local config = {
  ui_story_5031_50310101_1_dialog_content = "¡Damas, caballeros e invitados de todos los ámbitos de la vida! Bienvenido a <color=#FFB400>El ilusionista y el circo del viejo Bill</color>! Me llamo <color=#FFB400>Rainbow</color>, ¡y seré su anfitrión para el programa de esta noche!",
  ui_story_5031_50310101_2_dialog_content = "Todos los que se nos han unido a bordo del Emerald esta espléndida velada son los invitados más distinguidos de nuestro circo.",
  ui_story_5031_50310101_3_dialog_content = "Por favor, deje sus preocupaciones a un lado y disfrute de nuestra maravillosa actuación.",
  ui_story_5031_50310101_4_dialog_content = "¡Las espectaculares actuaciones que ofrece Illusionist & Old Bill's Circus están destinadas a desafiar toda razón y superar tu imaginación más salvaje!",
  ui_story_5031_50310101_5_dialog_content = "¡Este momento mágico te pertenece a ti, a mí, al mundo entero!",
  ui_story_5031_50310101_6_dialog_content = "Sin más preámbulos, demos la bienvenida a nuestro primer acto: ¡las acrobacias de alto vuelo de tres hermanas que han dominado el arte del trapecio! Por favor, denle una calurosa bienvenida a Merylt—",
  ui_story_5031_50310101_7_dialog_content = "subli—",
  ui_story_5031_50310101_8_dialog_content = "Y Frimet—",
  ui_story_5031_50310101_9_dialog_content = "¡Mientras suben al escenario!",
  ui_story_5031_50310101_10_dialog_content = "U-uh, ¿Arcoiris...? ¿No se está reparando el equipo de trapecio en este momento?",
  ui_story_5031_50310101_11_dialog_content = "Sí, incluso nosotros no somos capaces de volar solos.",
  ui_story_5031_50310101_12_dialog_content = "Jejeje... En realidad, he estado entrenando con el hombre fuerte del circo por un tiempo.",
  ui_story_5031_50310101_13_dialog_content = "¡Incluso podría ser capaz de lanzarlos a ustedes dos por el aire yo solo!",
  ui_story_5031_50310101_14_dialog_content = "Q-Qué tal si no, eso es demasiado peligroso... Además, podría haber daños colaterales...",
  ui_story_5031_50310101_15_dialog_content = "Hola jefe, podrías poner unos centavos, ya sabes.",
  ui_story_5031_50310101_16_dialog_content = "¡No podemos hacer un ensayo general si nuestro equipo no está listo!",
  ui_story_5031_50310101_17_dialog_content = "Teniendo en cuenta lo talentosos que somos, ¡dudo que necesitemos ensayar!",
  ui_story_5031_50310101_18_dialog_content = "Subli... Esa no es una forma muy agradable de hablar con el maestro de ceremonias Jeno.",
  ui_story_5031_50310101_19_dialog_content = "¿Mmm? Estamos trabajando en ello mientras hablamos.",
  ui_story_5031_50310101_20_dialog_content = "Los suministros de Elvis finalmente llegaron. Están dando los toques finales a tu equipo ahora mismo.",
  ui_story_5031_50310101_21_dialog_content = "Si ustedes tres no tienen ganas de ensayar, sigan y busquen un lugar para descansar un poco.",
  ui_story_5031_50310101_22_dialog_content = "Rainbow, ve a buscar a ese extra que decía poder hablar con los animales y tráela.",
  ui_story_5031_50310101_23_dialog_content = "Ella puede reemplazar al domador de bestias que todavía está enfermo por comer hielo raspado.",
  ui_story_5031_50310101_24_dialog_content = "¡Entendido!",
  ui_story_5031_50310101_25_dialog_content = "¿Está lista, señorita Fia?",
  ui_story_5031_50310101_26_dialog_content = "¡J-Solo un minuto!",
  ui_story_5031_50310101_27_dialog_content = "¡Ven, Bica! ¡Por aquí, por favor!",
  ui_story_5031_50310101_28_dialog_content = "Hola.",
  ui_story_5031_50310101_29_dialog_content = "Como te dije, Bica. Salta y haz un salto mortal, ¿de acuerdo?",
  ui_story_5031_50310101_30_dialog_content = "¡Hola!",
  ui_story_5031_50310101_31_dialog_content = "¡Por favor Bica! Sólo por esta vez, ¿podrías escucharme? ¡Ese maestro de ceremonias de aspecto aterrador todavía está mirando!",
  ui_story_5031_50310101_32_dialog_content = "¡¡Hola!!",
  ui_story_5031_50310101_33_dialog_content = "¡Ay! Cálmate, me disculparé, ¡solo deja de morderme!",
  ui_story_5031_50310101_34_dialog_content = "¡¡Pará pará pará!!",
  ui_story_5031_50310101_35_dialog_content = "¿Qué está pasando allá arriba? Resuelve tus problemas fuera del escenario, ¡no interrumpas el ensayo!",
  ui_story_5031_50310101_36_dialog_content = "¡El maestro de ceremonias Jeno!",
  ui_story_5031_50310101_37_dialog_content = "¿Qué? ¿Tú y tu amiguito finalmente terminaron con la cháchara?",
  ui_story_5031_50310101_38_dialog_content = "¡No escuchará ni una palabra de lo que diga, maestro de ceremonias Jeno! ¡Se ha echado a perder por completo!",
  ui_story_5031_50310101_39_dialog_content = "¿Mimado podrido, dices?",
  ui_story_5031_50310101_40_dialog_content = "¡Así es! ¡Y me mordió muy fuerte justo ahora, también!",
  ui_story_5031_50310101_41_dialog_content = "Oh, eso es perfectamente normal.",
  ui_story_5031_50310101_42_dialog_content = "¡¿Normal?!",
  ui_story_5031_50310101_43_dialog_content = "Como parte del circo, tienen derecho a los mismos privilegios que los demás. Es decir, son libres de rechazar cualquier trabajo cuando no tienen ganas de trabajar.",
  ui_story_5031_50310101_44_dialog_content = "¡¿Qué?!",
  ui_story_5031_50310101_45_dialog_content = "¡Este circo no se parece en nada a los que he leído! ¡Ni siquiera cerca!",
  ui_story_5031_50310101_46_dialog_content = "Todos los circos en los libros tratan a sus animales con crueldad y usan el miedo para hacerlos actuar. ¿Quieres decirme que tu circo no hace eso?",
  ui_story_5031_50310101_47_dialog_content = "¿Y qué diablos te dio esa idea?",
  ui_story_5031_50310101_48_dialog_content = "Nunca he oído hablar de tales métodos... ¿Por qué yo, o cualquier otra persona, los lastimaría? Después de todo, no son solo nuestros compañeros artistas, sino nuestros queridos e importantes amigos.",
  ui_story_5031_50310101_49_dialog_content = "Basta con mirar a esta Bica, y su pelaje suave y esponjoso. ¿Por qué alguien lastimaría algo tan precioso?",
  ui_story_5031_50310101_50_dialog_content = "¡Hola!",
  ui_story_5031_50310101_51_dialog_content = "En cualquier caso, mi circo nunca maltrataría así a nuestros artistas animales. Ni ahora, ni nunca.",
  ui_story_5031_50310101_52_dialog_content = "Todos los domadores que vinieron antes que tú pudieron encontrar una manera de guiarlos a través de sus actuaciones. También tendrás que encontrar tu propio camino.",
  ui_story_5031_50310101_53_dialog_content = "¡¿Con quién crees que estás hablando?!",
  ui_story_5031_50310101_54_dialog_content = "*Sollozando* Te diré que mi nombre es Fia, ¡la mejor extrozoóloga del mundo! ¡Mi conexión con las bestias maravillosas es más fuerte que la de cualquier otra persona!",
  ui_story_5031_50310101_55_dialog_content = "¿Cómo...? ¿Cómo podría perder...?",
  ui_story_5031_50310101_56_dialog_content = "No te preocupes, PlayerName. Un espectáculo de ballet no es un desafío para mí.",
  ui_story_5031_50310101_57_dialog_content = "Nunca pensé que llegaría a verte bailar ballet, Carleen.",
  ui_story_5031_50310101_58_dialog_content = "En el Coloso, escuché a otros aurorianos de Lumopolis hablar sobre tus impresionantes habilidades de ballet. ¡Alguien dijo una vez que incluso dejaste boquiabierto a un instructor profesional con tu actuación!",
  ui_story_5031_50310101_59_dialog_content = "¿Es eso cierto? Si es así, ¡no puedo evitar sentirme emocionado de verlo también!",
  ui_story_5031_50310101_60_dialog_content = "¡¡PlayerName!!",
  ui_story_5031_50310101_61_dialog_content = "fia? ¿No se supone que deberías estar practicando tu actuación de domesticación de bestias? ¿Qué estás haciendo aquí?",
  ui_story_5031_50310101_62_dialog_content = "Wah, wah... ¡Esos pequeños monstruos podridos me están volviendo loco! ¡No escuchan porque se les permite no trabajar cuando les da la gana!",
  ui_story_5031_50310101_63_dialog_content = "Cuando pienso en eso... y en cómo mi propio maestro me da órdenes... yo... yo... ¡¡¡Waaaaaaah!!!",
  ui_story_5031_50310101_64_dialog_content = "H-Oye, ahora! No llores, Fía...",
  ui_story_5031_50310101_65_dialog_content = "Se supone que eres el mejor extrozoólogo del mundo, ¿recuerdas?",
  ui_story_5031_50310101_66_dialog_content = "¡Yo sé eso! Entonces, ¿por qué la \"extrozoóloga más grande del mundo\" todavía tiene que trabajar todo el día cumpliendo las órdenes de su maestro?",
  ui_story_5031_50310101_67_dialog_content = "Intenta no pensar en ello, ¿de acuerdo? ¿Recuerdas la forma en que normalmente te burlas de mí? ¡Necesitas ese tipo de energía ahora mismo!",
  ui_story_5031_50310101_68_dialog_content = "¿¡QUÉ!?",
  ui_story_5031_50310101_69_dialog_content = "Bueno, quiero decir... ¿Recuerdas todas esas dificultades que superamos juntos? ¡Todo fue para realizar tu mayor sueño!",
  ui_story_5031_50310101_70_dialog_content = "Wah... Mi mayor sueño... y las dificultades que superamos...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>Justo después de llegar a Harbor City</color>",
  ui_story_5031_50310101_72_dialog_content = "Gracias por invitar Vice y yo a Harbor City, Carleen.",
  ui_story_5031_50310101_73_dialog_content = "Este lugar es realmente agradable, ¿no? Tan tranquilo y pacífico... ¡Un lugar perfecto para descansar y relajarse!",
  ui_story_5031_50310101_74_dialog_content = "¡Estoy tan contenta de que todos puedan venir también!",
  ui_story_5031_50310101_75_dialog_content = "De nada. Todo el mundo ha estado trabajando muy duro últimamente, así que pensé que a todos nos vendría bien un pequeño descanso para recuperar nuestros cuerpos y mentes.",
  ui_story_5031_50310101_76_dialog_content = "Era solo una niña la última vez que vine a Harbor City, pero de todos modos me dejó una profunda impresión.",
  ui_story_5031_50310101_77_dialog_content = "Sin embargo, nunca pensé que este lugar prosperaría tanto. El actual laird de la ciudad debe ser un líder bastante sabio.",
  ui_story_5031_50310101_78_dialog_content = "<size=33>Te encontré...</size>",
  ui_story_5031_50310101_79_dialog_content = "¿Crees que es algo como el Señor Schwartz?",
  ui_story_5031_50310101_80_dialog_content = "Ver la expresión feliz en el rostro de todos aquí... Realmente me hace preguntarme qué tipo de persona está a cargo aquí.",
  ui_story_5031_50310101_81_dialog_content = "Yo... no creo que los dos sean tan similares.",
  ui_story_5031_50310101_82_dialog_content = "Por cortesía, deberíamos hacerle una visita al laird de la ciudad ahora que estamos aquí.",
  ui_story_5031_50310101_83_dialog_content = "Vi un cartel en la calle hace un momento, decía algo sobre un circo y un carnaval a bordo de uno de los grandes cruceros.",
  ui_story_5031_50310101_84_dialog_content = "También podríamos preguntarle al laird de la ciudad más sobre eso.",
  ui_story_5031_50310101_85_dialog_content = "Si estamos aquí para relajarnos, ¡entonces esta es una excelente manera de comenzar! ¡Una verdadera experiencia de \"vacaciones de verano\"!",
  ui_story_5031_50310101_86_dialog_content = "¡Sí! ¡Tampoco me importaría preguntar qué más hacer aquí en Harbor City! ¡O qué tipo de delicias ofrecen!",
  ui_story_5031_50310101_87_dialog_content = "Vice Apenas puede contener su emoción... Supongo que realmente ha pasado demasiado tiempo desde que nos tomamos un descanso.",
  ui_story_5031_50310101_88_dialog_content = "<size=33>Objetivo bloqueado—¡PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "Bueno, ¿qué estamos esperando? Vamos-<size=50>¡AY!</size>",
  ui_story_5031_50310101_90_dialog_content = "¡Ay, ay! ¡Mi espalda!",
  ui_story_5031_50310101_91_dialog_content = "(Espera, esto parece terriblemente familiar...)",
  ui_story_5031_50310101_92_dialog_content = "¡Quédate atrás o pediré ayuda! ¡Lo digo en serio!",
  ui_story_5031_50310101_93_dialog_content = "Vamos-",
  ui_story_5031_50310101_94_option_content = "Fuerza... ¡Ay!",
  ui_story_5031_50310101_95_dialog_content = "¡¡Mi espalda!!",
  ui_story_5031_50310101_96_dialog_content = "¡Lo, lo, lo!",
  ui_story_5031_50310101_97_dialog_content = "Buen trabajo, Kyllo. ¡Vale, retírate por el bosque como estaba previsto!",
  ui_story_5031_50310101_98_dialog_content = "Pero yo solo... Mira, solo quiero un amigo.",
  ui_story_5031_50310101_99_dialog_content = "Lo...",
  ui_story_5031_50310101_100_dialog_content = "Todo el mundo dice que solo puedo entablar amistad con bestias maravillosas. Solo quería probar que no era cierto, y que también puedo hacerme amigo de Aurorianos y Caelestitas...",
  ui_story_5031_50310101_101_dialog_content = "Jejeje... Oye, PlayerName, ¡esto te convierte en mi primer amigo!",
  ui_story_5031_50310101_102_dialog_content = "¡Estoy tan feliz de que seas mi amigo, PlayerName!",
  ui_story_5031_50310101_103_dialog_content = "¡Mira, Maestro! ¡Hice un amigo!",
  ui_story_5031_50310101_104_dialog_content = "¡¡A-Así que realmente eres tú, Fia!!",
  ui_story_5031_50310101_105_dialog_content = "¡¿Por qué me atacaste desde ese bote de basura?!",
  ui_story_5031_50310101_106_dialog_content = "¡Jejeje! ¡Te tengo, PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "¿Fia?",
  ui_story_5031_50310101_108_dialog_content = "Sí, esta es Fia. No te preocupes por ella, así es ella.",
  ui_story_5031_50310101_109_dialog_content = "¿Así que este es el pequeño extrozoólogo con el que te encontraste antes?",
  ui_story_5031_50310101_110_dialog_content = "He oído hablar de ellos y de su campo de estudio, pero nunca esperé encontrarme con uno tan joven.",
  ui_story_5031_50310101_111_dialog_content = "Ha pasado un tiempo, Fia.",
  ui_story_5031_50310101_112_dialog_content = "Hola, Vice! ¡Mucho tiempo sin verlo!",
  ui_story_5031_50310101_113_dialog_content = "Permítame presentarme, señorita. Carleen. ¡Mi nombre es Fia y soy la extrozoóloga número uno en todo el mundo!",
  ui_story_5031_50310101_114_dialog_content = "O al menos lo seré algún día. Mi aprendizaje acaba de terminar, así que todavía tengo mucho espacio para mejorar. Si te causo algún problema en el futuro, ¡intenta ser paciente conmigo!",
  ui_story_5031_50310101_115_dialog_content = "Un placer conocerte. soy Carleen de Lumópolis. Sabes, me recuerdas mucho a Raphael.",
  ui_story_5031_50310101_116_dialog_content = "Debería presentarte cuando surja la oportunidad. Me imagino que ustedes dos se llevarán muy bien.",
  ui_story_5031_50310101_117_dialog_content = "Espera un segundo...",
  ui_story_5031_50310101_118_dialog_content = "¿Por qué estás actuando tan lindo e inocente, de repente?",
  ui_story_5031_50310101_119_dialog_content = "¿De qué estás hablando, PlayerName? Siempre soy así de dulce, ¿no? No es agradable decir algo así, ¿sabes?",
  ui_story_5031_50310101_120_dialog_content = "Sí, claro... A ver cuánto aguantas esta vez, Fia.",
  ui_story_5031_50310101_121_dialog_content = "De todos modos, ¿qué estás haciendo aquí en primer lugar? ¿Y dónde está Kyllo?",
  ui_story_5031_50310101_122_dialog_content = "¡Shhh! ¡No tan alto! Si quieres saberlo, Kyllo y yo estamos en una <color=#FFB400>misión secreta</color>. ¡Órdenes del maestro!",
  ui_story_5031_50310101_123_dialog_content = "¡Kyllo está investigando las aguas cercanas mientras hablamos!",
  ui_story_5031_50310101_124_dialog_content = "\"Misión secreta\"? Él no te envió a una búsqueda inútil de nuevo, ¿verdad?",
  ui_story_5031_50310101_125_dialog_content = "Además... ¡Kyllo estaba grandioso la última vez que los vi, muchachos! ¿No crees que llamará demasiado la atención?",
  ui_story_5031_50310101_126_dialog_content = "¡Ja! ¡Esa era su forma gigante! Desde entonces, Kyllo ha dominado el arte de cambiar de forma, ¿sabes?",
  ui_story_5031_50310101_127_dialog_content = "El Maestro dijo que con suficiente entrenamiento... ¡incluso podría alcanzar una forma humana!",
  ui_story_5031_50310101_128_dialog_content = "Eso... suena un poco aterrador, para ser honesto.",
  ui_story_5031_50310101_129_dialog_content = "¡No tengas miedo! ¡No hay nada que temer, siempre y cuando no hagas enojar a Kyllo!",
  ui_story_5031_50310101_130_dialog_content = "¡Pero basta de Kyllo! La misión que nos ocupa es de vital importancia, y tiene que ver con una <color=#FFB400>exótico</color> bestia maravillosa!",
  ui_story_5031_50310101_131_dialog_content = "Erm... No tenía la intención de escuchar a escondidas, de ninguna manera...",
  ui_story_5031_50310101_132_dialog_content = "¿Pero no crees que deberías bajar la voz, Fia?",
  ui_story_5031_50310101_133_dialog_content = "Además, ¿es seguro asumir que la razón por la que buscaste a PlayerName es para reclutarlo para tu \"misión secreta\"?",
  ui_story_5031_50310101_134_dialog_content = "¡Vaya! Supongo que estaba siendo un poco ruidoso, ¿eh?",
  ui_story_5031_50310101_135_dialog_content = "Bueno, dado que ustedes dos son amigos cercanos de PlayerName, creo que puedo confiarles los detalles de todos modos.",
  ui_story_5031_50310101_136_dialog_content = "Ahora, déjame explicarte la situación tan claramente como pueda.",
  ui_story_5031_50310101_137_dialog_content = "Todo empezó hace unos días...",
  ui_story_5031_50310101_138_dialog_content = "¡Quéaaa! ciudad puerto? ¡¿En realidad?!",
  ui_story_5031_50310101_139_dialog_content = "¡Guau! Escuché que el paisaje es increíble allí, ¡y que también hay mucha comida sabrosa!",
  ui_story_5031_50310101_140_dialog_content = "¡Nunca supe que te importaba tanto, Maestro! Enviándome de vacaciones después de todo el trabajo duro que he puesto...",
  ui_story_5031_50310101_141_dialog_content = "Las playas allí son bastante famosas, ahora que recuerdo. ¡Tengo que ir a elegir un traje de baño!",
  ui_story_5031_50310101_142_dialog_content = "Te estás adelantando terriblemente, ¿sabes?",
  ui_story_5031_50310101_143_dialog_content = "Si fuera un viaje tan agradable, mis maletas ya estarían hechas.",
  ui_story_5031_50310101_144_dialog_content = "Te envío a una tarea, Fia, no de vacaciones.",
  ui_story_5031_50310101_145_dialog_content = "Aquí hay algo de dinero para los gastos de viaje. Ponerse en marcha.",
  ui_story_5031_50310101_146_dialog_content = "¡Oye! ¡¿Qué se supone que debo hacer con monedas como esta?!",
  ui_story_5031_50310101_147_dialog_content = "¡E-Espere, Maestro! ¡¿A dónde vas?!",
  ui_story_5031_50310101_148_dialog_content = "Grrr... ¡Debería haberlo sabido! ¡Ese bueno para nada maestro mío nunca sería tan amable!",
  ui_story_5031_50310101_149_dialog_content = "Uh... ¿Crees que puedes llegar al punto de la historia, Fia? Creo que hemos oído suficiente sobre tu maestro...",
  ui_story_5031_50310101_150_dialog_content = "¡Estoy llegando a eso!",
  ui_story_5031_50310101_151_dialog_content = "Ejem... El objetivo de nuestra misión es una bestia maravillosa conocida como <color=#FFB400>ballenanube</color>.",
  ui_story_5031_50310101_152_dialog_content = "Mi maestro ha estado rastreando su Lumina especial desde hace algún tiempo. Hay señales de que ha llegado a las aguas de Harbor City.",
  ui_story_5031_50310101_153_dialog_content = "Pero después de que llegamos, el Lumina desapareció repentinamente...",
  ui_story_5031_50310101_154_dialog_content = "Mi teoría es que debido a que se desvaneció tan repentina y completamente, la Ballena Nube no debe haber salido de Harbor City... ¡Más bien, algo debe haberle sucedido!",
  ui_story_5031_50310101_155_dialog_content = "Ya veo... Eso suena siniestro, de hecho.",
  ui_story_5031_50310101_156_dialog_content = "No es broma, y lo que es más... Mi maestro dice que el poder de este Cloudwhale es incluso mayor que el de un Drakolion.",
  ui_story_5031_50310101_157_dialog_content = "Las leyendas dicen que su poder hace que los Eclipsites se encojan de miedo, y que su Lumina puede disipar incluso el Darkflow más espeso.",
  ui_story_5031_50310101_158_dialog_content = "También se dice que Cloudwhale tiene una vida extremadamente larga, por lo que es muy poco probable que haya muerto por causas naturales.",
  ui_story_5031_50310101_159_dialog_content = "Teniendo en cuenta todo esto, mi maestro está preocupado de que haya caído en las manos equivocadas.",
  ui_story_5031_50310101_160_dialog_content = "La ballena nubosa es dócil por naturaleza, pero si las personas equivocadas hacen un mal uso de su poder, los resultados podrían ser catastróficos...",
  ui_story_5031_50310101_161_dialog_content = "Si todo es como dices... entonces no podemos permitirnos quedarnos de brazos cruzados.",
  ui_story_5031_50310101_162_dialog_content = "¿Tienes alguna pista sobre su paradero?",
  ui_story_5031_50310101_163_dialog_content = "Hmm... ¡Ninguna en absoluto! Después de que mi maestro me dejó esta tarea, se fue sin decir una palabra más...",
  ui_story_5031_50310101_164_dialog_content = "¿Así que habías estado deambulando sin rumbo por Harbor City todo este tiempo hasta que encontraste mi rastro? ¿Entonces me acabas de tender una emboscada aquí?",
  ui_story_5031_50310101_165_dialog_content = "¡Has dado justo en el clavo, PlayerName! No solo eso, sino que el dinero que el Maestro me dio para los gastos de viaje está casi gastado...",
  ui_story_5031_50310101_166_dialog_content = "¡No sé qué hacer si no apareces, PlayerName!",
  ui_story_5031_50310101_167_dialog_content = "Lo sabía.",
  ui_story_5031_50310101_168_dialog_content = "¿Por qué no empezamos reuniendo información? Íbamos de camino a visitar al laird de la ciudad.",
  ui_story_5031_50310101_169_dialog_content = "Él podría saber una o dos cosas sobre la situación.",
  ui_story_5031_50310101_170_dialog_content = "¡De acuerdo! yo escucharia Carleen. ¡Vamos!",
  ui_story_5031_50310101_171_dialog_content = "¡Oye! ¿Por qué apresurarse, Fia? ¿Sabes siquiera a dónde vas?",
  ui_story_5031_50310101_172_dialog_content = "Está realmente emocionada, ¿no es así?",
  ui_story_5031_50310201_1_dialog_content = "Terrateniente <color=#FFB400>Elvis</color>, los soldados leales a usted están listos ahora.",
  ui_story_5031_50310201_2_dialog_content = "Las cosas están procediendo tal como lo planeó, señor. Usaremos el transporte de suministros y fuegos artificiales a Emerald como tapadera.",
  ui_story_5031_50310201_3_dialog_content = "Sí, ya veo.",
  ui_story_5031_50310201_4_dialog_content = "Bien hecho, Capitán Patou. Tal vez realmente eres el único en quien puedo confiar esta vez...",
  ui_story_5031_50310201_5_dialog_content = "Como usted dice, señor. Por favor, déjame el resto a mí. Ha sido un gran honor servir a mi laird.",
  ui_story_5031_50310201_6_dialog_content = "Por desgracia... Si hubiera más tiempo para esperar, no te pondría en tal riesgo.",
  ui_story_5031_50310201_7_dialog_content = "¡Laird Elvis! ¡Capitán Patou! ¡Perdona la intrusión!",
  ui_story_5031_50310201_8_dialog_content = "Qué grosero... ¿Pensé que había dejado perfectamente claro que nadie puede entrar?",
  ui_story_5031_50310201_9_dialog_content = "S-Sí, Capitán. Por favor, perdóname, pero un noble ha venido de visita...",
  ui_story_5031_50310201_10_dialog_content = "¿Qué noble? ¡Compórtate, soldado! Estás al servicio de la Casa Modali, ¡ahora actúa como tal!",
  ui_story_5031_50310201_11_dialog_content = "¡Comprendido! yo-es dama Carleen¡La princesa de Lumopolis, señor!",
  ui_story_5031_50310201_12_dialog_content = "¿Qué? Princesa Carleen de Lumopolis, dices?",
  ui_story_5031_50310201_13_dialog_content = "De acuerdo a Carleen, Harbor City quedó bajo la jurisdicción y protección oficial de Lumopolis justo antes de la Crisis de Darkover.",
  ui_story_5031_50310201_14_dialog_content = "¿Eso significa que confiaron en su propia fuerza para defender su hogar antes de eso?",
  ui_story_5031_50310201_15_dialog_content = "Los documentos históricos afirman que Harbor City alguna vez estuvo repleta de eclipses. Esos desafortunados residentes lucharon día y noche para evitar que cayera bajo el flagelo de Eclipsite.",
  ui_story_5031_50310201_16_dialog_content = "A lo largo de la prolongada batalla, los gobernantes de House <color=#FFB400>Modali</color>, que poseía una inmensa Lumina, aliada con otras potencias.",
  ui_story_5031_50310201_17_dialog_content = "Después de innumerables y sangrientas batallas, finalmente pudieron expulsar por completo a esos invasores.",
  ui_story_5031_50310201_18_dialog_content = "Err...",
  ui_story_5031_50310201_19_dialog_content = "Bendecido por el <color=#FFB400>Dios de luz</color>, esta ciudad rara vez ha sido perturbada por eclipses desde entonces.",
  ui_story_5031_50310201_20_dialog_content = "La gente ahora vive sus vidas en paz y la economía ha florecido significativamente.",
  ui_story_5031_50310201_21_dialog_content = "Me honra que conozca tan bien la historia de Harbor City, Su Alteza.",
  ui_story_5031_50310201_22_dialog_content = "También estoy agradecido con usted y con Lumopolis por su generosa protección. Después de todo, nunca habríamos sobrevivido a la Crisis de Darkover dependiendo de la <color=#FFB400>Bendición del Dios de la Luz</color> solo.",
  ui_story_5031_50310201_23_dialog_content = "Soy Elvis Modali, descendiente de la Casa Modali y laird de Harbor City.",
  ui_story_5031_50310201_24_dialog_content = "(Extraño... ¿Por qué la Lumina alrededor de este hombre es tan débil?)",
  ui_story_5031_50310201_25_dialog_content = "Saludos, Laird Elvis. Rezo para que nuestra visita no le haya causado demasiadas molestias.",
  ui_story_5031_50310201_26_dialog_content = "Por supuesto que no, Su Alteza. Ojalá me hubieras enviado un mensaje antes, para poder recibirte adecuadamente a ti y a tus compañeros.",
  ui_story_5031_50310201_27_dialog_content = "Eso no será necesario, ya que esperábamos verlos sin la fanfarria ni las formalidades habituales. Por favor, no seas particular con nosotros.",
  ui_story_5031_50310201_28_dialog_content = "Después de todo, no hemos venido a Harbor City como delegados de ningún tipo, sino como viajeros ordinarios de vacaciones.",
  ui_story_5031_50310201_29_dialog_content = "Tenga la seguridad, Su Alteza, entiendo completamente su difícil situación. ¿Puedo suponer que estos dos compañeros suyos no son otros que la Srta. Vice y la legendaria Caelestite?",
  ui_story_5031_50310201_30_dialog_content = "Saludos, soy PlayerName.",
  ui_story_5031_50310201_31_dialog_content = "Y yo soy Vice, Laird Elvis. Aunque nunca esperé que reconocieras a PlayerName, y mucho menos a mí.",
  ui_story_5031_50310201_32_dialog_content = "U-Um...!",
  ui_story_5031_50310201_33_dialog_content = "¿Vaya? ¿Y quién podría ser este?",
  ui_story_5031_50310201_34_dialog_content = "H-Hola! ¡Mi nombre es Fia! Soy un extrozoólogo profesional, además de amigo de PlayerName, Vice, y Carleen!",
  ui_story_5031_50310201_35_dialog_content = "¿Un extrozoólogo? Jeje, ya veo... Un placer conocerla, señorita Fia.",
  ui_story_5031_50310201_36_dialog_content = "He preparado un banquete. Como laird de Harbor City, será un honor que me acompañes a comer.",
  ui_story_5031_50310201_37_dialog_content = "Ya veo... ¿Y estás bastante interesado en el evento que se lleva a cabo a bordo del <color=#FFB400>Esmeralda</color>, Señorita Vice?",
  ui_story_5031_50310201_38_dialog_content = "En realidad, fui yo quien invitó <color=#FFB400>el ilusionista y el circo del viejo bill</color> y la Esmeralda a Harbor City.",
  ui_story_5031_50310201_39_dialog_content = "Mi esperanza es que puedan brindar una experiencia inolvidable a la gente de mi ciudad este verano.",
  ui_story_5031_50310201_40_dialog_content = "¿Todo el barco pertenece al circo? Seguro que tiene un sentimiento romántico...",
  ui_story_5031_50310201_41_dialog_content = "Por cierto. Si usted y sus acompañantes están interesados, siempre puede considerar participar en las festividades.",
  ui_story_5031_50310201_42_dialog_content = "El maestro de ceremonias es un amigo mío de la infancia. Aunque no nos hemos visto durante bastante tiempo, es tan capaz como digno de confianza.",
  ui_story_5031_50310201_43_dialog_content = "No tengo ninguna duda de que brindará el mejor entretenimiento para toda la ciudad.",
  ui_story_5031_50310201_44_dialog_content = "Ah... ¡El crucero!",
  ui_story_5031_50310201_45_dialog_content = "¡Disculpe! ¿Podría uno de sus amigos mostrarnos el interior del barco, Laird Elvis?",
  ui_story_5031_50310201_46_dialog_content = "¿Mmm?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>¡Fia! ¿Qué clase de pedido extraño es ese?</size>",
  ui_story_5031_50310201_48_dialog_content = "Acabo de recordar que Kyllo me dijo que un extraño y enorme barco había atracado en Harbour City no hace mucho.",
  ui_story_5031_50310201_49_dialog_content = "Si el Cloudwhale desapareciera repentinamente, ¡podría haberse mantenido dentro de ese tipo de barco!",
  ui_story_5031_50310201_50_dialog_content = "Mis disculpas, pero me temo que no puedo concederle esta petición.",
  ui_story_5031_50310201_51_dialog_content = "Er... ¿Por qué?",
  ui_story_5031_50310201_52_dialog_content = "Yo mismo no estoy seguro de los detalles, pero esto se refiere a una de las reglas del circo.",
  ui_story_5031_50310201_53_dialog_content = "Ayer, subí a bordo del barco para hablar con <color=#FFB400>Jeno</color>, el maestro de ceremonias, sobre el suministro de suministros a su compañía.",
  ui_story_5031_50310201_54_dialog_content = "Pensé que Jeno me daría un recorrido por las cabañas, pero solo estaba dispuesto a mostrarme hasta el corredor cuando discutíamos nuestro negocio.",
  ui_story_5031_50310201_55_dialog_content = "Por curiosidad, mencioné que deseaba ver el interior de este gran y maravilloso barco...",
  ui_story_5031_50310201_56_dialog_content = "Pero él me rechazó, afirmando que era su política que solo los miembros del circo podían adentrarse más en la cabina.",
  ui_story_5031_50310201_57_dialog_content = "Como amigo y socio comercial, esto fue lo más lejos que pude llegar. Me temo que la entrada para usted estará aún más fuera de discusión.",
  ui_story_5031_50310201_58_dialog_content = "¿Hay alguna razón en particular por la que le gustaría entrar en el barco? Tal vez pueda negociar con el maestro de ceremonias en tu nombre.",
  ui_story_5031_50310201_59_dialog_content = "En realidad, Fia era...",
  ui_story_5031_50310201_60_dialog_content = "¡Ajaja! ¡Eso también fue por curiosidad! Vengo de un lugar muy pequeño y nunca antes había visto el interior de un barco.",
  ui_story_5031_50310201_61_dialog_content = "<size=33>¡No lo olvides, estamos en una misión secreta! ¡No podemos derramar ninguna información sobre nuestro exótico objetivo!</size>",
  ui_story_5031_50310201_62_dialog_content = "Entiendo cómo debe sentirse, señorita Fia. Después de todo, los barcos tan grandes como el Emerald no son exactamente comunes, incluso en Harbour City.",
  ui_story_5031_50310201_63_dialog_content = "Estoy seguro de que usted tampoco está solo. Muchos asistentes al carnaval deben estar muriendo por saber más sobre el barco y lo que hay dentro.",
  ui_story_5031_50310201_64_dialog_content = "Bueno... Permíteme intentar hablar con Jeno una vez más.",
  ui_story_5031_50310201_65_dialog_content = "¿En serio? ¡Muchas gracias señor!",
  ui_story_5031_50310201_66_dialog_content = "Un placer, aunque por favor trate de no hacerse ilusiones demasiado altas. Jeno se apresuró a rechazar incluso a su patrocinador.",
  ui_story_5031_50310201_67_dialog_content = "Sin embargo, habrá muchas otras festividades para participar en la cubierta, como el concurso de cocina, el carnaval y el espectáculo circense.",
  ui_story_5031_50310201_68_dialog_content = "Creo que contribuirán mucho a satisfacer también su curiosidad, señorita Fia.",
  ui_story_5031_50310201_69_dialog_content = "*Tose*",
  ui_story_5031_50310201_70_dialog_content = "¡Señor!",
  ui_story_5031_50310201_71_dialog_content = "Estoy bien, Patou.",
  ui_story_5031_50310201_72_dialog_content = "Parece que en la emoción de Su Alteza y la visita de todos, olvidé por completo tomar mi medicina.",
  ui_story_5031_50310201_73_dialog_content = "Laird Elvis...",
  ui_story_5031_50310201_74_dialog_content = "Gracias por su amable hospitalidad.",
  ui_story_5031_50310201_75_dialog_content = "El honor es mío, Su Alteza. Espero que mi lapso momentáneo de salud no arruine su disfrute.",
  ui_story_5031_50310201_76_dialog_content = "De nada. Por favor, cuídese bien, Laird.",
  ui_story_5031_50310201_77_dialog_content = "Nos vamos a la Esmeralda en breve a ver el carnaval. Por favor, no te levantes por nuestro bien. Estaremos en nuestro camino.",
  ui_story_5031_50310201_78_dialog_content = "... Entiendo. Sin embargo, tengo que preparar un regalo para Su Alteza antes de partir hacia el Esmeralda más tarde.",
  ui_story_5031_50310201_79_dialog_content = "Es costumbre que los súbditos ofrezcan regalos a sus soberanos. Por favor, acéptelo amablemente, Su Alteza.",
  ui_story_5031_50310201_80_dialog_content = "Si insistes.",
  ui_story_5031_50310201_81_dialog_content = "Vengan todos. Es hora de ir.",
  ui_story_5031_50310201_82_dialog_content = "...",
  ui_story_5031_50310201_83_dialog_content = "Señor.",
  ui_story_5031_50310201_84_dialog_content = "Ordena a nuestros hombres que se preparen, Patou.",
  ui_story_5031_50310201_85_dialog_content = "Podría... ¿Podría Lumopolis haber descubierto nuestras acciones tan rápido?",
  ui_story_5031_50310201_86_dialog_content = "Creo que todavía es demasiado pronto para decirlo con certeza... Pero por ahora, debemos estar atentos a ellos.",
  ui_story_5031_50310201_87_dialog_content = "Pase lo que pase, el plan debe proceder hoy.",
  ui_story_5031_50310201_88_dialog_content = "Disculpe mi ignorancia, señor, pero ¿no puede simplemente pedirle ayuda al maestro de ceremonias Jeno?",
  ui_story_5031_50310201_89_dialog_content = "Como dijiste, él es tu amigo de la infancia.",
  ui_story_5031_50310201_90_dialog_content = "Las cosas no son tan simples, Patou. Nuestra historia compartida no significa necesariamente que pueda confiar en él.",
  ui_story_5031_50310201_91_dialog_content = "Después de todo, negó mi pedido de ver el interior de su nave sin dudarlo.",
  ui_story_5031_50310201_92_dialog_content = "De acuerdo con mis hallazgos, actualmente debe su lealtad a la <color=#FFB400>orden verdadero</color>.",
  ui_story_5031_50310201_93_dialog_content = "Si nuestro objetivo se revela debido a nuestra imprudencia... todo el plan podría desmoronarse en un instante.",
  ui_story_5031_50310201_94_dialog_content = "En este punto, no estoy seguro si puedo o no confiar en ese hombre, a quien una vez llamé \"amigo\"...",
  ui_story_5031_50310201_95_dialog_content = "Lo entiendo, señor. Déjamelo a mí.",
  ui_story_5031_50310201_96_dialog_content = "Muy bien. Continuaré investigando a Jeno para ver si sigue siendo la misma persona que una vez conocí...",
  ui_story_5031_50310201_97_dialog_content = "Laird Elvis parece una persona muy agradable, ¿eh? Nos recibió muy calurosamente y también fue amable con Vice y yo.",
  ui_story_5031_50310201_98_dialog_content = "Sí, parece mucho más amable que algunos de los nobles que hemos conocido antes. Él no se comporta con el mismo tipo de pretenciosidad que ellos.",
  ui_story_5031_50310201_99_dialog_content = "Por cierto. La Casa Modali es bastante diferente a muchas otras familias nobles. Son increíblemente protectores con su propia gente y también son amados por muchos.",
  ui_story_5031_50310201_100_dialog_content = "Cuando se trata de gobernar, su familia es una de las mejores, pero desafortunadamente...",
  ui_story_5031_50310201_101_dialog_content = "Ah... ¿Tiene algo que ver con lo débil que es su Lumina?",
  ui_story_5031_50310201_102_dialog_content = "Parece que tú también lo notaste. Cuando Elvis comenzó a toser incontrolablemente antes... bueno, digamos que no se debió a un resfriado común.",
  ui_story_5031_50310201_103_dialog_content = "Incluso la cicatriz en su rostro... Su enfermedad es conocida por otros como la <color=#FFB400>síndrome modal</color>.",
  ui_story_5031_50310201_104_dialog_content = "Entonces, ¿la cicatriz en su rostro se debe a su enfermedad? nunca lo hubiera imaginado...",
  ui_story_5031_50310201_105_dialog_content = "Entonces... ¿Es en serio?",
  ui_story_5031_50310201_106_dialog_content = "No entiendo mucho sobre la enfermedad más allá de su nombre, para ser honesto. Sólo llegué a saber de él de pasada, mientras estaba ocupado en mis estudios de historia.",
  ui_story_5031_50310201_107_dialog_content = "Cuando cedí a mi curiosidad, rápidamente descubrí que la información sobre el Síndrome de Modali y la familia misma era sorprendentemente escasa.",
  ui_story_5031_50310201_108_dialog_content = "Todo lo que aprendí es que esta enfermedad agota rápidamente el Lumina de las víctimas y evita que se recupere a niveles normales durante un período prolongado de tiempo.",
  ui_story_5031_50310201_109_dialog_content = "No es tan debilitante para aquellos con niveles de Lumina por encima del promedio, pero para otros... contraer la enfermedad de forma rápida y grave afecta su capacidad para llevar una vida normal.",
  ui_story_5031_50310201_110_dialog_content = "En casos extremos, la enfermedad puede incluso ser fatal.",
  ui_story_5031_50310201_111_dialog_content = "¡¿Es realmente tan malo?!",
  ui_story_5031_50310201_112_dialog_content = "Sí... Pero esta enfermedad es extremadamente única y solo ha aparecido en Harbor City. Como tal, los eruditos creen que de alguna manera está ligado a esta región.",
  ui_story_5031_50310201_113_dialog_content = "La gente de Harbor City, por otro lado, está completamente convencida de que la enfermedad es un símbolo de su <color=#FFB400>linaje heroico</color>.",
  ui_story_5031_50310201_114_dialog_content = "Dicen que sus ancestros, los que se defendieron de los Eclipsites en el pasado, cargaron con valentía y voluntad esta maldición por el bien de su gente.",
  ui_story_5031_50310201_115_dialog_content = "Como tal, sus descendientes también tienen la oportunidad de contraerlo.",
  ui_story_5031_50310201_116_dialog_content = "Afortunadamente, parece que los casos confirmados de esta enfermedad han ido disminuyendo gradualmente en los últimos años.",
  ui_story_5031_50310201_117_dialog_content = "Oh... ya veo, ya veo.",
  ui_story_5031_50310201_118_dialog_content = "No tienes que fingir que entendiste todo eso, ¿sabes?",
  ui_story_5031_50310201_119_dialog_content = "¡O-Claro que lo entendí! ¡Que sea joven no significa que sea tonto!",
  ui_story_5031_50310201_120_dialog_content = "En cualquier caso, creo que el laird entiende su propio destino mejor que nadie.",
  ui_story_5031_50310201_121_dialog_content = "Al igual que yo, ¡nací para ser el mejor extrozoólogo del mundo!",
  ui_story_5031_50310201_122_dialog_content = "Continuar con la gloria de innumerables generaciones pasadas... Debe ser una carga complicada y pesada de llevar.",
  ui_story_5031_50310201_123_dialog_content = "Como extraños, no creo que tengamos derecho a juzgar la situación en absoluto.",
  ui_story_5031_50310201_124_dialog_content = "Fia hace un muy buen punto.",
  ui_story_5031_50310201_125_dialog_content = "Sí, lo hace, aunque podría haber hecho lo mismo si no hubiera dicho nada también.",
  ui_story_5031_50310201_126_dialog_content = "Jeje! En cualquier caso, deberíamos centrarnos realmente en subir a bordo del Emerald y echar un vistazo. ¡Vamos!",
  ui_story_5031_50310201_127_dialog_content = "Date prisa y salva lo exótico. ¡Completa esta misión y tendré tiempo para jugar!",
  ui_story_5031_50310201_128_dialog_content = "¡Espera un segundo, Fia! ¿Qué te hace estar tan seguro de que podrás acceder al interior de la Esmeralda?",
  ui_story_5031_50310201_129_dialog_content = "Tendré que confiar en mi increíble encanto, ¿no?",
  ui_story_5031_50310201_130_dialog_content = "Qué \"encanto asombroso\"... Tendrías más suerte fingiendo ser un animalito y audicionando para el circo.",
  ui_story_5031_50310201_131_dialog_content = "¡Uh!",
  ui_story_5031_50310201_132_dialog_content = "Esa fue otra broma corta, ¿no?",
  ui_story_5031_50310201_133_dialog_content = "¡Ven aquí!",
  ui_story_5031_50310201_134_dialog_content = "¡E-Oye, eso dolió! ¡Deja de tirar tan fuerte, Fia!",
  ui_story_5031_50310201_135_dialog_content = "¡Vas directo al océano, gran idiota! ¡Kyllo puede lanzarte como una pelota, por lo que a mí respecta!",
  ui_story_5031_50310201_136_dialog_content = "¿Qué? ¿Estás llamando a Kyllo foca o algo así? ¡No creo que Kyllo apreciaría eso!",
  ui_story_5031_50310201_137_dialog_content = "¡No me importa!",
  ui_story_5031_50310201_138_dialog_content = "Vaya... Verlos discutir así de alguna manera me tranquiliza.",
  ui_story_5031_50310201_139_dialog_content = "Sí... Hace tiempo que no nos relajamos así.",
  ui_story_5031_50310201_140_dialog_content = "¡Espera!",
  ui_story_5031_50310201_141_dialog_content = "¡A-Muy bien, córtalo! Qué es, Carleen?",
  ui_story_5031_50310201_142_dialog_content = "Allá... ¡¿Qué hacen los Eclipsitos en esta orilla?!",
  ui_story_5031_50310201_143_dialog_content = "¡Prepárense para la batalla y manténganse en guardia, todos! Hay algo extraño en estos eclipses...",
  ui_story_5031_50310202_1_dialog_content = "Graah...",
  ui_story_5031_50310202_2_dialog_content = "¿Por qué estos eclipses eran tan débiles...?",
  ui_story_5031_50310202_3_dialog_content = "Mucho, ¿estás bien?",
  ui_story_5031_50310202_4_dialog_content = "Espera... E-Eres princesa Carleen! M-Mis disculpas si has resultado herido... ¡Fue por mi negligencia que esos Eclipsites sobrevivieron!",
  ui_story_5031_50310202_5_dialog_content = "No hay necesidad de entrar en pánico. No somos ciudadanos desarmados y somos perfectamente capaces de defendernos.",
  ui_story_5031_50310202_6_dialog_content = "No obstante, usted y sus hombres deben permanecer alerta en todo momento. El peligro podría estar al acecho en cada esquina.",
  ui_story_5031_50310202_7_dialog_content = "¡Comprendido! ¡Gracias por su guía, Su Alteza! ¡Aumentaremos nuestras patrullas e investigaremos el origen de estos eclipses!",
  ui_story_5031_50310202_8_dialog_content = "Muy bien, ahora manos a la obra, soldado.",
  ui_story_5031_50310202_9_dialog_content = "¡Si su Alteza!",
  ui_story_5031_50310202_10_dialog_content = "Eso fue genial, Carleen! ¡Te veías y sonabas como una reina!",
  ui_story_5031_50310202_11_dialog_content = "¡Por supuesto que lo hizo, Fia! Carleen es la hija del Señor de Lumopolis y, naturalmente, algún día será una gobernante sabia.",
  ui_story_5031_50310202_12_dialog_content = "G-Gracias... Pero todavía tengo mucho que aprender.",
  ui_story_5031_50310202_13_dialog_content = "Pero basta de eso. El Emerald está más adelante, así que sigamos adelante.",
  ui_story_5031_50310202_14_dialog_content = "Cualquiera que quiera participar en el concurso de cocina, ¡venga por aquí!",
  ui_story_5031_50310202_15_dialog_content = "Parece que estamos aquí, ¿eh? ¡Este lugar sí que está animado!",
  ui_story_5031_50310202_16_dialog_content = "Comencemos recopilando información primero, PlayerName.",
  ui_story_5031_50310202_17_dialog_content = "Sí, eso tiene sentido.",
  ui_story_5031_50310202_18_dialog_content = "Hola, ¿puedo preguntarte sobre el carnaval...?",
  ui_story_5031_50310202_19_dialog_content = "¡Yo! ¡Bienvenido al Circo del Ilusionista y del Viejo Bill!",
  ui_story_5031_50310202_20_dialog_content = "Parece que es la primera vez que ves nuestro circo, ¿verdad? ¡No hay necesidad de ser tímidos, chicos! ¡Justo por aquí!",
  ui_story_5031_50310202_21_dialog_content = "Simplemente no crees ningún problema a bordo del barco, ¿de acuerdo? No seré tan amable si empiezas a causar alboroto...",
  ui_story_5031_50310202_22_dialog_content = "¡Vamos, Meryl! El maestro de ceremonias Jeno nos envió aquí para dar la bienvenida a los invitados, ¡así que no holgazaneemos!",
  ui_story_5031_50310202_23_dialog_content = "Aquí Aquí. Parece que alguien va a entrar ahora, ¡y es justo tu tipo! ¿Por qué no me saludas, Merylt?",
  ui_story_5031_50310202_24_dialog_content = "¡Ah! Subli, no me presiones...",
  ui_story_5031_50310202_25_dialog_content = "Oye, seguro que se parece a él, ¿no? ¡Merylt, ve a echar un vistazo más de cerca!",
  ui_story_5031_50310202_26_dialog_content = "¿Eh? ¿Se parece a quién? ¿De qué están hablando ustedes dos?",
  ui_story_5031_50310202_27_dialog_content = "¡Se parece al tipo del cartel de Umbraton Daily! ¡El que Merylt guardó para sí misma!",
  ui_story_5031_50310202_28_dialog_content = "Eh... ¿De qué estás hablando exactamente?",
  ui_story_5031_50310202_29_dialog_content = "¡Espera, se parecen mucho! No eres ese Caelestite por casualidad, ¿verdad?",
  ui_story_5031_50310202_30_dialog_content = "S-Sí, en realidad lo soy... Pero, ¿cómo saben ustedes tres sobre mí?",
  ui_story_5031_50310202_31_dialog_content = "¡¡!!",
  ui_story_5031_50310202_32_dialog_content = "¿Por qué se escapa Merylt, Subli?",
  ui_story_5031_50310202_33_dialog_content = "¿Deberíamos detener a este tipo ahora?",
  ui_story_5031_50310202_34_dialog_content = "¡¿Q-Qué?!",
  ui_story_5031_50310202_35_dialog_content = "Jajaja, que divertido! Tómatelo con calma, Frimet. Dejémoslos a Rainbow. Por ahora, solo ve a buscar a Merylt, ¿de acuerdo?",
  ui_story_5031_50310202_36_dialog_content = "¡Oye! ¿Estás holgazaneando de nuevo?",
  ui_story_5031_50310202_37_dialog_content = "¡Perdón por eso, amigos! Esos tres solo están ayudando por el momento.",
  ui_story_5031_50310202_38_dialog_content = "Debes estar aquí para el carnaval, supongo.",
  ui_story_5031_50310202_39_dialog_content = "Permítame presentarme. ¡Soy Rainbow, el maestro de ceremonias del circo, enlace con el cliente, director de seguridad y aprendiz de ingeniero marino!",
  ui_story_5031_50310202_40_dialog_content = "E-Eso es un bocado...",
  ui_story_5031_50310202_41_dialog_content = "¡Jejeje! Es por eso que todos piensan que soy tan increíble, ¿sabes?",
  ui_story_5031_50310202_42_dialog_content = "¡Encantado de conocerte, Arcoiris! ¿Puedes decirme cómo entrar en la nave? ¡Ooh!",
  ui_story_5031_50310202_43_dialog_content = "¿Qué estás haciendo? ¿De verdad crees que te dejará entrar solo porque se lo pediste?",
  ui_story_5031_50310202_44_dialog_content = "P-Pero, ¿qué se supone que debemos hacer, entonces?",
  ui_story_5031_50310202_45_dialog_content = "Hola. Solo queríamos saber más sobre el carnaval y cómo disfrutarlo mejor.",
  ui_story_5031_50310202_46_dialog_content = "Bueno, el carnaval todavía se está preparando en este momento. Está bien pasar el rato en la cubierta y esperar la señal.",
  ui_story_5031_50310202_47_dialog_content = "Por ahora, los invito a todos a ver el concurso de cocina que se está organizando cerca.",
  ui_story_5031_50310202_48_dialog_content = "¡Un concurso feroz está a punto de tener lugar, y hay muchos puestos de comida maravillosos para visitar!",
  ui_story_5031_50310202_49_dialog_content = "¡Camina de esa manera, y no te lo perderás!",
  ui_story_5031_50310202_50_dialog_content = "Gracias por tu tiempo. Iremos a echar un vistazo.",
  ui_story_5031_50310202_51_dialog_content = "Esos miembros del circo eran bastante especiales, ¿no?",
  ui_story_5031_50310202_52_dialog_content = "Especialmente esas tres hermanas... Parecían muy interesadas en PlayerName.",
  ui_story_5031_50310202_53_dialog_content = "En realidad...? Prefiero no quedar atrapado con gente extraña...",
  ui_story_5031_50310202_54_dialog_content = "No puedo evitar pensar que las cosas se han vuelto demasiado locas a mi alrededor. Espero un poco de descanso y relajación.",
  ui_story_5031_50310202_55_dialog_content = "Mmm. ¿Qué tengo que hacer para entrar en esta nave?",
  ui_story_5031_50310202_56_dialog_content = "Realmente pensé que había convencido a esa amable señora.",
  ui_story_5031_50310202_57_dialog_content = "¿Así que no crees que un poco de demasiada honestidad te haría tirar por la borda?",
  ui_story_5031_50310202_58_dialog_content = "No olvides lo que dijo Elvis: el interior del barco está reservado para la gente del circo.",
  ui_story_5031_50310202_59_dialog_content = "El mejor lugar para que comencemos a buscar es sobre las cubiertas. Quién sabe... quizás encontremos algo.",
  ui_story_5031_50310202_60_dialog_content = "Espera un segundo... ese puesto un poco más adelante... Puedo distinguir algunas caras familiares allí.",
  ui_story_5031_50310202_61_dialog_content = "Es un placer presentar una de las mejores formas del mundo de disipar este feroz calor de verano.",
  ui_story_5031_50310202_62_dialog_content = "Incluyendo nuestro último sabor—<color=#FFB400>Brisa de la ciudad del puerto de edición limitada</color>.",
  ui_story_5031_50310202_63_dialog_content = "¡Recompensaremos aún más cualquier compra de diez tazas de hielo raspado con una bolsa térmica especial grabada con amor con una imagen de Caelestite!",
  ui_story_5031_50310202_64_dialog_content = "Muy bien. Sus diez tazas de hielo raspado y la bolsa térmica, hermosa dama.",
  ui_story_5031_50310202_65_dialog_content = "¡Soy yo quien inventó este estilo particular de hielo raspado! Y no puedo creer Kleken usé tu foto para la bolsa!",
  ui_story_5031_50310202_66_dialog_content = "Vice... Seguro que recuerdas que \"<color=#FFB400>Transferencia de Secreto Comercial</color>\"tú firmaste con Kleken ¿el año pasado?",
  ui_story_5031_50310202_67_dialog_content = "Mucho me temo que este es el resultado.",
  ui_story_5031_50310202_68_dialog_content = "Uh-oh... es demasiado dulce.",
  ui_story_5031_50310202_69_dialog_content = "No tiene la complejidad del hielo raspado de Vice.",
  ui_story_5031_50310202_70_dialog_content = "¡Yo también quisiera una taza!",
  ui_story_5031_50310202_71_dialog_content = "Oye, simplemente no puedes evitarlo, ¿verdad?",
  ui_story_5031_50310202_72_dialog_content = "Vice todavía está muy deprimida con su triste historia de transferencia de propiedad intelectual.",
  ui_story_5031_50310202_73_dialog_content = "Estoy totalmente de acuerdo con eso... Estoy feliz, sin importar cómo haya sucedido, que ahora todos tengan la oportunidad de disfrutar un delicioso hielo raspado y yo solo... solo quiero...",
  ui_story_5031_50310202_74_dialog_content = "Lo tendré Kleken transferir esa propiedad intelectual de nuevo a mí!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>Un rato después</color>",
  ui_story_5031_50310202_76_dialog_content = "¡Guau! Realmente helado.",
  ui_story_5031_50310202_77_dialog_content = "¡No lo tengas todo de una vez o te congelarás el cerebro!",
  ui_story_5031_50310202_78_dialog_content = "Es Vice todavía hablando con Kleken? ¿Están bien?",
  ui_story_5031_50310202_79_dialog_content = "¡PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "¿eh? ¿Qué es esa voz familiar?",
  ui_story_5031_50310202_81_dialog_content = "PlayerName, ¡no puedo creer que realmente seas tú!",
  ui_story_5031_50310202_82_dialog_content = "Fleur, ¿qué estás haciendo aquí?",
  ui_story_5031_50310202_83_dialog_content = "¿Vaya? ¿No estás aquí para participar en el Sorcery Pot Championship? Es una cosita de festival de competencia gourmet. Debería empezar muy pronto.",
  ui_story_5031_50310202_84_dialog_content = "Y también me gustaría agradecerte por tu ayuda con esos panes horneados en ese entonces.",
  ui_story_5031_50310202_85_dialog_content = "Tuve un poco de pensar. Y he decidido participar en el concurso. No hay mejor manera de mejorar y mostrar mi estilo único.",
  ui_story_5031_50310202_86_dialog_content = "Eh, de nada. Tengo que decir que no había oído hablar de este concurso gourmet hasta ahora. ¿Cómo se llamaba de nuevo? \"<color=#FFB400>Olla de brujería</color>\"?",
  ui_story_5031_50310202_87_dialog_content = "¡Esperar! ¿Es eso una referencia a ese chico Iron Chef de Rediesel Desert?",
  ui_story_5031_50310202_88_dialog_content = "¿El conocedor de Eclipsite, tío Johnny? ¡Lo mismísimo! ¡Y ese Olla Hechicera que usa!",
  ui_story_5031_50310202_89_dialog_content = "Aférrate. ¿Quién es este personaje del \"Tío Johnny\", Carleen?",
  ui_story_5031_50310202_90_dialog_content = "Solo un crítico gastronómico muy popular que vive en el desierto de Rediesel. No sé mucho más que eso.",
  ui_story_5031_50310202_91_dialog_content = "¿Qué te tiene tan metido en esto?",
  ui_story_5031_50310202_92_dialog_content = "¡Él no es cualquier viejo crítico de restaurantes de dos bits! ¡Él inventó los platos más famosos de todo este continente en esa olla!",
  ui_story_5031_50310202_93_dialog_content = "D-¿Crees que el tío Johnny participará en el campeonato él mismo?",
  ui_story_5031_50310202_94_dialog_content = "Oh, no, un chef de su estatura seguramente tiene mejores cosas que hacer que... espera, ¿también está en juego su olla de autor?",
  ui_story_5031_50310202_95_dialog_content = "¡Exactamente correcto! ¡El ganador del primer premio recibe nada menos que el propio Sorcery Pot del masterchef!",
  ui_story_5031_50310202_96_dialog_content = "No tengo idea de si el hombre mismo estará allí, ¡pero estoy seguro de que un premio como ese atraerá a estrellas de todo el mundo!",
  ui_story_5031_50310202_97_dialog_content = "¡Y yo quiero unirme! ¿Yo puedo? ¿Me dejarán?",
  ui_story_5031_50310202_98_dialog_content = "¡Pon esa olla mágica en manos de Vice y será maravilloso para todos nosotros en el Coloso!",
  ui_story_5031_50310202_99_dialog_content = "¡Vaya! Pero no te vuelvas loco conmigo, PlayerName. ¿Quién sabe lo que va a pasar?",
  ui_story_5031_50310202_100_dialog_content = "Lo siento, Fleur. Solo necesito hablar con PlayerName en voz baja.",
  ui_story_5031_50310202_101_dialog_content = "No seas tan insistente, Carleen, Fía.",
  ui_story_5031_50310202_102_dialog_content = "¡Oye! Fleur, ¡Espérame! ¡Estoy volviendo!",
  ui_story_5031_50310202_103_dialog_content = "Bien. Estaré esperando.",
  ui_story_5031_50310202_104_dialog_content = "¡Te estaré esperando aquí mismo, PlayerName!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName, no nos adelantemos, ¿de acuerdo?",
  ui_story_5031_50310202_106_dialog_content = "Lo siento. Supongo que me excedí un poco allí.",
  ui_story_5031_50310202_107_dialog_content = "Tu lo dijiste. Creo que alguien realmente quiere tener en sus manos ese bote mágico, PlayerName.",
  ui_story_5031_50310202_108_dialog_content = "¿Qué estás haciendo aquí? ¡Finalmente le encontré!",
  ui_story_5031_50310202_109_dialog_content = "Vice? ¿Cómo fue su discusión con Kleken ¿Vamos?",
  ui_story_5031_50310202_110_dialog_content = "¡Un miserable fracaso! ¡Mi único consuelo es que me las arreglé para conseguir unas cuantas tazas de hielo raspado gratis para todos ustedes!",
  ui_story_5031_50310202_111_dialog_content = "¡Tengan en ellos, amigos! ¡Deja que estos postres helados limpien la sensación de fracaso! *comiendo*",
  ui_story_5031_50310202_112_dialog_content = "no creo Vice Lo pasé muy bien... *Munching*",
  ui_story_5031_50310202_113_dialog_content = "Argh. ¡Cerebro congelado!",
  ui_story_5031_50310202_114_dialog_content = "Eso es lo que pasa cuando te lo comes todo de una vez, ya sabes. Ay... yo también lo tengo.",
  ui_story_5031_50310202_115_dialog_content = "¿eh? ¿Ves esa escalera de allí apuntando hacia abajo? ¿No me digas que esa fue la entrada a las cubiertas inferiores todo el tiempo?",
  ui_story_5031_50310202_116_dialog_content = "¿eh? Déjame echar un vistazo.",
  ui_story_5031_50310202_117_dialog_content = "Creo que realmente es... ¿Bueno? ¿Deberíamos bajar?",
  ui_story_5031_50310202_118_dialog_content = "¿Quiere decir que no ve un problema con el allanamiento de morada?",
  ui_story_5031_50310202_119_dialog_content = "Si estamos hablando de los mismos malhechores que secuestraron a Cloudwhale, no van a desplegar exactamente la alfombra de bienvenida.",
  ui_story_5031_50310202_120_dialog_content = "Al final del día, tenemos que intentarlo.",
  ui_story_5031_50310202_121_dialog_content = "TOC Toc. Perdón por la intrusión. ¡Por favor déjame entrar!",
  ui_story_5031_50310202_122_dialog_content = "¿Literalmente dijiste \"toc-toc\"?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5031_50310202_124_dialog_content = "¡Ahh!",
  ui_story_5031_50310202_125_dialog_content = "¿Quién es?",
  ui_story_5031_50310202_126_dialog_content = "¡Oh lo siento! ¡Compañeros turistas de paso!",
  ui_story_5031_50310202_127_dialog_content = "¿Otro grupo de almas perdidas, supongo? ¿Listo para tirar todo al viento por la oportunidad de entrar por esta puerta?",
  ui_story_5031_50310202_128_dialog_content = "Alternativamente, puedes simplemente salir de aquí.",
  ui_story_5031_50310202_129_dialog_content = "¿Oh?",
  ui_story_5031_50310202_130_dialog_content = "¡Lo que quiero decir es que las cubiertas inferiores están fuera del alcance de los pasajeros!",
  ui_story_5031_50310202_131_dialog_content = "Por favor, regresa.",
  ui_story_5031_50310202_132_dialog_content = "¡Oh, lo siento! Nos iremos ahora.",
  ui_story_5031_50310202_133_dialog_content = "Qué sabes... No es tan fácil entrar.",
  ui_story_5031_50310202_134_dialog_content = "Esto es un enigma... no hay duda al respecto.",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310202_136_dialog_content = "\"¡Atención a todos los pasajeros! Los preparativos para la competencia de carnaval se han completado recientemente\".",
  ui_story_5031_50310202_137_dialog_content = "\"Todos los participantes interesados, por favor diríjanse al área designada para inscribirse y registrarse\".",
  ui_story_5031_50310202_138_dialog_content = "\"Los participantes recibirán una importante recompensa de Nightium, así como la oportunidad de experimentar un día en la vida de un miembro del circo\".",
  ui_story_5031_50310202_139_dialog_content = "\"El ganador del primer premio también puede recibir un gran premio personalmente de manos del maestro de ceremonias\".",
  ui_story_5031_50310202_140_dialog_content = "¿Qué piensas? Un día en la vida de un miembro del circo también podría significar un día de acceso a las cubiertas inferiores.",
  ui_story_5031_50310202_141_dialog_content = "No es una mala idea, si lo digo.",
  ui_story_5031_50310202_142_dialog_content = "Vamos, echemos un vistazo más de cerca.",
  ui_story_5031_50310202_143_dialog_content = "Vaya, vaya, nunca lo habría adivinado. ¡Qué multitud!",
  ui_story_5031_50310202_144_dialog_content = "Tsk... Son como una horda de langostas rodeándome.",
  ui_story_5031_50310202_145_dialog_content = "¿Qué hace un juez respetable como yo, el juez Matthieu, entre esta gentuza?",
  ui_story_5031_50310202_146_dialog_content = "...",
  ui_story_5031_50310202_147_dialog_content = "¡Ve a molestar a alguien más!",
  ui_story_5031_50310202_148_dialog_content = "Tsk. Esta conmoción no es buena para mi delicado humor. Incluso me estoy quedando corto contigo, Loewe.",
  ui_story_5031_50310202_149_dialog_content = "Carleen, creo que esos dos son de Lumopolis.",
  ui_story_5031_50310202_150_dialog_content = "Son del Salón de la Justicia, tal vez... pero a quién le importa.",
  ui_story_5031_50310202_151_dialog_content = "Vice! PlayerName y Carleen! Y...?",
  ui_story_5031_50310202_152_dialog_content = "Oficial Gronru! Esto es...",
  ui_story_5031_50310202_153_dialog_content = "Soy Fia, extrozoóloga. ¡El placer de conocerla!",
  ui_story_5031_50310202_154_dialog_content = "Maravilloso. Espero que hayas sido una buena influencia para los niños pequeños, Caelestite.",
  ui_story_5031_50310202_155_dialog_content = "¡¿Para qué me miras?!",
  ui_story_5031_50310202_156_dialog_content = "Entonces, ¿a qué le debemos el placer, oficial? Gronru?",
  ui_story_5031_50310202_157_dialog_content = "Tuve la corazonada de que el espectáculo sería entretenido, junto con tu querido compañero de escuela.",
  ui_story_5031_50310202_158_dialog_content = "C-Ce... U-Um, hola, soy Ciel... ex compañero de clase de Vice.",
  ui_story_5031_50310202_159_dialog_content = "Ce?",
  ui_story_5031_50310202_160_dialog_content = "¡Mucho tiempo sin verlo! En realidad, ha pasado demasiado tiempo. No te he visto mucho desde que comencé a trabajar con PlayerName.",
  ui_story_5031_50310202_161_dialog_content = "Ciel es bastante tímido. Ese es su tic nervioso, el \"ce\".",
  ui_story_5031_50310202_162_dialog_content = "Pero a quién le importa eso, ¿verdad? Solíamos llamarla un genio absoluto cuando se trata de cualquier cosa que tenga que ver con la ingeniería, ¿verdad?",
  ui_story_5031_50310202_163_dialog_content = "Me parece bien. Una persona inteligente que es estable es difícil de encontrar.",
  ui_story_5031_50310202_164_dialog_content = "Oficial Gronru, señorita Ciel, ¿está aquí para divertirse?",
  ui_story_5031_50310202_165_dialog_content = "¡No no! No usaría este atuendo sofocante si fuera a disfrutar el carnaval.",
  ui_story_5031_50310202_166_dialog_content = "¿No me digas que mi estimada Caelestite no se ha dado cuenta? O tu, Vice?",
  ui_story_5031_50310202_167_dialog_content = "¿Has mencionado el tamaño de este prodigioso barco? ¡Considere la complejidad de su estructura y fabricación!",
  ui_story_5031_50310202_168_dialog_content = "Aproveché la primera oportunidad que tuve para arrastrar a Ciel a investigar esta obra de arte de la ingeniería.",
  ui_story_5031_50310202_169_dialog_content = "¡Qué vergüenza que no hayamos logrado encontrar un camino hacia las cubiertas inferiores! Una simple inspección del exterior no puede proporcionar suficientes conocimientos.",
  ui_story_5031_50310202_170_dialog_content = "¡Todo lo cual debe llevarnos inexorablemente ahora a unirnos a la competencia nosotros mismos!",
  ui_story_5031_50310202_171_dialog_content = "Asi que, Vice, vas a ayudar oficial Gronru y su amiga?",
  ui_story_5031_50310202_172_dialog_content = "Está bien. No quiero interferir con las maquinaciones del \"Team Colossus\". Y creo que los organizadores son bastante flexibles con el tamaño de los equipos.",
  ui_story_5031_50310202_173_dialog_content = "¡Y creo completamente que las habilidades de Ciel no son inferiores a las de mi estimado amigo, Vice!",
  ui_story_5031_50310202_174_dialog_content = "¡Yo, eh, haré mi mejor esfuerzo!",
  ui_story_5031_50310202_175_dialog_content = "Bueno, entonces, ¡es hora de prepararnos para este delicioso y prometedor juego! Nos vemos pronto.",
  ui_story_5031_50310202_176_dialog_content = "Oh mi. Ya estamos alineando oponentes duros, ya veo...",
  ui_story_5031_50310202_177_dialog_content = "¿Por qué tardan tanto en anunciar los detalles?",
  ui_story_5031_50310202_178_dialog_content = "Oh, creo que acabo de ver a dos personas subirse al escenario.",
  ui_story_5031_50310202_179_dialog_content = "¿Ese es el Laird Elvis? ¿Y hay otra figura, toda de negro?",
  ui_story_5031_50310202_180_dialog_content = "Ejem.",
  ui_story_5031_50310202_181_dialog_content = "¡Bienvenidos, todos y cada uno! ¡Mis queridos conciudadanos de Harbor City y viajeros de todas partes!",
  ui_story_5031_50310202_182_dialog_content = "Soy el laird de Harbor City, Elvis Modali.",
  ui_story_5031_50310202_183_dialog_content = "¡Laird Elvis!",
  ui_story_5031_50310202_184_dialog_content = "Elvis Modali! Elvis Modali!",
  ui_story_5031_50310202_185_dialog_content = "Gracias. Y es un honor y un privilegio para mí invitar a una verdadera leyenda de los mares con nosotros en este día de verano:",
  ui_story_5031_50310202_186_dialog_content = "¡El legendario ilusionista y el circo del viejo Bill ofrecerán otra actuación espectacular en este carnaval!",
  ui_story_5031_50310202_187_dialog_content = "Soy el maestro de ceremonias del Circo del Ilusionista y el Viejo Bill, Jeno Gallacher. Gracias a todos por la calurosa bienvenida.",
  ui_story_5031_50310202_188_dialog_content = "En vista de la equidad, será mi costumbre en los procedimientos de hoy entregar las reglas antes de cada desafío.",
  ui_story_5031_50310202_189_dialog_content = "Los competidores que superen todos los desafíos no solo podrán experimentar un día en la vida de un miembro del circo...",
  ui_story_5031_50310202_190_dialog_content = "Pero también recibirá un regalo especial y precioso preparado personalmente por mí mismo.",
  ui_story_5031_50310202_191_dialog_content = "Como se cree a menudo y con razón, una compañía de circo es también un almacén de muchas baratijas extraordinarias.",
  ui_story_5031_50310202_192_dialog_content = "Y, a decir verdad, ¡el circo que dirijo no es una excepción!",
  ui_story_5031_50310202_193_dialog_content = "Nuestros largos viajes en busca de maravillas han sido bendecidos de maneras muy físicas y extraordinarias.",
  ui_story_5031_50310202_194_dialog_content = "Además de los múltiples tesoros otorgados por el océano mismo, es decir, ¡el gran premio final de este carnaval!",
  ui_story_5031_50310202_195_dialog_content = "Siéntase libre de imaginar este tesoro exótico. Espéralo con ansias. ¡Usted no será decepcionado!",
  ui_story_5031_50310202_196_dialog_content = "¡Guau! ¡Suena súper valioso!",
  ui_story_5031_50310202_197_dialog_content = "¡Seremos ricos!",
  ui_story_5031_50310202_197X1_dialog_content = "Un tesoro exótico otorgado por el mar... ¡Lo sé!",
  ui_story_5031_50310202_197X2_dialog_content = "Esa debe ser la Nube—¡Ups!",
  ui_story_5031_50310202_197X3_dialog_content = "¡Silenciar! Tranquilizarse. ¿Quieres que más oponentes conozcan su verdadera identidad y luchen por ella?",
  ui_story_5031_50310202_197X4_dialog_content = "Ups, entiendo. ¡Entonces confiaremos en nosotros mismos para ganar el partido y salvar a Cloudwhale!",
  ui_story_5031_50310202_198_dialog_content = "Además, difícilmente creo que estaría impresionado si tuviéramos un solo juez para nuestra competencia.",
  ui_story_5031_50310202_199_dialog_content = "Por lo tanto, es un gran placer para mí invitar al gran líder de Harbor City, Laird Elvis, a ser co-juez conmigo.",
  ui_story_5031_50310202_200_dialog_content = "¡Laird Elvis! ¡Laird Elvis!",
  ui_story_5031_50310202_201_dialog_content = "Oh...? Jeno? ¿Es esto algo que deberíamos haber discutido primero?",
  ui_story_5031_50310202_202_dialog_content = "¿Hay algún problema, señor? ¡Hubiera pensado que estarías agradecido por tener la oportunidad de disfrutar lo que cualquier hombre en tu posición debería poder disfrutar!",
  ui_story_5031_50310202_203_dialog_content = "¡Laird Elvis! ¡Laird Elvis!",
  ui_story_5031_50310202_204_dialog_content = "Ya veo.",
  ui_story_5031_50310202_205_dialog_content = "¡Confiamos en que disfrutarán de los eventos al contenido de sus corazones, todos!",
  ui_story_5031_50310301_0_dialog_content = "Um, entonces este encaje debería ir aquí...",
  ui_story_5031_50310301_0X1_dialog_content = "¿Eh? ¿Cómo es que hay otro encaje?",
  ui_story_5031_50310301_0X2_dialog_content = "Este... Uh, ¿debería pasar por el otro lado?",
  ui_story_5031_50310301_0X3_dialog_content = "Gracias por ayudar, Vice.",
  ui_story_5031_50310301_0X4_dialog_content = "No hay problema. Solo espera y déjame resolver esto en un minuto.",
  ui_story_5031_50310301_0X5_dialog_content = "Tome su tiempo. No tengo prisa.",
  ui_story_5031_50310301_0X6_dialog_content = "Um, debería ser de esta manera, ¿verdad?",
  ui_story_5031_50310301_0X7_dialog_content = "Mmm, tal vez no...",
  ui_story_5031_50310301_0X8_dialog_content = "... Vice.",
  ui_story_5031_50310301_0X9_dialog_content = "¿Hmm? ¿Que es eso? ¿Te lastimé?",
  ui_story_5031_50310301_0X10_dialog_content = "No. Es sólo... ¿Puedo preguntarte algo personal?",
  ui_story_5031_50310301_0X11_dialog_content = "¿Personal?",
  ui_story_5031_50310301_0X12_dialog_content = "Sí... Me gustaría saber cómo te sentiste... cuando obtuviste el nuevo poder.",
  ui_story_5031_50310301_0X13_dialog_content = "Oh, ya veo... ¡Eso no es nada personal!",
  ui_story_5031_50310301_0X14_dialog_content = "Levanta un poco el codo derecho.",
  ui_story_5031_50310301_0X15_dialog_content = "Oh, por supuesto.",
  ui_story_5031_50310301_0X16_dialog_content = "Um... Pero esa es en realidad una pregunta difícil.",
  ui_story_5031_50310301_0X17_dialog_content = "No es que no quiera responder... Es solo que es difícil de describir.",
  ui_story_5031_50310301_0X18_dialog_content = "Entiendo.",
  ui_story_5031_50310301_0X19_dialog_content = "Para mí, sentí que mi potencial estaba siendo desbloqueado.",
  ui_story_5031_50310301_0X20_dialog_content = "Obtuve una perspectiva diferente sobre Lumina, pero también con ciertos riesgos.",
  ui_story_5031_50310301_0X21_dialog_content = "¿Riesgos?",
  ui_story_5031_50310301_0X22_dialog_content = "Sí, estaba tan dormida durante el proceso. Pensé que nunca me despertaría.",
  ui_story_5031_50310301_0X23_dialog_content = "Seguía pensando en mi antiguo yo, con miedo de perderme si me relajaba aunque sea por un segundo.",
  ui_story_5031_50310301_0X24_dialog_content = "También vi muchas cosas maravillosas, como si estuviera allí.",
  ui_story_5031_50310301_0X25_dialog_content = "Esas ilusiones se sentían tan reales, como una prueba para mí.",
  ui_story_5031_50310301_0X26_dialog_content = "Por suerte, me aferré a un destello de conciencia y lo conservé hasta el final.",
  ui_story_5031_50310301_0X27_dialog_content = "Ya veo. Entonces, ¿es un proceso de desbloquear tu potencial...?",
  ui_story_5031_50310301_0X28_dialog_content = "Sí, eso es lo que pienso.",
  ui_story_5031_50310301_0X29_dialog_content = "En realidad, muchos Aurorianos obtienen tales avances en una crisis.",
  ui_story_5031_50310301_0X30_dialog_content = "Supongo que eso es lo que me pasó a mí.",
  ui_story_5031_50310301_0X31_dialog_content = "Pero incluso ahora, todavía no puedo dominarlo por completo.",
  ui_story_5031_50310301_0X32_dialog_content = "Eso es probablemente porque todavía es nuevo para ti. Lo harás, dado el tiempo.",
  ui_story_5031_50310301_0X33_dialog_content = "¡Eso es cierto!",
  ui_story_5031_50310301_0X34_dialog_content = "Si quieres probarlo, ¿tal vez puedas comenzar con la liberación de la conciencia?",
  ui_story_5031_50310301_0X35_dialog_content = "Liberación de conciencia?",
  ui_story_5031_50310301_0X36_dialog_content = "Sí. Eso es lo que haría cada vez que quiero activar mi poder, aunque no todo el tiempo tiene éxito.",
  ui_story_5031_50310301_0X37_dialog_content = "Ya veo. Lo tengo.",
  ui_story_5031_50310301_0X38_dialog_content = "Lo intentaré en otro momento. Gracias, Vice.",
  ui_story_5031_50310301_0X39_dialog_content = "¡No hay problema!",
  ui_story_5031_50310301_0X40_dialog_content = "¡Allá vamos, la última puntilla!",
  ui_story_5031_50310301_0X41_dialog_content = "¡Uf, ponerse el atuendo noble seguro es un fastidio!",
  ui_story_5031_50310301_0X42_dialog_content = "Y su material parece bastante único. Nunca he visto esto en Illumina.",
  ui_story_5031_50310301_0X43_dialog_content = "Esta es mi primera vez también. Probablemente sea una especialidad de Harbor City.",
  ui_story_5031_50310301_0X44_dialog_content = "Después de todo, la ropa formal es su fuerte.",
  ui_story_5031_50310301_0X45_dialog_content = "Gracias de nuevo por la ayuda, Vice.",
  ui_story_5031_50310301_0X46_dialog_content = "No te preocupes. Pero te ves muy bien en eso, Carleen!",
  ui_story_5031_50310301_0X47_dialog_content = "Vamos a mostrárselo a PlayerName y Fia. ¡Se sorprenderán!",
  ui_story_5031_50310301_1_dialog_content = "¿Por qué no es Carleen ¿regresado todavía?",
  ui_story_5031_50310301_2_dialog_content = "Las chicas se toman su tiempo para cambiarse, sin mencionar que el atuendo se ve muy complejo.",
  ui_story_5031_50310301_2X1_dialog_content = "Incluso con la ayuda de Vice, todavía debería tomar un tiempo.",
  ui_story_5031_50310301_3_dialog_content = "Tienes un punto. ¿Por qué tengo la sensación de que los nobles necesitan un sirviente solo para vestirse?",
  ui_story_5031_50310301_4_dialog_content = "¿Qué tal si le das Carleen una mano también, Fia?",
  ui_story_5031_50310301_5_dialog_content = "¿Oye? ¿Qué soy yo, tu sirviente ahora? ¡Dándome órdenes así!",
  ui_story_5031_50310301_6_dialog_content = "Por favor. no son Carleen y Vice haciendo todo lo posible para ayudarte a localizar la Ballena Nube?",
  ui_story_5031_50310301_7_dialog_content = "¡Bien bien! Nunca antes había ayudado a alguien a ponerse un vestido. Puedo probar.",
  ui_story_5031_50310301_8_dialog_content = "PlayerName, tómalo con calma con Fia.",
  ui_story_5031_50310301_9_dialog_content = "Lo siento por hacer esperar a todos...",
  ui_story_5031_50310301_10_dialog_content = "¡Bien! Carleen, te ves... ¡absolutamente impresionante!",
  ui_story_5031_50310301_11_dialog_content = "¡Sí! Se ve cómodo, práctico y realmente te queda bien, Carleen!",
  ui_story_5031_50310301_12_dialog_content = "Gracias a todos. Es asombroso: la cantidad de sastres profesionales y diseñadores de moda increíbles en Harbor City.",
  ui_story_5031_50310301_13_dialog_content = "De hecho, me siento extremadamente cómodo en esto.",
  ui_story_5031_50310301_14_dialog_content = "¿Qué opinas, PlayerName?",
  ui_story_5031_50310301_15_dialog_content = "Lo siento. Me quedé hechizado por un segundo. Pero lo que iba a decir era que—",
  ui_story_5031_50310301_16_dialog_content = "¡Hermoso! ¡Agraciado! ¡Poderoso!",
  ui_story_5031_50310301_17_dialog_content = "eres un hijo del Schwartz familia en todos los sentidos, Carleen, y este impresionante atuendo solo lo demuestra.",
  ui_story_5031_50310301_18_dialog_content = "no se que decir Supongo que debería agradecerte, Laird Elvis.",
  ui_story_5031_50310301_19_dialog_content = "Por favor, es lo menos que podía hacer. Iba por algo que me recordara las características nobles y ejemplares de los Schwartz familia.",
  ui_story_5031_50310301_20_dialog_content = "¡Puede considerar el atuendo como una especie de buen augurio para su exitosa entrada en la competencia!",
  ui_story_5031_50310301_21_dialog_content = "¡Me necesitan en otro lugar, pero espero volver a verte más tarde!",
  ui_story_5031_50310301_22_dialog_content = "Oh, lo siento, supongo que realmente no tuve la oportunidad de compartir mis pensamientos sobre el nuevo vestido de Carleen.",
  ui_story_5031_50310301_23_dialog_content = "Urgh. Laird Elvis me robó el trueno.",
  ui_story_5031_50310301_24_dialog_content = "Eh, no creo que tengas que decir nada...",
  ui_story_5031_50310301_25_dialog_content = "Has dicho bastante con tus ojos.",
  ui_story_5031_50310301_26_dialog_content = "¿Ah?",
  ui_story_5031_50310301_27_dialog_content = "¡Saludos a todos! Es hora de que les dé a todos un breve resumen del evento.",
  ui_story_5031_50310301_28_dialog_content = "Permítame presentarme. ¡Soy Rainbow, el maestro de ceremonias del circo, enlace con el cliente, director de seguridad y aprendiz de ingeniero marino!",
  ui_story_5031_50310301_29_dialog_content = "¡Pero hoy usaré el sombrero del maestro de ceremonias principal de la competencia!",
  ui_story_5031_50310301_30_dialog_content = "En esta primera etapa, les pido amablemente que tomen una de mis pistolas de agua especialmente preparadas desde aquí.",
  ui_story_5031_50310301_31_dialog_content = "Estas pistolas de agua se han modificado para canalizar a Lumina para que dispare un perdigón especial.",
  ui_story_5031_50310301_32_dialog_content = "Las reglas son muy sencillas: alcanza los objetivos indicados por el maestro de ceremonias Jeno con tu pistola de agua.",
  ui_story_5031_50310301_33_dialog_content = "¡Debo informarles que no impediremos que los competidores o equipos usen las pistolas de agua entre sí!",
  ui_story_5031_50310301_34_dialog_content = "Solo los cinco equipos con mayor puntuación pasarán a la siguiente ronda. Los eliminados son arrojados al mar como castigo.",
  ui_story_5031_50310301_35_dialog_content = "¡Así que no queremos ningún concursante que no sepa nadar! ¡O al menos asegúrese de tener un dispositivo de flotación con usted!",
  ui_story_5031_50310301_36_dialog_content = "Los equipos pueden ser de cualquier tamaño, pero ten en cuenta que tu puntuación final se obtendrá dividiendo la puntuación de tu equipo por el número de miembros.",
  ui_story_5031_50310301_37_dialog_content = "Estas reglas son realmente buenas para nosotros, ¿verdad?",
  ui_story_5031_50310301_38_dialog_content = "Vamos a conseguir el premio seguro con Jona y Azure en nuestro equipo!",
  ui_story_5031_50310301_39_dialog_content = "¿Pistolas de agua? Parece una tontería, pero no puedo ignorar ese gran premio...",
  ui_story_5031_50310301_40_dialog_content = "¿Qué más vamos a hacer con nuestro tiempo de todos modos? Es solo un poco de diversión inofensiva.",
  ui_story_5031_50310301_41_dialog_content = "¡Oye! ¡Lo tenemos hecho!",
  ui_story_5031_50310301_42_dialog_content = "¡No cuentes tus pollos demasiado pronto! De todos modos, ustedes dos acaban de unirse a Rediesel Wrench.",
  ui_story_5031_50310301_43_dialog_content = "¡Recuerda cómo los chicos de Rediesel Wrench manejan las cosas frente a los extraños! Nos enorgullecemos.",
  ui_story_5031_50310301_44_dialog_content = "¡No te preocupes por nada! ¡Lo entendiste!",
  ui_story_5031_50310301_45_dialog_content = "¡Solo algunas cosas para recordar! ¡Entiendo!",
  ui_story_5031_50310301_46_dialog_content = "¿Todos tienen claras las reglas?",
  ui_story_5031_50310301_47_dialog_content = "¡Alto y claro!",
  ui_story_5031_50310301_48_dialog_content = "¡Esperar! Si estas pistolas de agua funcionan con Lumina, ¿cómo va a funcionar para mí?",
  ui_story_5031_50310301_49_dialog_content = "Oh sí. No consideré eso para Caelestites.",
  ui_story_5031_50310301_50_dialog_content = "Merylt, ¿crees que podrías ir al equipo de Caelestite y ayudarlos?",
  ui_story_5031_50310301_51_dialog_content = "¿Q-Qué se supone que debo hacer con eso? No se nos permite participar...",
  ui_story_5031_50310301_52_dialog_content = "Tonto. ¿Por qué incluso incluirlo? Él no es mucho de un brote de soja.",
  ui_story_5031_50310301_53_dialog_content = "Jefe, ¿qué pasa con Caelestite?",
  ui_story_5031_50310301_54_dialog_content = "Podemos tener en cuenta las desventajas. Cuenta a Caelestite ya esa niña como uno.",
  ui_story_5031_50310301_55_dialog_content = "¡Oye! ¿En qué universo es Caelestite más yo la mitad de una persona cada uno?",
  ui_story_5031_50310301_56_dialog_content = "Hazlo a tu manera. Dos participantes entonces.",
  ui_story_5031_50310301_57_dialog_content = "Uh, en realidad, soy un poco joven y no estoy muy en forma... Pensándolo bien, ¡tal vez tenga sentido combinarnos!",
  ui_story_5031_50310301_58_dialog_content = "Entonces, si no hay objeciones, entregaré sus objetivos en breve—",
  ui_story_5031_50310301_59_dialog_content = "¡Vamos! ¡Un aplauso para nuestros locos competidores!",
  ui_story_5031_50310301_60_dialog_content = "¡Ahora, aúlla! ¡Como lo dices en serio! ¡Bestias del Hades!",
  ui_story_5031_50310301_61_dialog_content = "¡Esperar! Espero que Boss no esté realmente pensando en convocar a esos...",
  ui_story_5031_50310301_62_dialog_content = "¡Rápido! ¡Cubre los ojos de Rainbow! ¡Se volverá loca si ve un eclipse!",
  ui_story_5031_50310301_63_dialog_content = "Graah!",
  ui_story_5031_50310301_64_dialog_content = "¿Eclipsitos?",
  ui_story_5031_50310301_65_dialog_content = "¡¡Eclipsitos!!",
  ui_story_5031_50310301_66_dialog_content = "Frimet! Haz algo para ayudarme con Rainbow. ¡Se lo va a perder!",
  ui_story_5031_50310301_67_dialog_content = "¡Jefe estúpido! ¿Por qué elegir Eclipses?",
  ui_story_5031_50310301_68_dialog_content = "Eh... porque funciona tan bien con este viento.",
  ui_story_5031_50310301_69_dialog_content = "PlayerName, Fia, ponte detrás de mí y Vice.",
  ui_story_5031_50310301_70_dialog_content = "¡No se preocupen, queridos amigos! Estos eclipses son poco más que ilusiones que he evocado con el \"<color=#FFB400>Origen</color>.\"",
  ui_story_5031_50310301_71_dialog_content = "¡Con el poder de mis propias manos, he analizado el \"origen\" del poder de los Eclipsites en el curso de mis batallas!",
  ui_story_5031_50310301_72_dialog_content = "Y, con el uso del \"<color=#FFB400>Tarjeta de origen</color>,\" creó las ilusiones ágiles y realistas que ves ante ti.",
  ui_story_5031_50310301_73_dialog_content = "Grah...",
  ui_story_5031_50310301_74_dialog_content = "Grah...",
  ui_story_5031_50310301_75_dialog_content = "Como puede ver, los Eclipsites están completamente bajo mi control y son excelentes objetivos.",
  ui_story_5031_50310301_76_dialog_content = "Entonces, ¡que empiecen los juegos!",
  ui_story_5031_50310401_1_dialog_content = "¡Oye! ¡Ponte a trabajar! ¡Quiero que limpies estos eclipses, porque no hay forma de que Rediesel Wrench se conforme con el segundo!",
  ui_story_5031_50310401_2_dialog_content = "¡Entendido, jefe! Pero, ¿y los aurorianos?",
  ui_story_5031_50310401_3_dialog_content = "¿Que hay de ellos? ¡Eres una llave inglesa Rediesel! ¡Ahora sácalo del parque!",
  ui_story_5031_50310401_4_dialog_content = "¡Haz que la llave Reddiesel se vea bien y dispara a cualquiera que se cruce en tu camino por el costado del barco!",
  ui_story_5031_50310401_5_dialog_content = "Entiendo.",
  ui_story_5031_50310401_6_dialog_content = "Intenso, Jona.",
  ui_story_5031_50310401_7_dialog_content = "¿Cual es el problema? ¡Ningún chico, por lindo que sea, está por encima del castigo!",
  ui_story_5031_50310401_8_dialog_content = "Lindo es lindo, pero aún más lindo es ese gran premio...",
  ui_story_5031_50310401_9_dialog_content = "Urgh... Jona y Azure están aquí, son profesionales de las armas.",
  ui_story_5031_50310401_10_dialog_content = "Dijeron que solo obtienes puntos por disparar Eclipsites, ¡pero estos tipos de Rediesel Wrench solo están disparando a otros jugadores!",
  ui_story_5031_50310401_11_dialog_content = "Si las ilusiones de Jeno no fueran una tapadera tan excelente, nos habrían disparado por la borda hace mucho tiempo.",
  ui_story_5031_50310401_12_dialog_content = "Todavía podríamos estarlo a menos que podamos hacer algo en lugar de simplemente esperar aquí. ¡Siga mi ejemplo! ¡Lucharemos para abrirnos paso!",
  ui_story_5031_50310401_13_dialog_content = "Esperar, Carleen!",
  ui_story_5031_50310401_14_dialog_content = "Esto es lo que obtienes por no seguir el espíritu de las reglas, sucios embusteros: ¡flor de hielo, no, lanzamiento de hielo!",
  ui_story_5031_50310401_15_dialog_content = "¡Ay!",
  ui_story_5031_50310401_16_dialog_content = "B-Jefe!",
  ui_story_5031_50310401_17_dialog_content = "Son dos de ellos abajo. Rápido, vengan aquí, todos.",
  ui_story_5031_50310401_18_dialog_content = "Excelente trabajo... Directo al océano con la sesión de hielo característica de Carleen. Oye, Carleen, detrás de la cubierta, ¡rápido!",
  ui_story_5031_50310401_19_dialog_content = "¡Ahora es tu oportunidad, PlayerName!",
  ui_story_5031_50310401_20_dialog_content = "Eso es lo que obtienes por ser un llanero solitario, Carleen! Esto significa-",
  ui_story_5031_50310401_21_dialog_content = "¡Ya te tengo, mi bella princesa de Lumopolis!",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310401_23_dialog_content = "¡¡!!",
  ui_story_5031_50310401_24_dialog_content = "¡Carleen!",
  ui_story_5031_50310401_25_dialog_content = "Lo... lo siento, PlayerName.",
  ui_story_5031_50310401_26_dialog_content = "Bien está lo que bien acaba. no esperaba Jona ser tan bueno con una pistola de agua Lumina.",
  ui_story_5031_50310401_27_dialog_content = "¡Oye! ¡Despreciables matones de Rediesel! ¡Deja de molestarnos!",
  ui_story_5031_50310401_28_dialog_content = "Eso no va a funcionar. Tenemos que resolver este callejón sin salida.",
  ui_story_5031_50310401_29_dialog_content = "Una competencia muy emocionante, todos.",
  ui_story_5031_50310401_30_dialog_content = "Sí. Por cierto. Lleno de proezas de poder que no esperaba.",
  ui_story_5031_50310401_31_dialog_content = "Un poder que obtuve de la Orden Verdadera...",
  ui_story_5031_50310401_32_dialog_content = "De las cuales estoy seguro de que ha oído más leyendas negativas como noble de Lumopolis, señor.",
  ui_story_5031_50310401_33_dialog_content = "De hecho, lo que representa el \"origen\" más que nada es simplemente otra forma de crear suspenso para el efecto performativo.",
  ui_story_5031_50310401_34_dialog_content = "En verdad, lo que poseo es simplemente el poder de transformar la energía... un hábito efectivo con la práctica, como puedes ver.",
  ui_story_5031_50310401_35_dialog_content = "No soy de los que se ofenden especialmente con los poderes extraños. No te preocupes.",
  ui_story_5031_50310401_36_dialog_content = "Pero, ¿por qué eclipses?",
  ui_story_5031_50310401_37_dialog_content = "Todos estamos aquí para asistir al carnaval, ¿no? ¿Qué es un carnaval sino una serie de encuentros emocionantes e impresionantes?",
  ui_story_5031_50310401_38_dialog_content = "Debería pensar que los eclipses se ajustan muy bien a los requisitos.",
  ui_story_5031_50310401_39_dialog_content = "No me puedo quejar de su lógica de negocios. Comida para el pensamiento.",
  ui_story_5031_50310401_40_dialog_content = "Naturalmente, siempre debo pensar en el caso de negocios como el maestro de ceremonias de toda la compañía de circo.",
  ui_story_5031_50310401_41_dialog_content = "Mis disculpas por la intrusión, Laird Elvis.",
  ui_story_5031_50310401_42_dialog_content = "¿Pato...? Más tarde, Jeno.",
  ui_story_5031_50310401_43_dialog_content = "¿Qué noticias tienes?",
  ui_story_5031_50310401_44_dialog_content = "Un informe, verificado. Hemos localizado una habitación que coincide con su descripción anterior.",
  ui_story_5031_50310401_45_dialog_content = "¿Qué? Maravilloso...",
  ui_story_5031_50310401_46_dialog_content = "Desafortunadamente, la habitación está protegida por una cerradura muy segura que nunca hemos visto. La entrada forzada ciertamente daría la alarma.",
  ui_story_5031_50310401_47_dialog_content = "Entiendo. Entonces tendremos que encontrar una llave capaz de abrirlo.",
  ui_story_5031_50310401_48_dialog_content = "Supongo que esa llave podría encontrarse en las cámaras de Jeno o en su persona. Podemos probar ambas vías simultáneamente.",
  ui_story_5031_50310401_49_dialog_content = "¡Elvis!",
  ui_story_5031_50310401_50_dialog_content = "Espero no molestarte, pero otro equipo acaba de anotar un gran punto y la gente te pide a gritos que honres el punto.",
  ui_story_5031_50310401_51_dialog_content = "¡Laird Elvis! ¡Laird Elvis!",
  ui_story_5031_50310401_52_dialog_content = "Disculpas, Jeno. Después de unas pocas palabras más con Patou.",
  ui_story_5031_50310401_53_dialog_content = "Entonces, ¿qué vamos a hacer, señor?",
  ui_story_5031_50310401_54_dialog_content = "Usted y sus hombres tienen autoridad para hacer lo que sea necesario para registrar la habitación.",
  ui_story_5031_50310401_55_dialog_content = "Pero me temo que cualquier ausencia significativa de los eventos del día despertará las sospechas de Jeno.",
  ui_story_5031_50310401_56_dialog_content = "Es intrigante cuántos participantes aurorianos tenemos con motivos desconocidos... y sospecho que las mismas ideas.",
  ui_story_5031_50310401_57_dialog_content = "Así que asigne una estrecha vigilancia sobre ellos. Cualquiera que quiera hacer un movimiento deberá hacerlo cuando esté tranquilo, cuando la cubierta esté menos ocupada.",
  ui_story_5031_50310401_58_dialog_content = "Lo entiendo, señor, debemos continuar buscando en silencio y esperar más órdenes de su señoría.",
  ui_story_5031_50310401_59_dialog_content = "¡Laird Elvis! ¡Laird Elvis!",
  ui_story_5031_50310401_60_dialog_content = "¡Por fin estoy de vuelta, todos! ¡Y por la presente anuncio que el equipo de Rediesel Wrench ha ganado otro punto!",
  ui_story_5031_50310401_61_dialog_content = "De vuelta de hecho. empezábamos a preguntarnos.",
  ui_story_5031_50310401_62_dialog_content = "Disculpas, Jeno, por la larga espera.",
  ui_story_5031_50310402_1_dialog_content = "¿Y qué hay de esa llave? ¿Cómo se supone que voy a saber dónde lo pusiste?",
  ui_story_5031_50310402_2_dialog_content = "¿Pareces un poco fuera de sí, Elvis?",
  ui_story_5031_50310402_3_dialog_content = "Quiero decir, parecía que algo que dijo tu guardaespaldas te había disgustado.",
  ui_story_5031_50310402_4_dialog_content = "Confío en que todo está bien? ¿No hay enfermedades de ningún tipo?",
  ui_story_5031_50310402_5_dialog_content = "No no. Estoy muy bien gracias.",
  ui_story_5031_50310402_6_dialog_content = "Estaba ocupado con algunos asuntos de estado. Lo siento por darte esa impresión.",
  ui_story_5031_50310402_7_dialog_content = "Espero que arrastrarte aquí no te haya alejado de un trabajo importante.",
  ui_story_5031_50310402_8_dialog_content = "Estaba pensando que tal vez realmente apreciarías esta oportunidad de disfrutar el maravilloso festival con tu gente.",
  ui_story_5031_50310402_9_dialog_content = "¿Vaya? ¿Es la primera vez que veo a Boss disculparse?",
  ui_story_5031_50310402_10_dialog_content = "Creo que sí. Supongo que puede hablar como una persona normal si quiere.",
  ui_story_5031_50310402_11_dialog_content = "Si tienes tanto tiempo libre, ve y ayuda a Rainbow, ¿de acuerdo?",
  ui_story_5031_50310402_12_dialog_content = "Pffffft.",
  ui_story_5031_50310402_13_dialog_content = "Sheesh. Es como arrear gatos, de la mañana a la noche.",
  ui_story_5031_50310402_14_dialog_content = "Oh, no te preocupes por mí. Sólo estaba...",
  ui_story_5031_50310402_15_dialog_content = "He estado preocupado por algunos asuntos de peso que necesitan una decisión.",
  ui_story_5031_50310402_16_dialog_content = "Esta oportunidad de relajarse ha significado una oportunidad para obtener nuevas ideas sobre algunas cosas y personas. Es muy útil.",
  ui_story_5031_50310402_17_dialog_content = "¡Maravilloso! Debes decirme si encuentras el día molesto por alguna razón.",
  ui_story_5031_50310402_18_dialog_content = "Derecha. No hay problema.",
  ui_story_5031_50310402_19_dialog_content = "\"¡Atención, participantes! ¡Ahora estamos entrando en una etapa más emocionante de nuestro juego que involucra el doble de proyecciones de Eclipsite!\"",
  ui_story_5031_50310402_20_dialog_content = "¡Finalmente! ¡Tiempo extra!",
  ui_story_5031_50310402_21_dialog_content = "¡Cúbreme, Ciel! ¡El tiempo de bonificación es donde los campeones lo hacen o lo deshacen!",
  ui_story_5031_50310402_22_dialog_content = "E-Entendido, oficial Gronru.",
  ui_story_5031_50310402_23_dialog_content = "Ah, estás corriendo demasiado rápido para mí—",
  ui_story_5031_50310402_24_dialog_content = "¡Oye! ¿Quién es ese?",
  ui_story_5031_50310402_25_dialog_content = "¿Qué tenemos aquí? Una pobre chica Illumina por su soledad.",
  ui_story_5031_50310402_26_dialog_content = "H-Oye! ¡Mantente alejado de mí!",
  ui_story_5031_50310402_27_dialog_content = "Necesitamos ese premio. Las cosas buenas no son baratas.",
  ui_story_5031_50310402_28_dialog_content = "Lo siento, señorita, pero voy a confiscar su pistola de agua. Ahora haznos un favor y salta al océano, ¿quieres?",
  ui_story_5031_50310402_29_dialog_content = "Espera, ¡buen equipo! Podríamos conseguir un buen precio por él en Umbraton, ¿no crees?",
  ui_story_5031_50310402_30_dialog_content = "¡Sí! Y siempre conseguimos lo que queremos, señorita. No hagas esto difícil.",
  ui_story_5031_50310402_31_dialog_content = "¡Danos tus objetos de valor!",
  ui_story_5031_50310402_32_dialog_content = "¡Manos fuera!",
  ui_story_5031_50310402_33_dialog_content = "¡Congelad, vosotros dos!",
  ui_story_5031_50310402_34_dialog_content = "¡No me digas que es el maestro de ceremonias!",
  ui_story_5031_50310402_35_dialog_content = "¡Lo mismísimo! El robo está estrictamente en contra de las reglas del torneo. ¡Me temo que no voy a poder dejarte ir!",
  ui_story_5031_50310402_36_dialog_content = "¿Quién crees que eres? ¿Crees que te tenemos miedo porque eres el maestro de ceremonias?",
  ui_story_5031_50310402_37_dialog_content = "No toleraré este tipo de comportamiento grosero, ¿me oyes?",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310402_39_dialog_content = "¡Amigo!",
  ui_story_5031_50310402_40_dialog_content = "¡Tú también!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310402_42_dialog_content = "¡Ay!",
  ui_story_5031_50310402_43_dialog_content = "V-Muy impresionante... Por la borda así como así.",
  ui_story_5031_50310402_44_dialog_content = "No estás herido, ¿verdad? ¡Eso fue una locura, pensar que podrían usar este evento como una extorsión!",
  ui_story_5031_50310402_45_dialog_content = "Uh, tengo que ayudar al oficial Gronru. ¡Gracias!",
  ui_story_5031_50310402_46_dialog_content = "Mi pistola de agua... ¿Dónde está?",
  ui_story_5031_50310402_47_dialog_content = "Vaya. Lo lamento. Toma, toma esto.",
  ui_story_5031_50310402_48_dialog_content = "Agregué algo a las reglas sobre \"las personas que pierden sus pistolas de agua pueden recoger una nueva del maestro de ceremonias\". Así que no te preocupes por eso.",
  ui_story_5031_50310402_49_dialog_content = "¡Ah, OK! Gracias.",
  ui_story_5031_50310402_50_dialog_content = "Hey...",
  ui_story_5031_50310402_51_dialog_content = "¿Ah?",
  ui_story_5031_50310402_52_dialog_content = "Soy Ciel Gracias, señorita Rainbow.",
  ui_story_5031_50310402_53_dialog_content = "Ciel? Recordaré tu nombre.",
  ui_story_5031_50310402_54_dialog_content = "Dios mío. ¿Cómo es una dama con clase? Carleen haciendo en un evento como este?",
  ui_story_5031_50310402_55_dialog_content = "Ella debería saber mejor con su noble educación. ¡Nos está haciendo quedar mal a todos!",
  ui_story_5031_50310402_56_dialog_content = "...",
  ui_story_5031_50310402_57_dialog_content = "¡Oye! ¿Solo estoy hablando conmigo mismo aquí?",
  ui_story_5031_50310402_58_dialog_content = "Tenemos que vigilar y proteger Carleen.",
  ui_story_5031_50310402_59_dialog_content = "Tut, bien podría serlo.",
  ui_story_5031_50310402_60_dialog_content = "¡Oye, ven aquí! ¡Hay montones de eclipses aquí que puedes derribar!",
  ui_story_5031_50310402_61_dialog_content = "¡Ah!",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5031_50310402_63_dialog_content = "Lo siento, señor... Accidentalmente conseguí su pistola de agua.",
  ui_story_5031_50310402_64_dialog_content = "Déjame ayudarte a recogerlo.",
  ui_story_5031_50310402_65_dialog_content = "Está bien. No te preocupes por eso. Tu amigo está esperando allí. Que la pases bien.",
  ui_story_5031_50310402_66_dialog_content = "Gracias. ¡Qué gentil noble eres!",
  ui_story_5031_50310402_67_dialog_content = "...",
  ui_story_5031_50310402_68_dialog_content = "... Desagradable.",
  ui_story_5031_50310402_69_dialog_content = "¡Agua! ¡Tráeme un poco de agua! ¡Necesito lavarme las manos!",
  ui_story_5031_50310402_70_dialog_content = "... Dramático.",
  ui_story_5031_50310402_71_dialog_content = "Graah!",
  ui_story_5031_50310402_72_dialog_content = "PlayerName, Jeno seguro agregó muchos Eclipsites.",
  ui_story_5031_50310402_73_dialog_content = "Y esos muchachos de Rediesel no nos dan respiro.",
  ui_story_5031_50310402_74_dialog_content = "¡Prefieren arriesgarse a ser eliminados por falta de puntos para centrarse en nosotros!",
  ui_story_5031_50310402_75_dialog_content = "Creo que eso solo dice que nos ven como la competencia.",
  ui_story_5031_50310402_76_dialog_content = "Y es por eso que quieren eliminarnos desde el principio.",
  ui_story_5031_50310402_77_dialog_content = "Tengo un poco de táctica... pero podría funcionar: puedo ser el cebo como alguien que no tiene acceso a Lumina.",
  ui_story_5031_50310402_78_dialog_content = "Haré todo lo posible para atraer muchos Eclipsites mientras usas el desvío para salir de debajo. Jona y el pulgar de Azure.",
  ui_story_5031_50310402_79_dialog_content = "¡Eso es demasiado arriesgado, PlayerName! Podemos intentar abrirnos paso de nuevo. Tendría más cuidado con eso!",
  ui_story_5031_50310402_80_dialog_content = "Jona y Azure son demasiado buenos Podrán identificarte desde una gran distancia, Carleen.",
  ui_story_5031_50310402_81_dialog_content = "No caigo tan fácil. Confía en mi poder.",
  ui_story_5031_50310402_82_dialog_content = "Confío, y ahora es el momento de poner tu fe en mi poder también.",
  ui_story_5031_50310402_83_dialog_content = "Carleen, creo que vale la pena probar la sugerencia de PlayerName.",
  ui_story_5031_50310402_84_dialog_content = "Creo que podría ser la mejor opción táctica que tenemos.",
  ui_story_5031_50310402_85_dialog_content = "Bien entonces. Pero ten cuidado, ¿de acuerdo?",
  ui_story_5031_50310402_86_dialog_content = "Está seguro. Fia, te vas con Carleen y Vice.",
  ui_story_5031_50310402_87_dialog_content = "¿E-Eh? Bueno.",
  ui_story_5031_50310402_88_dialog_content = "¡Eclipsitos! ¡Comida entrante!",
  ui_story_5031_50310402_89_dialog_content = "¡500 Lumamber es todo lo que se necesita para obtener el banquete más grande que jamás haya visto! ¡Ahora o nunca! ¡Ahhhhh!",
  ui_story_5031_50310402_90_dialog_content = "Graah!",
  ui_story_5031_50310402_91_dialog_content = "¡Graaaah...!",
  ui_story_5031_50310402_92_dialog_content = "¿Eh? ¿Ese es el PlayerName? ¿Qué diablos está haciendo?",
  ui_story_5031_50310402_93_dialog_content = "Caelestita inteligente. Está provocando a los Eclipsites para que bloqueen nuestra línea de visión, supongo.",
  ui_story_5031_50310402_94_dialog_content = "Entonces es un tonto que va a recibir un merecido justo en su trasero por subestimarme...",
  ui_story_5031_50310402_95_dialog_content = "Hola señoras.",
  ui_story_5031_50310402_96_dialog_content = "¿Qué?",
  ui_story_5031_50310402_97_dialog_content = "Me temo que considero a la alegre banda de Carleen bajo mi protección...",
  ui_story_5031_50310402_98_dialog_content = "Tengo suficiente ira en mis manos contaminadas para ir por ahí... ¿Se atreven a atacar al noble? Toma tus bultos!!",
  ui_story_5031_50310402_99_dialog_content = "Ponte detrás de mí, Vice, Fía!",
  ui_story_5031_50310402_100_dialog_content = "¡Voy a acabar con todos ustedes, los Eclipsites, sin ayuda!",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5031_50310402_102_dialog_content = "Grah...",
  ui_story_5031_50310402_103_dialog_content = "Graah!!",
  ui_story_5031_50310402_104_dialog_content = "Graah!",
  ui_story_5031_50310402_105_dialog_content = "Graah!",
  ui_story_5031_50310402_106_dialog_content = "Son débiles, pero hay demasiados. Nos tienen rodeados.",
  ui_story_5031_50310402_107_dialog_content = "Este no es el momento para darse el gusto, Carleen. Tenemos que volver con PlayerName.",
  ui_story_5031_50310402_108_dialog_content = "Si tan solo las reglas permitieran el Moon Cocoon... Humph. ¡Tomen eso, ustedes Eclipsites!",
  ui_story_5031_50310402_108X1_dialog_content = "Si tan solo tuviera un nuevo poder como Vice obtuvo...!",
  ui_story_5031_50310402_108X2_dialog_content = "Cálmate, Carleen.",
  ui_story_5031_50310402_108X3_dialog_content = "Solo deja ir tu conciencia como Vice dijo...",
  ui_story_5031_50310402_108X4_dialog_content = "Suelta... Respira.",
  ui_story_5031_50310402_108X5_dialog_content = "Carleen.",
  ui_story_5031_50310402_108X6_dialog_content = "Padre...",
  ui_story_5031_50310402_108X7_dialog_content = "Tú y yo sabemos que los Eclipsites no pueden ser eliminados.",
  ui_story_5031_50310402_108X8_dialog_content = "Las acciones imprudentes solo conducen a la muerte de los soldados que creyeron en ti.",
  ui_story_5031_50310402_108X9_dialog_content = "Sin un gran poder, no puedes defender a ningún ser querido.",
  ui_story_5031_50310402_108X10_dialog_content = "No eres lo suficientemente fuerte... Debes encontrar una manera... de ser más fuerte.",
  ui_story_5031_50310402_108X11_dialog_content = "Estoy muy decepcionado...",
  ui_story_5031_50310402_108X12_dialog_content = "No... ¡Eso no es cierto, Padre!",
  ui_story_5031_50310402_108X13_dialog_content = "¡Carleen!",
  ui_story_5031_50310402_108X14_dialog_content = "Graah!",
  ui_story_5031_50310402_108X15_dialog_content = "¡¡Batirlo!!",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310402_110_dialog_content = "¡N-No puedes usar los puños! No obtendremos puntos.",
  ui_story_5031_50310402_111_dialog_content = "Cálmate, Carleen! ¡Primero tenemos que encontrar PlayerName!",
  ui_story_5031_50310402_112_dialog_content = "... Lo siento. Estás bien.",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310402_114_dialog_content = "\"¡El partido ha terminado! Todos los participantes restantes, diríjanse al podio del juez para anotar\".",
  ui_story_5031_50310402_115_dialog_content = "Gran trabajo, Carleen. ¡Pasamos a la siguiente ronda!",
  ui_story_5031_50310402_116_dialog_content = "Bueno, gran parte fue gracias a PlayerName por sacarnos del círculo de Rediesel Wrench.",
  ui_story_5031_50310402_117_dialog_content = "Con no poco riesgo para ti mismo. No lo permitiría en una batalla real.",
  ui_story_5031_50310402_118_dialog_content = "¡Ajá, Caelestite en realidad cree que salvó a todos!",
  ui_story_5031_50310402_119_dialog_content = "¿Eh? Azure? ¿Qué quieres decir?",
  ui_story_5031_50310402_120_dialog_content = "Un tipo de Lumo buscó una pelea de la nada. Nos distrajo mal.",
  ui_story_5031_50310402_121_dialog_content = "Puedes agradecer a tus estrellas de la suerte que lo hizo... Sin él, habrías estado frito.",
  ui_story_5031_50310402_122_dialog_content = "Pero fue mucho más divertido derribarlo que jugar este tonto juego de niños con pistolas de agua.",
  ui_story_5031_50310402_123_dialog_content = "Se llamaba a sí mismo noble, no se parece a ningún noble que haya visto, y nos mantuvo bien ocupados.",
  ui_story_5031_50310402_124_dialog_content = "Una lástima que ese tipo tranquilo lo arrastró. Podríamos haber luchado mucho y duro.",
  ui_story_5031_50310402_125_dialog_content = "B-jefe...",
  ui_story_5031_50310402_126_dialog_content = "¿Te atreves a mostrar tu cara de nuevo?",
  ui_story_5031_50310402_127_dialog_content = "No vamos en contra de las mujeres y los niños. ¡¿Olvidaste?!",
  ui_story_5031_50310402_128_dialog_content = "Lo siento mucho. No sé lo que me pasó.",
  ui_story_5031_50310402_129_dialog_content = "Comience con flexiones lejos de la plataforma principal. Me ocuparé de ti después de mi trago.",
  ui_story_5031_50310402_130_dialog_content = "¡S-Sí, jefe!",
  ui_story_5031_50310402_131_dialog_content = "Siempre lloviendo en mi desfile...",
  ui_story_5031_50310402_132_dialog_content = "No me di cuenta de que la llave Rediesel tenía ese lado.",
  ui_story_5031_50310402_133_dialog_content = "Lo tomaré como un cumplido. Muy bien, princesa, voy a beber con Azure. Nos vemos.",
  ui_story_5031_50310402_134_dialog_content = "¡Adiós! Estamos consiguiendo el alcohol gratis allí. Hola Caelestite, eres bienvenido a venir.",
  ui_story_5031_50310402_135_dialog_content = "Uf... De alguna manera hemos terminado con un oponente menos del que preocuparnos.",
  ui_story_5031_50310402_136_dialog_content = "pienso Gronru y su amiga también sobrevivió. De hecho, obtuvieron una puntuación bastante alta.",
  ui_story_5031_50310402_137_dialog_content = "No esperaba que todos se lo tomaran tan en serio. Mirar Jona y Azure—¡eliminado en la primera ronda!",
  ui_story_5031_50310402_138_dialog_content = "Estoy seguro de que la próxima ronda solo será... más intensa, desgarradora y antagónica...",
  ui_story_5031_50310402_139_dialog_content = "Ronroneo.",
  ui_story_5031_50310402_140_dialog_content = "¡Eso fue bastante audible!",
  ui_story_5031_50310402_141_dialog_content = "¡Solo construyendo sobre tu atmósfera ansiosa!",
  ui_story_5031_50310402_142_dialog_content = "Saludos, Laird.",
  ui_story_5031_50310402_143_dialog_content = "Saludos. Estabas...",
  ui_story_5031_50310402_144_dialog_content = "Así es. Soy Subli.",
  ui_story_5031_50310402_145_dialog_content = "Jeno me hizo traerte esto como regalo.",
  ui_story_5031_50310402_146_dialog_content = "¿Y esto es...?",
  ui_story_5031_50310402_147_dialog_content = "Una manta. Le preocupaba que pudieras resfriarte con esta brisa marina.",
  ui_story_5031_50310402_148_dialog_content = "... Ya veo. Transmitir mi agradecimiento.",
  ui_story_5031_50310402_149_dialog_content = "Y gracias también, Subli.",
  ui_story_5031_50310402_150_dialog_content = "Jeje, no lo menciones.",
  ui_story_5031_50310402_151_dialog_content = "...",
  ui_story_5031_50310501_1_dialog_content = "¡Los saludo, valientes guerreros, que han superado la primera ronda!",
  ui_story_5031_50310501_2_dialog_content = "No hay duda de que todos ustedes han demostrado su valía en este viaje hacia el tesoro supremo.",
  ui_story_5031_50310501_3_dialog_content = "Nuestras reglas para la próxima ronda también son extremadamente simples.",
  ui_story_5031_50310501_4_dialog_content = "Estoy seguro de que todos ustedes han tenido el beneficio de jugar un juego muy similar cuando eran niños.",
  ui_story_5031_50310501_5_dialog_content = "¡Sal, oh bestia cobarde que se retuerce en las horas del crepúsculo! ¡Oh guardián de extraños artefactos y hechicerías!",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>Ruido sordo...!</color>",
  ui_story_5031_50310501_7_dialog_content = "Mira, este es nuestro Guardián del Secreto en esta ronda.",
  ui_story_5031_50310501_8_dialog_content = "Ejem. Ahora, repasaré algunas de las reglas.",
  ui_story_5031_50310501_9_dialog_content = "Cuando este eclipse único se vuelva verde...",
  ui_story_5031_50310501_10_dialog_content = "Debe llegar a él lo más rápido que pueda, pasando todos los demás Eclipsites que lo bloquean.",
  ui_story_5031_50310501_11_dialog_content = "Simplemente cruce esta línea a sus pies para calificar para la siguiente ronda.",
  ui_story_5031_50310501_12_dialog_content = "¡Tenga cuidado cuando se ponga rojo!",
  ui_story_5031_50310501_13_dialog_content = "No se permite el movimiento de Aurorianos o Eclipsitas en ese momento. Si lo hace, será arrojado por la borda por el Eclipsite más cercano y luego estará fuera.",
  ui_story_5031_50310501_14_dialog_content = "Cualquiera que no llegue a la línea de meta al final también está fuera.",
  ui_story_5031_50310501_15_dialog_content = "Y puede sentirse libre de usar Luminatics apropiados. No hay restricciones ahora.",
  ui_story_5031_50310501_16_dialog_content = "Exactamente. ¡Entonces vamos! ¡Muéstranos lo que tienes! ¡Desafía a mi criatura por el premio!",
  ui_story_5031_50310501_17_dialog_content = "PlayerName.",
  ui_story_5031_50310501_18_dialog_content = "Sí. Ahora finalmente puedo usar mis puntos fuertes.",
  ui_story_5031_50310501_19_dialog_content = "No te preocupes. ¡Ayudaré a todos a llegar a la meta a tiempo!",
  ui_story_5031_50310502_1_dialog_content = "¡je! ¡Incluso yo podría sacar un Eclipsite así!",
  ui_story_5031_50310502_2_dialog_content = "¡Observen y aprendan, asquerosos Eclipsitas!",
  ui_story_5031_50310502_3_dialog_content = "¡Oye! El grande está a punto de cambiar de color. ¡Mejor para!",
  ui_story_5031_50310502_4_dialog_content = "¡Dame un segundo! ¡Puedo tomar la iniciativa!",
  ui_story_5031_50310502_5_dialog_content = "idiotas Estás a punto de ser eliminado, ¿no lo sabes?",
  ui_story_5031_50310502_6_dialog_content = "Por cierto, tengo que agradecerte por ganar puntos en la última ronda mientras yo estaba comprometido con esos dos bandidos.",
  ui_story_5031_50310502_7_dialog_content = "Nunca supe que fueran tan duros... Eso fue un buen calentamiento.",
  ui_story_5031_50310502_8_dialog_content = "Si no me hubieras apartado... ¡Podría haber hecho un ejemplo de ellos!",
  ui_story_5031_50310502_9_dialog_content = "...",
  ui_story_5031_50310502_10_dialog_content = "Gesto de desaprobación. ¡Estoy tratando de felicitarte, mi hombre! ¿Tu Luminatic selló tu boca?",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310502_12_dialog_content = "¡Cambió de color!",
  ui_story_5031_50310502_13_dialog_content = "Graah!",
  ui_story_5031_50310502_14_dialog_content = "¡N-No vengas!",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>¡¡Plaf!!</color>",
  ui_story_5031_50310502_17_dialog_content = "¡Se van! Plebeyos por nombre, plebeyos por naturaleza...",
  ui_story_5031_50310502_18_dialog_content = "No debemos aventurarnos demasiado lejos de la princesa. Protégela en lugares más cercanos.",
  ui_story_5031_50310502_19_dialog_content = "No podemos dejar que se bañe en el mar como esas pobres almas tontas.",
  ui_story_5031_50310502_20_dialog_content = "Gracias por la manta, Jeno.",
  ui_story_5031_50310502_21_dialog_content = "De nada. Manténgase caliente, manténgase bien. Parece que una fuerte brisa te soplaría.",
  ui_story_5031_50310502_22_dialog_content = "Jeje. Un juego extraño para un adulto de tus años, ¿no?",
  ui_story_5031_50310502_23_dialog_content = "¿En qué manera? ¿Es demasiado infantil?",
  ui_story_5031_50310502_24_dialog_content = "De nada. Estoy un poco sorprendido.",
  ui_story_5031_50310502_25_dialog_content = "Todavía disfrutas este juego incluso después de todos estos años, incluso tráelo de vuelta para esta ronda...",
  ui_story_5031_50310502_26_dialog_content = "Porque soy una persona bastante nostálgica.",
  ui_story_5031_50310502_27_dialog_content = "También estoy maldecido con una larga memoria. Por ejemplo, algo tan insignificante como una cita perdida hace muchos años, por la que esperé un día entero.",
  ui_story_5031_50310502_28_dialog_content = "... Me disculpo por no haber dicho adiós hace tantos años.",
  ui_story_5031_50310502_29_dialog_content = "Eso está bien.",
  ui_story_5031_50310502_30_dialog_content = "¿...?",
  ui_story_5031_50310502_31_dialog_content = "Sólo quería oírte decir eso.",
  ui_story_5031_50310502_32_dialog_content = "Sólo puedo imaginar...",
  ui_story_5031_50310502_33_dialog_content = "Imagínese todas las tribulaciones involucradas en abrirse camino desde el hijo del dueño de un restaurante hasta el laird de Harbor City.",
  ui_story_5031_50310502_34_dialog_content = "Pero todavía tengo la fuerte impresión de que no has cambiado en absoluto en muchos otros aspectos importantes. Espero que no se equivoque.",
  ui_story_5031_50310502_35_dialog_content = "¿De qué maneras importantes?",
  ui_story_5031_50310502_36_dialog_content = "Como los ejercicios aeróbicos que implementaste en Harbour City. Muy tonto pero... muy tú.",
  ui_story_5031_50310502_37_dialog_content = "¡Jajaja! Tonto, pero efectivo para ayudar a todos a mantenerse en forma.",
  ui_story_5031_50310502_38_dialog_content = "¿Y usted? Te busqué durante mucho tiempo después de regresar a Lumopolis. Nadie sabía tu paradero.",
  ui_story_5031_50310502_39_dialog_content = "¿Yo?",
  ui_story_5031_50310502_40_dialog_content = "Te busqué durante mucho tiempo después de regresar a Harbor City. Nadie sabía adónde habías ido.",
  ui_story_5031_50310502_41_dialog_content = "Algunos incluso me dijeron que tú y tu familia ya no estaban con nosotros...",
  ui_story_5031_50310502_42_dialog_content = "Un resumen justo.",
  ui_story_5031_50310502_43_dialog_content = "La providencia nos entregó un escape hacia el Emerald y, como refugiados que huyen de la crisis de Darkover, nos apoderamos de nuestra balsa salvavidas por todo lo que valía.",
  ui_story_5031_50310502_44_dialog_content = "Como el destino lo tendría, finalmente fui salvado por Lady Victoria del Orden Verdadero.",
  ui_story_5031_50310502_45_dialog_content = "Ella también me dotó con la habilidad de manipular el Origen.",
  ui_story_5031_50310502_46_dialog_content = "Fue solo cuando regresé al Emerald que me enteré de que mis padres habían fallecido.",
  ui_story_5031_50310502_47_dialog_content = "Y, por supuesto, culpé al maestro de ceremonias anterior por su desaparición. Lo reté a duelo en mi ira.",
  ui_story_5031_50310502_48_dialog_content = "La verdad tardó en llegar, lo suficiente para que el viejo maestro de ceremonias perdonara esta indiscreción.",
  ui_story_5031_50310502_49_dialog_content = "Y luego solo estábamos yo, la Esmeralda y otros miembros del circo en nuestro viaje a través de alta mar.",
  ui_story_5031_50310502_50_dialog_content = "Lo siento... Eran buenas personas.",
  ui_story_5031_50310502_51_dialog_content = "No necesitas disculparte. No fue tu culpa.",
  ui_story_5031_50310502_52_dialog_content = "Puede que esté aprovechando True Order para avanzar en mi carrera como mago...",
  ui_story_5031_50310502_53_dialog_content = "Pero, a decir verdad, me importa poco la Orden y sus doctrinas.",
  ui_story_5031_50310502_54_dialog_content = "De todos modos, la Orden tiene tantas sectas... Me temo que probablemente estoy en el tipo más \"desviado\".",
  ui_story_5031_50310502_55_dialog_content = "Sin embargo, debo honrar la promesa que le hice a Lady Victoria por su amabilidad.",
  ui_story_5031_50310502_56_dialog_content = "Nunca quiero traicionar una promesa...",
  ui_story_5031_50310502_57_dialog_content = "Una promesa... *Tose*",
  ui_story_5031_50310502_58_dialog_content = "¿Es eso… estás tosiendo sangre?",
  ui_story_5031_50310502_59_dialog_content = "Estoy bien. Un poco sobrecargado de política... y también este maldito frío...",
  ui_story_5031_50310502_60_dialog_content = "¿Me tomas por tonto?",
  ui_story_5031_50310502_61_dialog_content = "¡Ja ja! Lejos de ahi. Estoy muy saludable, gracias.",
  ui_story_5031_50310502_62_dialog_content = "¿O quieres usar tus poderes de adivinación para ver mi futuro? Estoy seguro de que me quedan otros 200 años por lo menos.",
  ui_story_5031_50310502_63_dialog_content = "¿Adivinación? Por favor. ¡Puedes decirme la verdad!",
  ui_story_5031_50310502_64_dialog_content = "*Jadeando* Bueno, como antiguo residente de Harbor City, ¿debes estar familiarizado con los llamados \"Héroes legendarios\"?",
  ui_story_5031_50310502_65_dialog_content = "Por supuesto. Un cuento para dormir para niños pequeños.",
  ui_story_5031_50310502_66_dialog_content = "... Pero ese cuento antes de dormir es real.",
  ui_story_5031_50310502_67_dialog_content = "...",
  ui_story_5031_50310502_68_dialog_content = "En pocas palabras, sellaron los Eclipsites con algún tipo de pacto de sangre.",
  ui_story_5031_50310502_69_dialog_content = "Los Eclipsites afectados cayeron en una hibernación profunda, mientras que Harbor City ha sido protegido de manera efectiva para que no se acerque.",
  ui_story_5031_50310502_70_dialog_content = "Pero esto tuvo un costo, no solo para ellos, sino también para sus descendientes.",
  ui_story_5031_50310502_71_dialog_content = "Y esta es la verdadera fuente de la condición conocida como síndrome de Modali.",
  ui_story_5031_50310502_72_dialog_content = "¿Qué? ¿Es por eso que tienes esa cicatriz en la cara? ¿Síndrome modal?",
  ui_story_5031_50310502_73_dialog_content = "*Tose* Efectivamente. Pero no te preocupes. Estoy... ugh... lidiando bastante bien.",
  ui_story_5031_50310502_74_dialog_content = "Si se selló con un pacto, ¿hay alguna forma de deshacerlo?",
  ui_story_5031_50310502_75_dialog_content = "Quizás. Eso es lo que he estado buscando en estos largos años... una solución.",
  ui_story_5031_50310502_76_dialog_content = "¿Y qué has encontrado?",
  ui_story_5031_50310502_77_dialog_content = "Lo siento, no tengo nada adecuado para compartir todavía. Y hay secretos e intereses involucrados que no se pueden contar de manera simple o ligera.",
  ui_story_5031_50310502_78_dialog_content = "...",
  ui_story_5031_50310502_79_dialog_content = "¡Mirar! ¡Esa chica es una potencia! ¡Ella está corriendo adelante!",
  ui_story_5031_50310502_80_dialog_content = "¡Su compañero ni siquiera usa Luminatics! ¿Cómo es que ella todavía toma la iniciativa?",
  ui_story_5031_50310502_81_dialog_content = "¿Quién no puede usar Luminatics? ¿Es un Caelestita?",
  ui_story_5031_50310502_82_dialog_content = "¿Qué? ¡Veamos la Caelestita!",
  ui_story_5031_50310502_83_dialog_content = "Maestro de ceremonias, ¿puedo molestarlo un segundo? Un nuevo lote de suministros. Solo necesito que cierres la sesión.",
  ui_story_5031_50310502_84_dialog_content = "Por supuesto. Llego en un momento.",
  ui_story_5031_50310502_85_dialog_content = "Me temo que tendrás que juzgar solo hasta que yo regrese.",
  ui_story_5031_50310502_86_dialog_content = "Adelante, Jeno.",
  ui_story_5031_50310602_1_dialog_content = "\"Ronda 2, carrera: ¡comienza!\"",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310602_3_dialog_content = "¡PlayerName! ¡Quédate cerca de nosotros!",
  ui_story_5031_50310602_4_dialog_content = "Manténgase cerca de PlayerName, Vice y fia! No dejes que los eclipses lo atrapen.",
  ui_story_5031_50310602_5_dialog_content = "¡Entendido!",
  ui_story_5031_50310602_6_dialog_content = "No me di cuenta de que teníamos tan poco tiempo para movernos. Lo siento, no puedo ser de más ayuda.",
  ui_story_5031_50310602_7_dialog_content = "Creo que algunos Aurorianos ya han llegado corriendo con sus Lumináticos.",
  ui_story_5031_50310602_8_dialog_content = "No importa. Solo tenemos que concentrarnos.",
  ui_story_5031_50310602_9_dialog_content = "PlayerName, necesito que me des un camino a seguir.",
  ui_story_5031_50310602_10_dialog_content = "¡Entendido!",
  ui_story_5031_50310602_11_dialog_content = "Ah...",
  ui_story_5031_50310602_12_dialog_content = "Me irrita en muchos niveles. Sé que las reglas dicen mantener la distancia con Su Alteza, pero no puedo permitirlo.",
  ui_story_5031_50310602_13_dialog_content = "Oye, ¿tú no eres... ese juez? Yo recuerdo.",
  ui_story_5031_50310602_14_dialog_content = "De hecho, soy el juez Matthieu, Su Alteza, y esta silenciosa lata de frijoles a mi lado es mi socio, Loewe.",
  ui_story_5031_50310602_15_dialog_content = "me doy cuenta pobre Pittman ha estado bajo su gracia, pero lo que deseo decir es—",
  ui_story_5031_50310602_16_dialog_content = "Su Alteza... se merece algo mejor.",
  ui_story_5031_50310602_17_dialog_content = "Un poderoso guerrero no debe estar unido por las caderas a alguien incapaz de la Luminática rudimentaria.",
  ui_story_5031_50310602_18_dialog_content = "Ya habrías calificado a estas alturas sin el obstáculo de este Caelestita, incluso si supuestamente está ayudando.",
  ui_story_5031_50310602_19_dialog_content = "Veo en el caelestita la misma desdichada dependencia de todos los plebeyos.",
  ui_story_5031_50310602_20_dialog_content = "¡¿Q-Qué?!",
  ui_story_5031_50310602_21_dialog_content = "No le hagas caso.",
  ui_story_5031_50310602_22_dialog_content = "¿Qué?",
  ui_story_5031_50310602_23_dialog_content = "Está un poco retorcido por dentro.",
  ui_story_5031_50310602_24_dialog_content = "¡Oye! ¡¿Qué estas diciendo?!",
  ui_story_5031_50310602_25_dialog_content = "¡Dime más! Quiero escuchar más.",
  ui_story_5031_50310602_26_dialog_content = "Por lo general, finge ser tolerante.",
  ui_story_5031_50310602_27_dialog_content = "Pero él, de hecho, odia a los plebeyos.",
  ui_story_5031_50310602_28_dialog_content = "Pero ha construido una neurosis masiva contra los plebeyos...",
  ui_story_5031_50310602_29_dialog_content = "Lo cual es divertido teniendo en cuenta sus propios antecedentes...",
  ui_story_5031_50310602_30_dialog_content = "¡Oye! ¡Ni una palabra más! ¡Lo prohíbo! ¡Vuelve a tu silencio!",
  ui_story_5031_50310602_31_dialog_content = "¡Oirás y obedecerás! ¡Deténgase!",
  ui_story_5031_50310602_32_dialog_content = "... ¡Callarse la boca!",
  ui_story_5031_50310602_33_dialog_content = "Gesto de desaprobación.",
  ui_story_5031_50310602_34_dialog_content = "Pensé que todos los nobles de Lumopolis menospreciaban a los plebeyos en diferentes grados.",
  ui_story_5031_50310602_35_dialog_content = "No es lo mismo.",
  ui_story_5031_50310602_X35_dialog_content = "Se lava la mano al menos diez veces si alguien le toca la mano por accidente.",
  ui_story_5031_50310602_X36_dialog_content = "Grita cuando el polvo cae sobre él.",
  ui_story_5031_50310602_36_dialog_content = "Oh... May también vivir dentro de un caso y acabar con el mundo exterior.",
  ui_story_5031_50310602_37_dialog_content = "Sí, está obsesionado con la limpieza a un nivel loco.",
  ui_story_5031_50310602_38_dialog_content = "Siento mucho escuchar eso...",
  ui_story_5031_50310602_39_dialog_content = "¡No necesito lástima de una muchacha atrasada como tú!",
  ui_story_5031_50310602_40_dialog_content = "Él holgazanea en el trabajo.",
  ui_story_5031_50310602_41_dialog_content = "¿Perezoso en el trabajo, dices? No estás pintando un cuadro impresionante.",
  ui_story_5031_50310602_42_dialog_content = "Y se aprovecha de los sentimientos de sus antiguos compañeros de clase.",
  ui_story_5031_50310602_X42_dialog_content = "Empuja las cosas a Pittma...",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310602_44_dialog_content = "¡Está cambiando de color! ¡Mantengan sus caballos, todos!",
  ui_story_5031_50310602_45_dialog_content = "¡Oh, no!",
  ui_story_5031_50310602_46_dialog_content = "¡No puedo dejar de correr! ¡Ayúdame!",
  ui_story_5031_50310602_47_dialog_content = "¡A-Aléjate de mí, sucio plebeyo!",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5031_50310602_49_dialog_content = "Lo siento mucho, señor.",
  ui_story_5031_50310602_50_dialog_content = "¡Escapar! ¡Lejos!",
  ui_story_5031_50310602_51_dialog_content = "¡Mi ropa! ¡Necesito llegar a un vestuario!",
  ui_story_5031_50310602_52_dialog_content = "¡Vuelvo a darme un baño, Loewe!",
  ui_story_5031_50310602_53_dialog_content = "Es un comedor quisquilloso.",
  ui_story_5031_50310602_54_dialog_content = "Dice que su lengua es igual de sensible al calor.",
  ui_story_5031_50310602_55_dialog_content = "Gritando cosas como: \"¡Ah! ¡Qué calor!\"",
  ui_story_5031_50310602_56_dialog_content = "¡Y me hace echarle un vistazo!",
  ui_story_5031_50310602_57_dialog_content = "No quiero mirarlo en absoluto.",
  ui_story_5031_50310602_58_dialog_content = "¡Tres han sido eliminados!",
  ui_story_5031_50310602_59_dialog_content = "¡Hablaré contigo más tarde!",
  ui_story_5031_50310602_60_dialog_content = "Tuve una sensación tan diferente de la impresión de la apariencia. Esta manera breve y concisa de hablar es impresionante.",
  ui_story_5031_50310602_X60_dialog_content = "Sí, parece una persona interesante.",
  ui_story_5031_50310602_61_dialog_content = "Lo siento, Carleen.",
  ui_story_5031_50310602_62_dialog_content = "¿Para qué? No escuches nada de lo que dijo Matthieu.",
  ui_story_5031_50310602_63_dialog_content = "Te esfuerzas mucho, pero no soy muy bueno en una pelea. A veces creo que te estoy defraudando.",
  ui_story_5031_50310602_64_dialog_content = "¿Crees que me estoy esforzando demasiado? ¿Es por eso que dices eso?",
  ui_story_5031_50310602_65_dialog_content = "Sí. Creo que has sido el mejor competidor en este carnaval... llevando a nuestro equipo sobre tus hombros.",
  ui_story_5031_50310602_66_dialog_content = "¿Tú crees que...?",
  ui_story_5031_50310602_67_dialog_content = "Nunca te he considerado una carga. De hecho, ¡eres nuestra arma secreta con todas las cosas que puedes hacer!",
  ui_story_5031_50310602_68_dialog_content = "Por supuesto, PlayerName. Siempre has sido un compañero muy importante.",
  ui_story_5031_50310602_69_dialog_content = "Gracia divina. PlayerName, no puedes dejarte influenciar por lo que dice un bicho raro al azar.",
  ui_story_5031_50310602_70_dialog_content = "A todos...",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310602_72_dialog_content = "Es verde ahora. ¡Prepararse!",
  ui_story_5031_50310602_73_dialog_content = "Bueno. ¡Todos, sigan recto!",
  ui_story_5031_50310701_1_dialog_content = "Ya casi llegamos, PlayerName.",
  ui_story_5031_50310701_2_dialog_content = "Solo unos pocos pasos más para la siguiente ronda...",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310701_4_dialog_content = "¡Todos, muévanse!",
  ui_story_5031_50310701_5_dialog_content = "¡Espera, para!",
  ui_story_5031_50310701_6_dialog_content = "¡Ha vuelto al color original ahora!",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>¡Anillo-anillo!</color>",
  ui_story_5031_50310701_8_dialog_content = "¿Qué sucedió? ¿Se está volviendo más rápido?",
  ui_story_5031_50310701_9_dialog_content = "¡Ay!",
  ui_story_5031_50310701_10_dialog_content = "¡Ay! ¡Está girando muy rápido ahora!",
  ui_story_5031_50310701_11_dialog_content = "Están probando los tiempos de reacción; de lo contrario, ¿por qué hacerlo tan impredecible?",
  ui_story_5031_50310701_12_dialog_content = "Tenemos que andar con cuidado ahora.",
  ui_story_5031_50310701_13_dialog_content = "¡Otros cuatro concursantes son eliminados!",
  ui_story_5031_50310701_14_dialog_content = "Ves a esa chica de ahí, Carleen? Creo que algo anda mal con ella.",
  ui_story_5031_50310701_15_dialog_content = "Ella no se ve muy feliz. Puedo sentir que su poder de Lumina se debilita cada segundo.",
  ui_story_5031_50310701_16_dialog_content = "Boo-hoo...",
  ui_story_5031_50310701_17_dialog_content = "Oh, no. ¡Está colapsada!",
  ui_story_5031_50310701_18_dialog_content = "¿No significa eso que la van a tirar al agua?",
  ui_story_5031_50310701_19_dialog_content = "Parece que le duele con los ojos cerrados.",
  ui_story_5031_50310701_20_dialog_content = "¡No la pueden tirar al mar si tiene una condición médica!",
  ui_story_5031_50310701_21_dialog_content = "PlayerName, PlayerName, tenemos que pensar en algo.",
  ui_story_5031_50310701_22_dialog_content = "Grah...",
  ui_story_5031_50310701_23_dialog_content = "¡No podemos esperar más!",
  ui_story_5031_50310701_24_dialog_content = "¡Carleen!",
  ui_story_5031_50310702_1_dialog_content = "¡¡Se acabó el tiempo!!",
  ui_story_5031_50310702_2_dialog_content = "¿Cuál es el problema, Su Alteza?",
  ui_story_5031_50310702_3_dialog_content = "Esta señora no se encuentra bien.",
  ui_story_5031_50310702_4_dialog_content = "Le echaré un vistazo. Conozco algo de medicina.",
  ui_story_5031_50310702_5_dialog_content = "¿Estás bien, jovencita? ¿Puedes escucharme?",
  ui_story_5031_50310702_6_dialog_content = "Boo-hoo...",
  ui_story_5031_50310702_7_dialog_content = "Conozco la condición... Síndrome de Modali.",
  ui_story_5031_50310702_8_dialog_content = "Rápido, toma esta pastilla.",
  ui_story_5031_50310702_9_dialog_content = "¿Puedo molestarte en traer esa manta, Jeno?",
  ui_story_5031_50310702_10_dialog_content = "Seguro.",
  ui_story_5031_50310702_11_dialog_content = "Resoplan...",
  ui_story_5031_50310702_12_dialog_content = "Laird Elvis... Gracias. Me siento mucho mejor.",
  ui_story_5031_50310702_13_dialog_content = "No te esfuerces demasiado. La temperatura de tu cuerpo es baja. Estarás más cómodo con una manta.",
  ui_story_5031_50310702_14_dialog_content = "Sí... Gracias, señor, usted nos enseñó los ejercicios aeróbicos y siempre he bebido agua tibia.",
  ui_story_5031_50310702_15_dialog_content = "Sí, muy bien, Ranka. Estoy orgulloso de ti.",
  ui_story_5031_50310702_16_dialog_content = "La manta, Elvis.",
  ui_story_5031_50310702_17_dialog_content = "ah Gracias.",
  ui_story_5031_50310702_18_dialog_content = "Patou!",
  ui_story_5031_50310702_19_dialog_content = "Aquí estoy, señor.",
  ui_story_5031_50310702_20_dialog_content = "Haga que los guardias la lleven de regreso con su familia y recuérdeles la urgencia de una visita al hospital.",
  ui_story_5031_50310702_21_dialog_content = "¡Déjelo a mí, señor!",
  ui_story_5031_50310702_22_dialog_content = "¿Ves lo joven que es, Jeno?",
  ui_story_5031_50310702_23_dialog_content = "...",
  ui_story_5031_50310702_24_dialog_content = "Laird Elvis, eres un laird fiel y bondadoso de Harbor City.",
  ui_story_5031_50310702_25_dialog_content = "Hoy he visto más nobleza en ti que en toda una vida de muchos supuestos nobles.",
  ui_story_5031_50310702_26_dialog_content = "Harbor City es realmente afortunada de tener un laird como tú.",
  ui_story_5031_50310702_27_dialog_content = "Sheesh. Ella es solo otra plebeya. Creo que ha perdido la perspectiva, Su Alteza.",
  ui_story_5031_50310702_28_dialog_content = "Tan desagradable ser... semi-asaltado por ese plebeyo eliminado.",
  ui_story_5031_50310702_29_dialog_content = "Casi me arrojan al mar. Pero logré volver a levantarme.",
  ui_story_5031_50310702_30_dialog_content = "¿Cuándo diablos podemos volver para bañarnos y cambiarnos de ropa?",
  ui_story_5031_50310702_31_dialog_content = "Calla.",
  ui_story_5031_50310702_32_dialog_content = "Gracias por sus amables palabras, Su Alteza.",
  ui_story_5031_50310702_33_dialog_content = "Pero no puedo ayudar mucho más que eso.",
  ui_story_5031_50310702_34_dialog_content = "Lo siento, pero el deber urgente llama. Hasta más tarde.",
  ui_story_5031_50310702_35_dialog_content = "Seguramente.",
  ui_story_5031_50310702_36_dialog_content = "...",
  ui_story_5031_50310702_37_dialog_content = "¿Envió por mí, señor?",
  ui_story_5031_50310702_38_dialog_content = "Nos estamos quedando sin tiempo, Patou.",
  ui_story_5031_50310702_39_dialog_content = "los <color=#FFB400>Piedra de viento</color> se vuelve más débil. Puedo sentirlo.",
  ui_story_5031_50310702_40_dialog_content = "Es por eso que yo, y luego la niña, caímos bajo esta enfermedad.",
  ui_story_5031_50310702_41_dialog_content = "Me temo que el sello no durará mucho más.",
  ui_story_5031_50310702_42_dialog_content = "¿Por qué no buscar ayuda en Lumopolis, señor? ¿Qué hay de esa dama de buen corazón, princesa? Carleen?",
  ui_story_5031_50310702_43_dialog_content = "Ella podría ponernos en contacto con el Señor Schwartz.",
  ui_story_5031_50310702_44_dialog_content = "Confío en que Señor Schwartz tiene la perspicacia para ayudarnos en este asunto.",
  ui_story_5031_50310702_45_dialog_content = "Pero mi razón me dice que no confíe en el Consejo de Ancianos.",
  ui_story_5031_50310702_46_dialog_content = "¿Qué es más probable? ¿Que enviarán tropas para defender Harbor City? ¿O pedirnos que abandonemos la tierra que hemos heredado durante generaciones?",
  ui_story_5031_50310702_47_dialog_content = "Piensa en el coste que pagaron nuestros antepasados para proteger el secreto de Windstone... Está bien guardado incluso hoy.",
  ui_story_5031_50310702_48_dialog_content = "Si su existencia se rumorea en el extranjero, también podríamos tener que lidiar con aquellos que quieren tomarlo.",
  ui_story_5031_50310702_49_dialog_content = "Entonces, sin Windstone, Harbour City seguramente se perderá.",
  ui_story_5031_50310702_50_dialog_content = "No daré a la destrucción aquello por lo que nuestros antepasados dieron su vida y que generaciones han construido con sudor y trabajo.",
  ui_story_5031_50310702_51_dialog_content = "Todo lo que hago es por la seguridad de Harbor City. La realidad es que estamos solos.",
  ui_story_5031_50310702_52_dialog_content = "Sí, señor. Entiendo.",
  ui_story_5031_50310702_53_dialog_content = "Con mucho gusto ofrecemos nuestras vidas a fuego y espada en defensa de Harbor City y House Modali.",
  ui_story_5031_50310702_54_dialog_content = "Y no hay forma de volver atrás.",
  ui_story_5031_50310702_55_dialog_content = "La derrota significará el fin de Harbor City y sus residentes. Nadie viene a salvarnos.",
  ui_story_5031_50310702_56_dialog_content = "Debemos aprender a salvarnos, Patou.",
  ui_story_5031_50310702_57_dialog_content = "Princesa Carleen, ¿estás seguro de mantener tu identidad oculta?",
  ui_story_5031_50310702_58_dialog_content = "Sí. No quiero que nada se interponga entre mí y nuestras relajantes vacaciones. Gracias por su comprensión, Laird Elvis.",
  ui_story_5031_50310702_59_dialog_content = "Muy bien.",
  ui_story_5031_50310702_60_dialog_content = "Escúchenme, todos.",
  ui_story_5031_50310702_61_dialog_content = "La dama que acaba de colapsar por enfermedad habría sido arrojada por la borda por Eclipsites de acuerdo con nuestras reglas.",
  ui_story_5031_50310702_62_dialog_content = "¡Sin embargo, esta valiente dama y sus compañeros se arriesgaron a ser descalificados para salvarla de una situación peligrosa!",
  ui_story_5031_50310702_63_dialog_content = "Podría haber caído inconsciente al agua.",
  ui_story_5031_50310702_64_dialog_content = "Es posible que hayan infringido las reglas, ¡pero recompensamos el tipo de corazón aquí en Harbor City!",
  ui_story_5031_50310702_65_dialog_content = "... Y dado que esta es nuestra costumbre, ¡espero que se unan a mí para dar la bienvenida a su equipo nuevamente a la competencia!",
  ui_story_5031_50310702_66_dialog_content = "¡Hurra! ¡Hurra!",
  ui_story_5031_50310702_67_dialog_content = "¡Eres increíble, Laird Elvis!",
  ui_story_5031_50310702_68_dialog_content = "¡Gracias a todos! Me siento honrado de ser su gobernador.",
  ui_story_5031_50310702_69_dialog_content = "¡Gracias, Laird Elvis!",
  ui_story_5031_50310702_70_dialog_content = "No lo menciones. Estoy seguro de que todos vosotros habríais hecho lo mismo.",
  ui_story_5031_50310702_71_dialog_content = "Usted y sus acompañantes pueden regresar al partido.",
  ui_story_5031_50310702_X71_dialog_content = "¡Entonces continuemos!",
  ui_story_5031_50310702_X72_dialog_content = "¡Uf, uf...! Ustedes están corriendo demasiado rápido. Incluso hemos llegado a la línea de meta de alguna manera.",
  ui_story_5031_50310702_X73_dialog_content = "¡Date prisa, PlayerName! ¡Está cambiando de color otra vez!",
  ui_story_5031_50310702_X74_dialog_content = "¿En serio? No, ya no puedo más.",
  ui_story_5031_50310702_72_dialog_content = "Corre aquí, PlayerName. ¡Te atraparemos!",
  ui_story_5031_50310702_73_dialog_content = "¡Entendido!",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5031_50310702_75_dialog_content = "Eso estuvo cerca.",
  ui_story_5031_50310702_76_dialog_content = "Eres muy pesado, PlayerName.",
  ui_story_5031_50310702_77_dialog_content = "¡Lo hicimos!",
  ui_story_5031_50310702_78_dialog_content = "¡Estamos en la siguiente ronda!",
  ui_story_5031_50310702_79_dialog_content = "Pero muchos otros competidores fuertes también lo lograron.",
  ui_story_5031_50310702_80_dialog_content = "Esa persona haciendo una escena... es ese Oficial Gronru?",
  ui_story_5031_50310702_81_dialog_content = "¡Oye! ¡Date prisa, Ciel!",
  ui_story_5031_50310702_82_dialog_content = "¡Vamos, usa tu definitiva!",
  ui_story_5031_50310702_83_dialog_content = "¡O vamos a ser eliminados!",
  ui_story_5031_50310702_84_dialog_content = "C-Ce, pero <color=#FFB400>Estigio</color> es todavía...",
  ui_story_5031_50310702_85_dialog_content = "Eh... Está bien. \"Actualización del estado del mecanismo de pierna: Mark II\".",
  ui_story_5031_50310702_86_dialog_content = "\"Aumenta la liberación de energía en un 50%\".",
  ui_story_5031_50310702_87_dialog_content = "¡Vamos!",
  ui_story_5031_50310702_88_dialog_content = "¡Guau! ¡Ciel se fue directamente!",
  ui_story_5031_50310702_89_dialog_content = "¡Ahhh! ¡Fuera del camino, todos! ¡Perdí el control de Styx!",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50310702_91_dialog_content = "V-Muy impresionante. Incluso dejó un agujero en el edificio.",
  ui_story_5031_50310702_92_dialog_content = "Y una marca bastante larga en la cubierta.",
  ui_story_5031_50310702_93_dialog_content = "Vaya, eso es simplemente increíble. ¿A dónde fue?",
  ui_story_5031_50310702_94_dialog_content = "¿Estás bien, Ciel?",
  ui_story_5031_50310702_95_dialog_content = "¡Ay, ay! No creo que esté herido.",
  ui_story_5031_50310702_96_dialog_content = "Puede que no estés herido, pero no puedo decir lo mismo de nuestra amada Esmeralda.",
  ui_story_5031_50310702_97_dialog_content = "Vaya. ¡Lo siento mucho!",
  ui_story_5031_50310702_98_dialog_content = "¡No fue mi intención! No he terminado de depurar Styx, no, es mi culpa por ser débil...",
  ui_story_5031_50310702_99_dialog_content = "Esta bien. No me interesa la culpa. Pensemos en qué hacer a continuación.",
  ui_story_5031_50310702_100_dialog_content = "Idealmente, contrataríamos a alguien para repararlo.",
  ui_story_5031_50310702_101_dialog_content = "Pero no creo que Ciel sea un hijo del dinero.",
  ui_story_5031_50310702_102_dialog_content = "Estás bien. Lamento eso...",
  ui_story_5031_50310702_103_dialog_content = "Deja de disculparte. Vamos. ¡Esta bien!",
  ui_story_5031_50310702_104_dialog_content = "¡Eso me recuerda! Puedes desafiar nuestra próxima ronda: ¡un concurso de surf!",
  ui_story_5031_50310702_105_dialog_content = "Laird Elvis patrocina la siguiente ronda con un premio extra para el ganador.",
  ui_story_5031_50310702_106_dialog_content = "¿¡R-En serio!?",
  ui_story_5031_50310702_107_dialog_content = "¡Por cierto! Y estoy bastante seguro... ¡son cinco millones de Nightium!",
  ui_story_5031_50310702_108_dialog_content = "Eso es suficiente para cubrir los costos de reparación.",
  ui_story_5031_50310702_109_dialog_content = "¡Maravilloso! ¡Estoy dentro!",
  ui_story_5031_50310702_110_dialog_content = "Oye, no nos adelantemos.",
  ui_story_5031_50310702_111_dialog_content = "Las hermanas Merylt y yo también nos uniremos.",
  ui_story_5031_50310702_112_dialog_content = "¡Y tengo la intención de ganar, Ciel!",
  ui_story_5031_50310702_113_dialog_content = "Si pierdes... oh, ¿cuál es su nombre otra vez? Estigia, ¿verdad?",
  ui_story_5031_50310702_114_dialog_content = "Será mío.",
  ui_story_5031_50310702_115_dialog_content = "... No puedo.",
  ui_story_5031_50310702_116_dialog_content = "Oye. Solo quiero tomarlo prestado para estudiarlo. No te lo voy a robar ni nada por el estilo.",
  ui_story_5031_50310702_117_dialog_content = "Lo devolveré después.",
  ui_story_5031_50310702_118_dialog_content = "Lo siento.",
  ui_story_5031_50310702_119_dialog_content = "La cosa es... que simplemente no puedo hacer eso...",
  ui_story_5031_50310801_1_dialog_content = "¡Hola a todos! Espero que la brisa fresca del verano y la fruta gratis los hayan emocionado a todos.",
  ui_story_5031_50310801_2_dialog_content = "¡Te ves bien descansado y listo para entrar en la siguiente ronda de competencia!",
  ui_story_5031_50310801_3_dialog_content = "¡Sí!",
  ui_story_5031_50310801_4_dialog_content = "¡Oh, te ves muy emocionado! Y parece que no puedes esperar más.",
  ui_story_5031_50310801_5_dialog_content = "Así que esta vez podemos limpiarnos un poco del sudor que hemos acumulado.",
  ui_story_5031_50310801_6_dialog_content = "¡Es hora de darse un chapuzón en el gran baño del mar bajo este sol abrasador!",
  ui_story_5031_50310801_7_dialog_content = "Es el momento que todos han estado esperando: un <size=45>concurso de surf</size>!",
  ui_story_5031_50310801_8_dialog_content = "¡¡Guau!!",
  ui_story_5031_50310801_9_dialog_content = "Y como es tradición tener competencias de surf en Harbor City, el equipo ganador...",
  ui_story_5031_50310801_10_dialog_content = "... También recibirán una recompensa especial de Laird Elvis de <color=#FFB400>cinco millones de Nightium</color>!",
  ui_story_5031_50310801_11_dialog_content = "F-Cinco millones?",
  ui_story_5031_50310801_12_dialog_content = "¿¡Cinco millones!?",
  ui_story_5031_50310801_13_dialog_content = "PlayerName, Vice! ¡No seas codicioso!",
  ui_story_5031_50310801_14_dialog_content = "¡No olvides por qué estamos aquí!",
  ui_story_5031_50310801_15_dialog_content = "Sí... Pero tal vez podamos ganar algo de dinero mientras ayudamos a Fia a conseguir esa maravillosa bestia.",
  ui_story_5031_50310801_16_dialog_content = "Harbor City es bastante rica, ¿eh?",
  ui_story_5031_50310801_17_dialog_content = "De hecho, es. Han estado en auge en los últimos años.",
  ui_story_5031_50310801_18_dialog_content = "No todos los días ves a un laird lanzar un gran premio a su gente.",
  ui_story_5031_50310801_19_dialog_content = "No es de extrañar que Harbour City vaya bien si eso es lo que Laird Elvis está tramando.",
  ui_story_5031_50310801_20_dialog_content = "Carleen realmente ha estado haciendo su mejor esfuerzo, ¿no es así?",
  ui_story_5031_50310801_21_dialog_content = "¿Supongo que has estado pensando en todos los problemas económicos durante estas vacaciones?",
  ui_story_5031_50310801_22_dialog_content = "Oh, lo siento si mato el estado de ánimo para ustedes...",
  ui_story_5031_50310801_23_dialog_content = "No no. Eso no es lo que quiero decir.",
  ui_story_5031_50310801_24_dialog_content = "Solo me preocupa un poco que te estés cansando.",
  ui_story_5031_50310801_25_dialog_content = "Sí, Carleen! No vale la pena el estrés. ¡Vamos a relajarnos!",
  ui_story_5031_50310801_26_dialog_content = "Mira lo bien que se lo está pasando Fia con esa piña.",
  ui_story_5031_50310801_27_dialog_content = "Estoy seguro de que está bien y verdaderamente distraída de su gran plan.",
  ui_story_5031_50310801_28_dialog_content = "¡mmm! ¡Es realmente dulce!",
  ui_story_5031_50310801_29_dialog_content = "Es genial, ya sabes, ¡tienen frutas gratis!",
  ui_story_5031_50310801_30_dialog_content = "Sí. Ciertamente así es.",
  ui_story_5031_50310801_31_dialog_content = "Tengo mucho que aprender de Fia.",
  ui_story_5031_50310801_32_dialog_content = "<size=33>Y no solo ella, sino también Vice y PlayerName, también...</size>",
  ui_story_5031_50310801_33_dialog_content = "Tú y yo sabemos que los Eclipsites no pueden ser eliminados.",
  ui_story_5031_50310801_34_dialog_content = "Un gobernante debe ejercer más moderación, no precipitarse en el centro de la acción para detenerlos usted mismo.",
  ui_story_5031_50310801_35_dialog_content = "No eres el único que sufrirá en ese intercambio, ¿y los que te siguen?",
  ui_story_5031_50310801_36_dialog_content = "...",
  ui_story_5031_50310801_37_dialog_content = "Quiero que realmente consideres por qué te he permitido etiquetarte junto con PlayerName y los demás.",
  ui_story_5031_50310801_38_dialog_content = "Yo...",
  ui_story_5031_50310801_39_dialog_content = "Necesita más tiempo para crecer en su papel noble y privilegiado en la vida.",
  ui_story_5031_50310801_40_dialog_content = "... Si padre.",
  ui_story_5031_50310801_41_dialog_content = "Carleen? Carleen!",
  ui_story_5031_50310801_42_dialog_content = "¿Eh? ¿Disculpa, que dijiste?",
  ui_story_5031_50310801_43_dialog_content = "Solo estaba diciendo que tal vez deberíamos ir a cambiarnos. Seguro que pasaremos mucho tiempo en el agua.",
  ui_story_5031_50310801_44_dialog_content = "¡No puedes manchar tu ropa nueva!",
  ui_story_5031_50310801_45_dialog_content = "ah Muy bien.",
  ui_story_5031_50310801_46_dialog_content = "Espera, ¿en qué debo cambiarme?",
  ui_story_5031_50310801_47_dialog_content = "¡je! Eso sería naturalmente—",
  ui_story_5031_50310801_48_dialog_content = "¡Traje de baño!",
  ui_story_5031_50310801_49_dialog_content = "¡Guau! Te ves genial, Carleen y Vice!",
  ui_story_5031_50310801_50_dialog_content = "Gracias, Fía.",
  ui_story_5031_50310801_51_dialog_content = "¿Cómo es que también trajiste mi traje de baño?",
  ui_story_5031_50310801_52_dialog_content = "¿Quién no lleva un bañador a la playa?",
  ui_story_5031_50310801_53_dialog_content = "Estos son nuestros primeros deportes acuáticos, así que no pensé en hacerlo hasta ahora.",
  ui_story_5031_50310801_54_dialog_content = "¡Ojalá yo también tuviera un traje de baño!",
  ui_story_5031_50310801_55_dialog_content = "¡Después nos dirigiremos directamente a un outlet de moda de Harbor City para encargar uno para ti!",
  ui_story_5031_50310801_56_dialog_content = "¿En serio? ¡Gracias, Vice!",
  ui_story_5031_50310801_57_dialog_content = "Guau. Es la primera vez que me piden un traje de baño personalizado. ¡Impresionante!",
  ui_story_5031_50310801_58_dialog_content = "También noté algunos utensilios realmente buenos antes. ¡Tal vez podamos comprar esos también!",
  ui_story_5031_50310801_59_dialog_content = "¡Grandioso!",
  ui_story_5031_50310801_60_dialog_content = "Además...",
  ui_story_5031_50310801_61_dialog_content = "Ejem, yo...",
  ui_story_5031_50310801_62_dialog_content = "¿Eh? ¿Qué es, PlayerName?",
  ui_story_5031_50310801_63_dialog_content = "Perdón por interrumpirte en medio de una gran charla...",
  ui_story_5031_50310801_64_dialog_content = "Pero... no puedo surfear.",
  ui_story_5031_50310801_65_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5031_50310801_66_dialog_content = "¿Eso significa que no recibiré mi traje de baño?",
  ui_story_5031_50310801_67_dialog_content = "¿Eso es lo que te preocupa? ¿Has olvidado nuestro verdadero propósito aquí, tu maravillosa bestia?",
  ui_story_5031_50310801_68_dialog_content = "Mi traje de baño así como el Cloudwhale... Boo-hoo...",
  ui_story_5031_50310801_69_dialog_content = "... ¡Todos están fuera de alcance! ¡Waaaah!",
  ui_story_5031_50310801_70_dialog_content = "Lo siento mucho Fía. ¡No llores!",
  ui_story_5031_50310801_71_dialog_content = "Pensaré en una manera, incluso si no obtenemos el primer lugar...",
  ui_story_5031_50310801_72_dialog_content = "¡Estoy seguro de que podemos encontrar suficiente dinero para algunos trajes de baño!",
  ui_story_5031_50310801_73_dialog_content = "... ¿En serio?",
  ui_story_5031_50310801_74_dialog_content = "¡Sí! Carleen y Vice puede responder por mí, ¿no?",
  ui_story_5031_50310801_75_dialog_content = "¡E-Eso sería genial!",
  ui_story_5031_50310801_76_dialog_content = "Lo siento, no debería haber empezado a fantasear con ganar el premio antes de preguntar claramente sobre la situación.",
  ui_story_5031_50310801_77_dialog_content = "No es tu culpa, Vice. Estoy tan descoordinado. ¡Ni siquiera puedo surfear!",
  ui_story_5031_50310801_78_dialog_content = "Oh, no, lo malinterpretaste, PlayerName.",
  ui_story_5031_50310801_79_dialog_content = "No todo el mundo está hecho para surfear.",
  ui_story_5031_50310801_80_dialog_content = "Simplemente lo había estudiado antes.",
  ui_story_5031_50310801_X80_dialog_content = "Yo también. Cuando visité Harbor City en mi infancia, solo vi la competencia de surf ese año.",
  ui_story_5031_50310801_X81_dialog_content = "Por eso me interesé y me encontré un maestro.",
  ui_story_5031_50310801_81_dialog_content = "¿Vaya? Entonces, ¿dónde aprendiste a surfear, Fia?",
  ui_story_5031_50310801_82_dialog_content = "¿Eh? Nunca aprendí a surfear.",
  ui_story_5031_50310801_83_dialog_content = "¡¿Qué?!",
  ui_story_5031_50310801_84_dialog_content = "¿Entonces por qué estabas llorando? ¡Si nunca lo has hecho antes y no sabes cómo!",
  ui_story_5031_50310801_85_dialog_content = "¡Cómo pudiste gritarme así, Caelestite! No encontrarás una novia con una actitud como esa.",
  ui_story_5031_50310801_86_dialog_content = "¿Una g-novia?",
  ui_story_5031_50310801_87_dialog_content = "¿De qué estás hablando? ¡Oye, vuelve!",
  ui_story_5031_50310801_88_dialog_content = "¡Guau! ¡Todos se dirigen al agua! ¡Deberíamos ir ahora!",
  ui_story_5031_50310801_89_dialog_content = "... ¡Tu eres rápido!",
  ui_story_5031_50310801_90_dialog_content = "...",
  ui_story_5031_50310801_91_dialog_content = "...",
  ui_story_5031_50310801_92_dialog_content = "(¿Cómo se volvió tan incómodo de repente?)",
  ui_story_5031_50310801_93_dialog_content = "Ejem, entonces, vamos a ir allí ahora también, ¿verdad?",
  ui_story_5031_50310801_94_dialog_content = "Sí. Creo que sí.",
  ui_story_5031_50310801_95_dialog_content = "Bueno. Vamos.",
  ui_story_5031_50310801_96_dialog_content = "(¿Qué les pasa?)",
  ui_story_5031_50310801_97_dialog_content = "Derecha. Coloque ambas manos paralelas alrededor de la parte inferior del pecho y junte los pies.",
  ui_story_5031_50310801_98_dialog_content = "Luego usa la fuerza de tus brazos para sostener tu cuerpo.",
  ui_story_5031_50310801_99_dialog_content = "¿Me gusta esto?",
  ui_story_5031_50310801_100_dialog_content = "Así es. Mira al frente. Lo estás haciendo bien.",
  ui_story_5031_50310801_101_dialog_content = "Cuando sube la ola, esa es tu señal para ponerte de pie. Mantenga los pies del mismo ancho que los hombros y estire la espalda.",
  ui_story_5031_50310801_102_dialog_content = "¡Aquí hay una ola!",
  ui_story_5031_50310801_103_dialog_content = "¿Sientes que tu tabla de surf gana velocidad bajo la ola? ¡Está sucediendo!",
  ui_story_5031_50310801_104_dialog_content = "¡E-está bien!",
  ui_story_5031_50310801_105_dialog_content = "De pie... ¡Guau!",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5031_50310801_107_dialog_content = "¡PlayerName!",
  ui_story_5031_50310801_108_dialog_content = "*Tosiendo*",
  ui_story_5031_50310801_109_dialog_content = "Estoy bien. Que todavía estoy vivo...",
  ui_story_5031_50310801_110_dialog_content = "Vamos, PlayerName. No seas tan débil.",
  ui_story_5031_50310801_111_dialog_content = "Incluso yo sé cómo pararme en una tabla de surf.",
  ui_story_5031_50310801_112_dialog_content = "¡No estás parado en absoluto! ¡Estás claramente agachado!",
  ui_story_5031_50310801_113_dialog_content = "¡Todavía soy mejor que tú!",
  ui_story_5031_50310801_114_dialog_content = "¡Y con la idea de Carleen, todo lo que necesito aprender es a agacharme!",
  ui_story_5031_50310801_115_dialog_content = "¡No olvides que soy el único que puede pedirle a los peces que vengan a empujar mi tabla de surf!",
  ui_story_5031_50310801_116_dialog_content = "Tienes que ser...",
  ui_story_5031_50310801_117_dialog_content = "¡El tiempo ha llegado!",
  ui_story_5031_50310801_118_dialog_content = "¡Guau! Genial ver a tanta gente practicando en las olas. ¡Buen trabajo!",
  ui_story_5031_50310801_119_dialog_content = "¡Parece que la promesa de 5 millones de Nightium es extremadamente atractiva!",
  ui_story_5031_50310801_120_dialog_content = "¡Jaja!",
  ui_story_5031_50310801_121_dialog_content = "¡je! ¡Es una broma!",
  ui_story_5031_50310801_122_dialog_content = "¡Así que empecemos con las reglas!",
  ui_story_5031_50310801_123_dialog_content = "Como antes, cuatro personas por equipo. Te turnarás para enfrentarte a las olas.",
  ui_story_5031_50310801_124_dialog_content = "Si no tiene cuatro personas en su equipo, puede ingresar con menos.",
  ui_story_5031_50310801_125_dialog_content = "¡Puede ingresar con solo dos personas, porque solo se calificarán los dos mejores jugadores de su equipo!",
  ui_story_5031_50310801_126_dialog_content = "Como antes, obtienes puntos por eliminar las ilusiones de Eclipsite. Pero no vas a ser eliminado al caer al agua.",
  ui_story_5031_50310801_127_dialog_content = "Aparte de Eclipsites, la mitad de tus puntos vendrán de tu técnica de navegación.",
  ui_story_5031_50310801_128_dialog_content = "Así que sugiero organizar el orden en el que vas a ir. ¡Será muy importante!",
  ui_story_5031_50310801_129_dialog_content = "¡Oh, no! Acabo de revelar un secreto importante para ganar. ¡Supongo que hará que el concurso sea mucho más intenso!",
  ui_story_5031_50310801_130_dialog_content = "¡Jajajajaja!",
  ui_story_5031_50310801_131_dialog_content = "De todos modos, ¡diviértanse todos!",
  ui_story_5031_50310801_132_dialog_content = "Estamos a punto de comenzar la primera ronda, en un momento.",
  ui_story_5031_50310801_133_dialog_content = "¿Todos los equipos se alinearían? ¿Y podemos tener el primer jugador de cada equipo por el lugar de inicio?",
  ui_story_5031_50310801_134_dialog_content = "Quiero contarles a todos un pequeño secreto...",
  ui_story_5031_50310801_135_dialog_content = "Nuestro primer surfista de hoy va a ser... ¡yo!",
  ui_story_5031_50310801_136_dialog_content = "¡Sí!",
  ui_story_5031_50310801_137_dialog_content = "¡Seguro que puedes surfear, Rainbow!",
  ui_story_5031_50310801_138_dialog_content = "Rainbow realmente está ganando a la multitud.",
  ui_story_5031_50310801_139_dialog_content = "Ella debe ser increíble en esto. Tiene mucha confianza.",
  ui_story_5031_50310801_140_dialog_content = "Oh bien. De todos modos, las reglas dicen que solo contarán los dos mejores anotadores, por lo que podría ser bueno para nosotros.",
  ui_story_5031_50310801_141_dialog_content = "Es por eso que el orden en el que entras es realmente importante.",
  ui_story_5031_50310801_142_dialog_content = "Entonces, si tienen a Rainbow como titular en su equipo, entonces deberíamos...",
  ui_story_5031_50310801_143_dialog_content = "¡Hmph! ¿No es obvio que debo ir primero? ¡Soy el mejor!",
  ui_story_5031_50310801_144_dialog_content = "... ¿Tú? ¿Lo mejor?",
  ui_story_5031_50310801_145_dialog_content = "¿Qué estás implicando?",
  ui_story_5031_50310801_146_dialog_content = "¡No olvides que soy el único que logró seguir las instrucciones de Carleen en ese momento!",
  ui_story_5031_50310801_147_dialog_content = "¡Es una cosa segura! Ganaré fácilmente.",
  ui_story_5031_50310801_148_dialog_content = "¡Puedes quedarte aquí y esperar mi regreso triunfal, PlayerName!",
  ui_story_5031_50310801_149_dialog_content = "... ¿De verdad va a ser tan fácil?",
  ui_story_5031_50310801_150_dialog_content = "Algo en su arrogancia me está preocupando aún más.",
  ui_story_5031_50310801_151_dialog_content = "Ejem, tendré que ser el maestro de ceremonias en este ya que Rainbow se ha involucrado.",
  ui_story_5031_50310801_152_dialog_content = "Uh... Debo decir que todos ustedes parecen bastante pequeños desde este punto de vista, balanceándose arriba y abajo sobre las olas...",
  ui_story_5031_50310801_153_dialog_content = "Por pequeño que seas, has dominado las leyes naturales del movimiento, lo que te permite surfear.",
  ui_story_5031_50310801_154_dialog_content = "Es nada menos que una forma de arte de supremo ingenio y sentido estético...",
  ui_story_5031_50310801_155_dialog_content = "¡Adiós a todos! Cabalga los ritmos de estas olas y conquista...",
  ui_story_5031_50310801_156_dialog_content = "... ¡Suficiente! ¡Empecemos! ¡Comienzo!",
  ui_story_5031_50310801_157_dialog_content = "¡Estábamos esperando!",
  ui_story_5031_50310801_158_dialog_content = "Tsk. Simplemente no puedo entender a los tontos mediocres.",
  ui_story_5031_50310801_159_dialog_content = "Ya que están todos tan impacientes, entonces comencemos. ¡Vamos!",
  ui_story_5031_50310801_160_dialog_content = "...",
  ui_story_5031_50310801_161_dialog_content = "¿Eh? ¿Eso es todo?",
  ui_story_5031_50310801_162_dialog_content = "¡Queremos otro maestro de ceremonias!",
  ui_story_5031_50310801_163_dialog_content = "¡Ja ja! Pobre Jeno.",
  ui_story_5031_50310801_164_dialog_content = "En ese caso, ¡mejor me voy!",
  ui_story_5031_50310801_165_dialog_content = "¡Vamos, Ciel! ¡Ha comenzado! ¡Rápido!",
  ui_story_5031_50310801_166_dialog_content = "¿Ya empezó? ¿No había algún tipo de señal?",
  ui_story_5031_50310801_167_dialog_content = "Oh, querido. \"Actualización del estado del mecanismo de la pierna: ¡Modo de rociado\"!",
  ui_story_5031_50310801_168_dialog_content = "¿Están navegando en un mech?",
  ui_story_5031_50310801_169_dialog_content = "¡Las olas simplemente arrastraron a esos concursantes al mar!",
  ui_story_5031_50310801_170_dialog_content = "¿Qué se supone que debemos hacer al respecto?",
  ui_story_5031_50310801_171_dialog_content = "Esta bien. Fia está bastante lejos ahora... y parece estar estable.",
  ui_story_5031_50310801_172_dialog_content = "¡Oooh! ¡¡Adelante, Arcoiris!!",
  ui_story_5031_50310801_173_dialog_content = "¡Guau! ¡Se vuelve como una profesional!",
  ui_story_5031_50310801_174_dialog_content = "Esa chica en el robot tampoco es tan mala. ¡Ella es rápida!",
  ui_story_5031_50310801_175_dialog_content = "Pero no se ve tan bien en una tabla como Rainbow.",
  ui_story_5031_50310801_176_dialog_content = "Hmph. El concurso está lejos de ser tan simple como podría pensar.",
  ui_story_5031_50310801_177_dialog_content = "¡Rugido! ¡Criaturas malditas de las profundidades!",
  ui_story_5031_50310801_178_dialog_content = "¡Graaaah!",
  ui_story_5031_50310801_179_dialog_content = "¡Ellos estan aqui!",
  ui_story_5031_50310801_180_dialog_content = "¡je! ¡Rainbow está a punto de transformarse de nuevo!",
  ui_story_5031_50310801_181_dialog_content = "Oh. ¡Cuidado, arcoiris!",
  ui_story_5031_50310801_182_dialog_content = "¿Eh? ¡Hay eclipses saliendo de las olas!",
  ui_story_5031_50310801_183_dialog_content = "Eso va a ser un poco difícil...",
  ui_story_5031_50310801_184_dialog_content = "¿R-Rainbow?",
  ui_story_5031_50310801_185_dialog_content = "¡Sí!",
  ui_story_5031_50310801_186_dialog_content = "¡Ya os aguanté bastante, miserables Eclipsitas!",
  ui_story_5031_50310801_187_dialog_content = "<size=45>¡Morir!</size>",
  ui_story_5031_50310801_188_dialog_content = "No pareces muy feliz. ¿Estás pensando en esa chica Ranka?",
  ui_story_5031_50310802_X1_dialog_content = "No pareces muy feliz. ¿Estás pensando en esa chica Ranka?",
  ui_story_5031_50310802_1_dialog_content = "Oh, eh, sí...",
  ui_story_5031_50310802_2_dialog_content = "Déjame traerte algo de fruta. Necesitas mantenerte hidratado.",
  ui_story_5031_50310802_3_dialog_content = "Gracias, Jeno.",
  ui_story_5031_50310802_4_dialog_content = "¿Ese medicamento que acabas de darle es la \"solución\" de la que estabas hablando?",
  ui_story_5031_50310802_5_dialog_content = "De nada. Es algo que inventé después de estudiar los textos antiguos. Es solo para el alivio temporal del dolor.",
  ui_story_5031_50310802_6_dialog_content = "¿Y aún así lo inventaste?",
  ui_story_5031_50310802_7_dialog_content = "Érase una vez, usted quería ser chef. ¿Pero te hiciste farmacéutico?",
  ui_story_5031_50310802_8_dialog_content = "¡je! Harbor City no necesita más chefs, pero necesitamos a alguien que entienda muy bien el síndrome de Modali.",
  ui_story_5031_50310802_9_dialog_content = "Entonces, en otras palabras, ¿sacrificaste tu sueño para hacer algo grandioso con tu vida?",
  ui_story_5031_50310802_10_dialog_content = "Nunca quise llegar a ser grande. Simplemente no quiero quedarme de brazos cruzados mientras otros sufren.",
  ui_story_5031_50310802_11_dialog_content = "Y no soy mucho de un farmacéutico. Acabo de copiar lo que leí en los pergaminos antiguos. Fue fácil.",
  ui_story_5031_50310802_12_dialog_content = "Me sentiré libre de perseguir mis sueños una vez que descubra el síndrome de Modali.",
  ui_story_5031_50310802_13_dialog_content = "¿Y qué harías entonces?",
  ui_story_5031_50310802_14_dialog_content = "Podría intentar abrir una cadena de salones de arte de clase alta con restaurantes adjuntos.",
  ui_story_5031_50310802_15_dialog_content = "¿Todavía recuerdas esa promesa de hace tantos años?",
  ui_story_5031_50310802_16_dialog_content = "Ha pasado tanto tiempo... Pensé que lo habías olvidado.",
  ui_story_5031_50310802_17_dialog_content = "Tengo una excelente memoria. Incluso recuerdo pequeñas cosas, como ese retrato que estabas destinado a pintar para mí.",
  ui_story_5031_50310802_18_dialog_content = "He dejado un espacio vacío en la galería de arte de Harbor City.",
  ui_story_5031_50310802_19_dialog_content = "...",
  ui_story_5031_50310802_20_dialog_content = "Entonces, ¿hay algo que pueda hacer para ayudar?",
  ui_story_5031_50310802_21_dialog_content = "¿Qué quieres decir?",
  ui_story_5031_50310802_22_dialog_content = "¿Hay algo que pueda hacer para ayudarlo con este \"Síndrome de Modali\"?",
  ui_story_5031_50310802_23_dialog_content = "...",
  ui_story_5031_50310802_24_dialog_content = "En realidad...",
  ui_story_5031_50310802_25_dialog_content = "¡Guau! ¡señorita Rainbow es asombroso!",
  ui_story_5031_50310802_26_dialog_content = "¡Una mezcla perfecta de poder y belleza!",
  ui_story_5031_50310802_27_dialog_content = "... ¿Qué estabas diciendo?",
  ui_story_5031_50310802_28_dialog_content = "Esta bien. Primero disfrutemos del evento.",
  ui_story_5031_50310802_29_dialog_content = "Debo tratar de ser un buen juez. No querría defraudar a los concursantes.",
  ui_story_5031_50310802_30_dialog_content = "Rainbow es realmente fuerte y aterrador también...",
  ui_story_5031_50310802_31_dialog_content = "T-Tienes razón.",
  ui_story_5031_50310802_32_dialog_content = "¡No digas eso de Rainbow, brote de soja!",
  ui_story_5031_50310802_33_dialog_content = "Sí. ¡Incluso si Merylt se preocupa por ti!",
  ui_story_5031_50310802_34_dialog_content = "Lo siento mucho. ¡Lo dije en el buen sentido!",
  ui_story_5031_50310802_35_dialog_content = "Estoy tan asombrado por su intrépida demostración de espíritu...",
  ui_story_5031_50310802_36_dialog_content = "No vayas a causar problemas, Subli.",
  ui_story_5031_50310802_37_dialog_content = "Rainbow realmente, realmente odia los eclipses. Es por eso que ella está haciendo eso.",
  ui_story_5031_50310802_38_dialog_content = "¿Odia los eclipses?",
  ui_story_5031_50310802_39_dialog_content = "Sí...",
  ui_story_5031_50310802_40_dialog_content = "El pueblo de Rainbow fue destruido por los Eclipsites.",
  ui_story_5031_50310802_41_dialog_content = "Así fue como perdió a sus amigos y familiares.",
  ui_story_5031_50310802_42_dialog_content = "Es por eso que Rainbow se enoja cada vez que ve eclipses, incluso ilusiones.",
  ui_story_5031_50310802_43_dialog_content = "Es una persona muy dulce y gentil. Es solo con Eclipsites.",
  ui_story_5031_50310802_44_dialog_content = "Sí. ¡Me encanta el arcoíris!",
  ui_story_5031_50310802_45_dialog_content = "Yo también. Me gusta mucho más que nuestro maestro de ceremonias, siempre se ve feroz.",
  ui_story_5031_50310802_46_dialog_content = "Creo... que nuestro maestro de ceremonias es simpático...",
  ui_story_5031_50310802_47_dialog_content = "¡Solo tú dirías algo así!",
  ui_story_5031_50310802_48_dialog_content = "Asi que es por eso...",
  ui_story_5031_50310802_49_dialog_content = "Mirando la actitud alegre de Rainbow, es difícil creer que tenga un pasado tan trágico.",
  ui_story_5031_50310802_50_dialog_content = "A veces, las chicas más felices y dulces son las que tienen un pasado más doloroso y trágico.",
  ui_story_5031_50310802_51_dialog_content = "La respeto.",
  ui_story_5031_50310802_52_dialog_content = "Derecha. No puedo evitar sentir que tengo suerte de no ser el primero en salir...",
  ui_story_5031_50310802_53_dialog_content = "Oye... ¿Qué pasa con Fia?",
  ui_story_5031_50310802_54_dialog_content = "¡Deja de venir a mi tabla de surf de todas partes a la vez!",
  ui_story_5031_50310802_55_dialog_content = "¡Elige una dirección!",
  ui_story_5031_50310802_56_dialog_content = "¡Ay! ¡Camino equivocado! ¡No ahí! ¡Guau!",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5031_50310802_58_dialog_content = "¡Ja ja! ¿Cómo logró esa chica un giro de 360 grados?",
  ui_story_5031_50310802_59_dialog_content = "Ahora se está dando un chapuzón. No va a ganar muchos puntos por estilo.",
  ui_story_5031_50310802_60_dialog_content = "*Tosiendo*",
  ui_story_5031_50310802_61_dialog_content = "¡Pescado estúpido!",
  ui_story_5031_50310802_62_dialog_content = "PlayerName se va a reír de mí seguro, boo-hoo...",
  ui_story_5031_50310802_63_dialog_content = "Fia debe estar preocupada de que me ría de ella ahora.",
  ui_story_5031_50310802_64_dialog_content = "Pero... ¡jaja!",
  ui_story_5031_50310802_65_dialog_content = "Debo decir que es muy divertido, jajaja!",
  ui_story_5031_50310802_66_dialog_content = "No te rías tan fuerte, PlayerName.",
  ui_story_5031_50310802_67_dialog_content = "Que es mi culpa. No esperaba que Fia tuviera problemas de coordinación con los peces.",
  ui_story_5031_50310802_68_dialog_content = "Era un poco irreal esperar que pudiera ganar con la comunicación de los peces.",
  ui_story_5031_50310802_69_dialog_content = "No no. ¡Fia dijo que sería pan comido!",
  ui_story_5031_50310802_70_dialog_content = "No puedes seguir culpándote de todo, Carleen. Es sólo un juego de todos modos. ¿A quien le importa?",
  ui_story_5031_50310802_71_dialog_content = "... Sí.",
  ui_story_5031_50310802_72_dialog_content = "Déjame darte un comentario: apuesto a que puedes saber lo que está pasando si todavía tuvieras tus preciosos ojos.",
  ui_story_5031_50310802_73_dialog_content = "El surfista más destacado en el concurso en este momento es nuestro propio Rainbow of the Circus, así como Ciel of Illumina.",
  ui_story_5031_50310802_74_dialog_content = "Los dos están a la altura de los Eclipsites destruidos y muy por delante en lo que respecta al estilo.",
  ui_story_5031_50310802_75_dialog_content = "Pero dada la respuesta de nuestra audiencia, Rainbow parece tener una técnica ligeramente superior.",
  ui_story_5031_50310802_76_dialog_content = "Así que les deseo al resto de ustedes, dieciocho concursantes, completamente anónimos como son, la mejor de las suertes.",
  ui_story_5031_50310802_77_dialog_content = "... Y una lucha valiente contra las olas y vicisitudes de la vida.",
  ui_story_5031_50310802_78_dialog_content = "...",
  ui_story_5031_50310802_79_dialog_content = "¡Espera, Jeno!",
  ui_story_5031_50310802_80_dialog_content = "¡Hasta el mar contigo!",
  ui_story_5031_50310802_81_dialog_content = "¡Graaaah!",
  ui_story_5031_50310802_82_dialog_content = "¡Uf, incluso si eres una ilusión, no puedo evitarlo!",
  ui_story_5031_50310802_83_dialog_content = "¡Me siento mucho mejor después de destruirlos a todos!",
  ui_story_5031_50310802_84_dialog_content = "Eres tan... poderoso...",
  ui_story_5031_50310802_85_dialog_content = "¿Eh? ¡De vuelta a ti, niña!",
  ui_story_5031_50310802_86_dialog_content = "¡Eres un buen partido para mí, que crecí junto al mar!",
  ui_story_5031_50310802_87_dialog_content = "En realidad, me acabo de ganar las marcas matando Eclipsites.",
  ui_story_5031_50310802_88_dialog_content = "No obtuve mucho en términos de mis habilidades de navegación.",
  ui_story_5031_50310802_89_dialog_content = "Me aproveché de una laguna en las reglas...",
  ui_story_5031_50310802_90_dialog_content = "Eres raro, Ciel.",
  ui_story_5031_50310802_91_dialog_content = "¿Q-Raro?",
  ui_story_5031_50310802_92_dialog_content = "Sí. Te estoy dando elogios, pero no solo no los aceptas, también te ves molesto.",
  ui_story_5031_50310802_93_dialog_content = "¿Qué tiene de malo anotar matando Eclipsites? ¿Cómo es eso de abusar de las reglas?",
  ui_story_5031_50310802_94_dialog_content = "...",
  ui_story_5031_50310802_95_dialog_content = "Ciel, eres bueno. Deberías tener más confianza en ti mismo.",
  ui_story_5031_50310802_96_dialog_content = "Seguir dudando de ti mismo es una forma segura de estropear las cosas.",
  ui_story_5031_50310802_97_dialog_content = "Yo...",
  ui_story_5031_50310802_98_dialog_content = "¡Graagh!",
  ui_story_5031_50310802_99_dialog_content = "¿¡Más eclipses!? ¡No te vas a escapar!",
  ui_story_5031_50310802_100_dialog_content = "¿Estoy bien?",
  ui_story_5031_50310802_101_dialog_content = "Je... jeje.",
  ui_story_5031_50310802_102_dialog_content = "Bueno, ¡no hay forma de que vaya a decepcionar a Rainbow, entonces!",
  ui_story_5031_50310802_103_dialog_content = "\"Actualización de estado de Arm Mech—Tipo II\"!",
  ui_story_5031_50310802_104_dialog_content = "\"¡Aumenta la liberación de energía en un 60%\"!",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>retumba—</color>",
  ui_story_5031_50310802_106_dialog_content = "¿¡C-Ciel!?",
  ui_story_5031_50310802_107_dialog_content = "¿Aumentó de nuevo la producción de energía?",
  ui_story_5031_50310802_108_dialog_content = "Pero Styx es...",
  ui_story_5031_50310802_109_dialog_content = "¡Oye! ¡Esa chica mecha desató una energía tan poderosa en el mar!",
  ui_story_5031_50310802_110_dialog_content = "¡El barco se mece de un lado a otro! vamos a hundirnos...",
  ui_story_5031_50310802_111_dialog_content = "¡Ella voló hacia el cielo! ¿Está tratando de ganar más puntos con un salto mortal?",
  ui_story_5031_50310802_112_dialog_content = "No, espera... Eso es...",
  ui_story_5031_50310802_113_dialog_content = "¡Eclipsitos! ¡Ella noqueó a los Eclipsites del mar!",
  ui_story_5031_50310802_114_dialog_content = "Ah, eso es...",
  ui_story_5031_50310802_115_dialog_content = "¡Qué poder tan increíble!",
  ui_story_5031_50310802_116_dialog_content = "Como no soy tan hábil, tendré que confiar en el 50% de los puntos restantes.",
  ui_story_5031_50310802_117_dialog_content = "¡Styx, ataque de barrido!",
  ui_story_5031_50310802_118_dialog_content = "Pero el mecha tiene un gran rendimiento y puede lanzar ataques de área efectivos.",
  ui_story_5031_50310802_119_dialog_content = "Correcto, su mecha es más pesado, por lo que no puede realizar actos ágiles.",
  ui_story_5031_50310802_120_dialog_content = "¡Ciel aprovechó esto para matar instantáneamente a una gran cantidad de Eclipsites, cambiando las tornas al ganar un montón de puntos!",
  ui_story_5031_50310802_121_dialog_content = "Tratando de salir de una situación desesperada a pesar de sus desventajas. es inspirador",
  ui_story_5031_50310802_122_dialog_content = "Entonces, ¿el laird le daría una puntuación?",
  ui_story_5031_50310802_123_dialog_content = "Claro, maestro de ceremonias.",
  ui_story_5031_50310802_124_dialog_content = "E-Es eso...",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>Click-clack...</color>",
  ui_story_5031_50310802_126_dialog_content = "¿Ah?",
  ui_story_5031_50310802_127_dialog_content = "¡Oh, no! Styx no puede mantener una salida de energía tan alta...",
  ui_story_5031_50310802_128_dialog_content = "¡Ahhhhh! ¡Me estoy cayendo!",
  ui_story_5031_50310802_129_dialog_content = "Ciel!",
  ui_story_5031_50310802_130_dialog_content = "¡Hah!",
  ui_story_5031_50310802_131_dialog_content = "¿Eh? ¿Rainbow?",
  ui_story_5031_50310802_132_dialog_content = "Uhm...",
  ui_story_5031_50310802_133_dialog_content = "Ya puedes abrir los ojos. Te tengo.",
  ui_story_5031_50310802_134_dialog_content = "¿Qué?",
  ui_story_5031_50310802_135_dialog_content = "¿R-Rainbow?",
  ui_story_5031_50310802_136_dialog_content = "Eso fue imprudente. Cambiar a una salida de energía tan alta cuando tu mecha no estaba calibrado para ello.",
  ui_story_5031_50310802_137_dialog_content = "Lo siento.",
  ui_story_5031_50310802_138_dialog_content = "Styx experimentó una explosión y el daño no se reparó por completo.",
  ui_story_5031_50310802_139_dialog_content = "Perdona que te agobie...",
  ui_story_5031_50310802_140_dialog_content = "¿Es eso así? ¡Qué pena!",
  ui_story_5031_50310802_141_dialog_content = "¡Espero con ansias sus capacidades una vez que esté completamente reparado!",
  ui_story_5031_50310802_142_dialog_content = "...",
  ui_story_5031_50310802_143_dialog_content = "Uhm... ¿Arcoiris?",
  ui_story_5031_50310802_144_dialog_content = "¿Mmm? ¿Qué es?",
  ui_story_5031_50310802_145_dialog_content = "¿Por qué me salvaste? Si me caigo al mar, pierdo muchos puntos.",
  ui_story_5031_50310802_146_dialog_content = "¿Eh? Bien...",
  ui_story_5031_50310802_147_dialog_content = "Probablemente sea por eso, en comparación con los 5 millones de Nightium...",
  ui_story_5031_50310802_148_dialog_content = "Estoy más interesado en ti.",
  ui_story_5031_50310901_1_dialog_content = "¡Se acabó la primera ronda! Ahora, ¿los concursantes de la segunda ronda irían a sus puntos de partida asignados?",
  ui_story_5031_50310901_2_dialog_content = "Mientras tanto, se calcularán los puntajes finales de la primera ronda.",
  ui_story_5031_50310901_3_dialog_content = "Está bien, Fía. Todavía tenemos nuestra oportunidad.",
  ui_story_5031_50310901_4_dialog_content = "Sí. No te sientas mal. Nunca esperábamos que obtuvieras una puntuación alta.",
  ui_story_5031_50310901_5_dialog_content = "¡Ahhh!",
  ui_story_5031_50310901_6_dialog_content = "¡PlayerName estúpido!",
  ui_story_5031_50310901_7_dialog_content = "¿Eh? ¿Qué hice?",
  ui_story_5031_50310901_8_dialog_content = "Estaba tratando de consolarte.",
  ui_story_5031_50310901_9_dialog_content = "Solo detente primero, PlayerName.",
  ui_story_5031_50310901_10_dialog_content = "... Creo que hay un malentendido.",
  ui_story_5031_50310901_11_dialog_content = "Prepárense para la segunda ronda, todos.",
  ui_story_5031_50310901_12_dialog_content = "Escuché que Rainbow dijo que enviaría a Merylt a continuación.",
  ui_story_5031_50310901_13_dialog_content = "¿Hmm? ¿Estás bien, Fía?",
  ui_story_5031_50310901_14_dialog_content = "*Sollozo* Carleen! PlayerName, él...",
  ui_story_5031_50310901_15_dialog_content = "¡Espera un minuto! ¡Yo no hice nada!",
  ui_story_5031_50310901_16_dialog_content = "Fia, olvídate de él. Centrémonos en la siguiente ronda.",
  ui_story_5031_50310901_17_dialog_content = "Quieres el premio mon⁠—Me refiero al traje de baño... Y tenemos un Cloudwhale para salvar, ¿verdad?",
  ui_story_5031_50310901_18_dialog_content = "Boo-hoo, sí...",
  ui_story_5031_50310901_19_dialog_content = "Luego seca tus lágrimas. Discutamos nuestro arreglo para la próxima ronda.",
  ui_story_5031_50310901_20_dialog_content = "Entonces... ¡Propongo que PlayerName sea el siguiente!",
  ui_story_5031_50310901_21_dialog_content = "¡¿Eh?!",
  ui_story_5031_50310901_22_dialog_content = "¡Hmph! Te estabas riendo cuando me caí al agua, ¿no?",
  ui_story_5031_50310901_23_dialog_content = "¡Ahora es mi turno de reírme de ti!",
  ui_story_5031_50310901_24_dialog_content = "¿Cómo supiste que me estaba riendo⁠—No, espera. ¡Eso no tiene sentido!",
  ui_story_5031_50310901_25_dialog_content = "¡Pensé que ganar el juego era más importante!",
  ui_story_5031_50310901_26_dialog_content = "Solo necesitamos dos puntajes ganadores, así que ni siquiera necesito continuar, ¿verdad?",
  ui_story_5031_50310901_27_dialog_content = "¿Lo olvidaste, PlayerName? Tú y Fia se cuentan como uno.",
  ui_story_5031_50310901_28_dialog_content = "Se suma tu puntuación y la de Fia.",
  ui_story_5031_50310901_29_dialog_content = "Cierto... Eso pasó...",
  ui_story_5031_50310901_30_dialog_content = "no sabemos quien Vice y me enfrentaré cuando sea nuestro turno.",
  ui_story_5031_50310901_31_dialog_content = "Entonces, solo para estar seguro, es mejor que participes.",
  ui_story_5031_50310901_32_dialog_content = "Entonces tiene sentido enviar PlayerName a continuación.",
  ui_story_5031_50310901_33_dialog_content = "Verdadero. Merylt debería ser la más suave de las trillizas.",
  ui_story_5031_50310901_34_dialog_content = "Y no me siento oficial Gronru es bueno para surfear",
  ui_story_5031_50310901_35_dialog_content = "Entonces, si ese es el caso...",
  ui_story_5031_50310901_36_dialog_content = "Si ese es el caso...",
  ui_story_5031_50310901_37_dialog_content = "Lo sé, lo sé... Iré. Solo deja de mirarme.",
  ui_story_5031_50310901_38_dialog_content = "Jejeje! Buena suerte, PlayerName.",
  ui_story_5031_50310901_39_dialog_content = "Sin presión, ¿de acuerdo? Solo recuerda lo que te hemos enseñado.",
  ui_story_5031_50310901_40_dialog_content = "Está bien incluso si no pudieras hacerlo.",
  ui_story_5031_50310901_41_dialog_content = "Lo tengo, lo tengo.",
  ui_story_5031_50310901_42_dialog_content = "¡Hmph! ¡Será mejor que no seas el eslabón más débil, PlayerName!",
  ui_story_5031_50310901_43_dialog_content = "¡Tú mismo no obtuviste una buena puntuación!",
  ui_story_5031_50310901_44_dialog_content = "Mientras anunciamos el puntaje, ¿Llegarán todos los concursantes a sus posiciones?",
  ui_story_5031_50310901_45_dialog_content = "El ganador de la última ronda es... ¡Rainbow!",
  ui_story_5031_50310901_46_dialog_content = "Eso no es sorpresa. Ella es nuestro as.",
  ui_story_5031_50310901_47_dialog_content = "Rainbow-!",
  ui_story_5031_50310901_48_dialog_content = "Sin embargo, ¡hay algo que te dejará boquiabierto!",
  ui_story_5031_50310901_49_dialog_content = "Tenemos otro concursante con la misma puntuación compartiendo el mismo rango, y ese es... ¡Ciel!",
  ui_story_5031_50310901_50_dialog_content = "¡Esa es la chica mecha!",
  ui_story_5031_50310901_51_dialog_content = "¡Increíble! ¿¡Se puso al día con la puntuación de Rainbow!?",
  ui_story_5031_50310901_52_dialog_content = "¡Es increíble, Ciel!",
  ui_story_5031_50310901_53_dialog_content = "gracias oficial Gronru!",
  ui_story_5031_50310901_54_dialog_content = "Oficial Gronru? ¿¡Por qué estás aquí!?",
  ui_story_5031_50310901_55_dialog_content = "¡Deberías estar en tu posición!",
  ui_story_5031_50310901_56_dialog_content = "Bueno, eso es porque...",
  ui_story_5031_50310901_57_dialog_content = "Sé que quieres enfrentarnos a Merylt, PlayerName y a mí...",
  ui_story_5031_50310901_58_dialog_content = "Con la esperanza de aprovechar la situación, ¿no?",
  ui_story_5031_50310901_59_dialog_content = "...",
  ui_story_5031_50310901_60_dialog_content = "Uhm, bueno...",
  ui_story_5031_50310901_61_dialog_content = "¿Bien adivina que? ¡No te voy a poner las cosas tan fáciles!",
  ui_story_5031_50310901_62_dialog_content = "Hmm... No te pongas nervioso.",
  ui_story_5031_50310901_63_dialog_content = "Hay menos gente en esta ronda. Todo lo que necesito hacer es defenderme.",
  ui_story_5031_50310901_64_dialog_content = "PlayerName, eh...",
  ui_story_5031_50310901_65_dialog_content = "¿Qué pasó, Meryl?",
  ui_story_5031_50310901_66_dialog_content = "Uhm, tu tablero... No está conectado a ti.",
  ui_story_5031_50310901_67_dialog_content = "Es muy peligroso...",
  ui_story_5031_50310901_68_dialog_content = "¡Vaya! ¡Me olvidé completamente de eso!",
  ui_story_5031_50310901_69_dialog_content = "¡Muchas gracias Meryl!",
  ui_story_5031_50310901_70_dialog_content = "¡Eh...!",
  ui_story_5031_50310901_71_dialog_content = "¡Oh, ella acaba de sumergirse en el agua!",
  ui_story_5031_50310901_72_dialog_content = "¿Dije algo malo otra vez?",
  ui_story_5031_50310901_73_dialog_content = "Bueno, es hora.",
  ui_story_5031_50310901_74_dialog_content = "Empecemos la segunda ronda.",
  ui_story_5031_50310901_75_dialog_content = "Jajajaja... ¿Así, otra vez?",
  ui_story_5031_50310901_76_dialog_content = "¿Es ese el estilo del maestro de ceremonias del circo?",
  ui_story_5031_50310901_77_dialog_content = "Oh, no hay mecha en esta ronda. Que decepcionante.",
  ui_story_5031_50310901_78_dialog_content = "¿Eh? ¡Mirar! Esa es la niña de los trillizos del circo...",
  ui_story_5031_50310901_79_dialog_content = "¡Sus movimientos son incluso más elegantes que los de Rainbow!",
  ui_story_5031_50310901_80_dialog_content = "¡Por supuesto! ¡Merylt es uno de los miembros del circo con el mejor equilibrio y control!",
  ui_story_5031_50310901_81_dialog_content = "Domina el trapecio de alto vuelo y las anillas de gimnasia. ¡Hacer surf debería ser pan comido para ella!",
  ui_story_5031_50310901_82_dialog_content = "Realmente sabes todo lo que hay que saber sobre los miembros del circo.",
  ui_story_5031_50310901_83_dialog_content = "Bueno, no son solo mis empleados.",
  ui_story_5031_50310901_84_dialog_content = "Ellos son mi familia.",
  ui_story_5031_50310901_85_dialog_content = "...",
  ui_story_5031_50310901_86_dialog_content = "Eso en realidad me recuerda al viejo tú.",
  ui_story_5031_50310901_87_dialog_content = "¿Es eso así? ¿El mocoso inútil que siempre dependió de su familia y de ti?",
  ui_story_5031_50310901_88_dialog_content = "No. Ese niño inocente que lloraría por un pajarito que se cayó de su nido.",
  ui_story_5031_50310901_89_dialog_content = "Incluso te rompiste el brazo al intentar volver a ponértelo y llevaste un yeso durante seis meses.",
  ui_story_5031_50310901_90_dialog_content = "Y todavía estás tratando de cuidar a todos los que te rodean.",
  ui_story_5031_50310901_91_dialog_content = "Oh, suficiente con todas esas cosas vergonzosas sobre mí.",
  ui_story_5031_50310901_92_dialog_content = "Solo disfruta el juego.",
  ui_story_5031_50310901_93_dialog_content = "Ja... Está bien, está bien.",
  ui_story_5031_50310902_1_dialog_content = "Como era de esperar, el concursante con la puntuación más alta sigue siendo miembro de nuestro circo...",
  ui_story_5031_50310902_2_dialog_content = "merylt!",
  ui_story_5031_50310902_3_dialog_content = "¡Ohhhhhh!",
  ui_story_5031_50310902_4_dialog_content = "Este brillante resultado es el fruto de su interminable trabajo duro y sudor bajo las estrellas.",
  ui_story_5031_50310902_5_dialog_content = "¡Espero que su éxito inspire y despierte algo en todos ustedes, holgazanes!",
  ui_story_5031_50310902_X5_dialog_content = "...",
  ui_story_5031_50310902_X6_dialog_content = "Hmph, ¿tan avergonzado de que te quedes sin palabras? Bien, no todo el mundo quiere hacer algo con su vida.",
  ui_story_5031_50310902_X7_dialog_content = "Concursantes de la tercera ronda, ¡prepárense!",
  ui_story_5031_50310902_X8_dialog_content = "Concursantes de la tercera ronda, por favor prepárense.",
  ui_story_5031_50310902_6_dialog_content = "Concursantes de la tercera ronda, ¡prepárense!",
  ui_story_5031_50310902_7_dialog_content = "¿Eh? PlayerName, ¿ganas cero puntos? De ninguna manera.",
  ui_story_5031_50310902_8_dialog_content = "En cierto modo, eso está más allá de lo que una persona normal puede hacer.",
  ui_story_5031_50310902_9_dialog_content = "Sin que Carleen y Vice, realmente no sabemos qué hacer con Cloudwhale.",
  ui_story_5031_50310902_10_dialog_content = "*sollozo* es suficiente...",
  ui_story_5031_50310902_11_dialog_content = "Como Caelestita, lo siento.",
  ui_story_5031_50310902_12_dialog_content = "Oh, deja de culpar a PlayerName, Fia.",
  ui_story_5031_50310902_13_dialog_content = "No es realista pensar que un novato pueda aprender a surfear en un día.",
  ui_story_5031_50310902_14_dialog_content = "Nos pondremos al día. No te preocupes.",
  ui_story_5031_50310902_15_dialog_content = "Eres realmente confiable, Carleen, Vice!",
  ui_story_5031_50310902_16_dialog_content = "Suspiro, esfuérzate más y da lo mejor de ti, PlayerName.",
  ui_story_5031_50310902_17_dialog_content = "No te enfades. Dejaré de molestarte. Cuando domine cómo surfear, Carleen ¡y haré todo lo posible para enseñarte!",
  ui_story_5031_50310902_18_dialog_content = "Ja. Supongo que debería estar agradecido.",
  ui_story_5031_50310902_19_dialog_content = "¡Más te vale!",
  ui_story_5031_50310902_20_dialog_content = "U-Um, PlayerName...",
  ui_story_5031_50310902_21_dialog_content = "¿Eh? ¿Merylt? ¿Qué puedo hacer por ti?",
  ui_story_5031_50310902_22_dialog_content = "Uhm...",
  ui_story_5031_50310902_23_dialog_content = "¡Oh, déjame decirlo!",
  ui_story_5031_50310902_24_dialog_content = "PlayerName, ¡Merylt quiere disculparse por casi lastimarte!",
  ui_story_5031_50310902_25_dialog_content = "¡Oh eso! No te preocupes Meryl. No me lastimaste.",
  ui_story_5031_50310902_26_dialog_content = "Solo respiré un poco de agua porque yo también me asusté.",
  ui_story_5031_50310902_27_dialog_content = "Emm... Hmm...",
  ui_story_5031_50310902_28_dialog_content = "¡Eres tan amable, PlayerName! A diferencia del jefe!",
  ui_story_5031_50310902_29_dialog_content = "Tanta dulzura, no es de extrañar que Merylt se enamorara de ti... ¿¡Uhmm!?",
  ui_story_5031_50310902_30_dialog_content = "¡F-Frimet!",
  ui_story_5031_50310902_31_dialog_content = "¡Deberías ir a prepararte, n-ahora!",
  ui_story_5031_50310902_32_dialog_content = "¡Mmm! ¡Mmm!",
  ui_story_5031_50310902_33_dialog_content = "¡Ay, espérame!",
  ui_story_5031_50310902_34_dialog_content = "¿Oh?",
  ui_story_5031_50310902_35_dialog_content = "Eres bastante popular, PlayerName.",
  ui_story_5031_50310902_36_dialog_content = "...",
  ui_story_5031_50310902_37_dialog_content = "¿Eh? ¿De qué estás hablando?",
  ui_story_5031_50310902_38_dialog_content = "¡Nada!",
  ui_story_5031_50310902_39_dialog_content = "Mejor voy a prepararme. Va a empezar en cualquier momento.",
  ui_story_5031_50310902_40_dialog_content = "Si, vamos.",
  ui_story_5031_50310902_41_dialog_content = "Actuando todo misterioso...",
  ui_story_5031_50310902_42_dialog_content = "Vayamos a la playa entonces, Fia—",
  ui_story_5031_50310902_43_dialog_content = "¿Eh? ¿Fia?",
  ui_story_5031_50310902_44_dialog_content = "¿En serio? ¿Qué les está pasando a todos?",
  ui_story_5031_50310902_45_dialog_content = "Ahora que estamos en la tercera ronda, todos ya deberían conocer las reglas. Comencemos, entonces.",
  ui_story_5031_50310902_46_dialog_content = "¡Torrente rápido!",
  ui_story_5031_50310902_47_dialog_content = "Esa es una ofensiva poderosa.",
  ui_story_5031_50310902_48_dialog_content = "Parece que tendría que tomarlo en serio ahora. ¡Es hora de mostrar mi entrenamiento especial!",
  ui_story_5031_50310902_49_dialog_content = "*Tose*",
  ui_story_5031_50310902_50_dialog_content = "¡Elvis! ¿Dónde está tu medicina?",
  ui_story_5031_50310902_51_dialog_content = "Dentro... el bolsillo interior de mi abrigo.",
  ui_story_5031_50310902_52_dialog_content = "No olvides apagar el parlante... tos...",
  ui_story_5031_50310902_53_dialog_content = "No te preocupes. Lo apagué.",
  ui_story_5031_50310902_54_dialog_content = "¿Seguro que está en tu bolsillo? no puedo encontrarlo",
  ui_story_5031_50310902_55_dialog_content = "Tos, tos... Uf...",
  ui_story_5031_50310902_56_dialog_content = "Lo siento... ¿Tienes un pañuelo?",
  ui_story_5031_50310902_57_dialog_content = "Por supuesto. Un segundo.",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>Estrépito-</color>",
  ui_story_5031_50310902_59_dialog_content = "Tsk, demasiadas cosas.",
  ui_story_5031_50310902_60_dialog_content = "¿Puedes ser bueno en un momento como este?",
  ui_story_5031_50310902_61_dialog_content = "...",
  ui_story_5031_50310902_62_dialog_content = "Aquí.",
  ui_story_5031_50310902_63_dialog_content = "Gracias... Tos, tos...",
  ui_story_5031_50310902_64_dialog_content = "¡Esta es una ronda emocionante! ¡Menuda pelea!",
  ui_story_5031_50310902_65_dialog_content = "¡Sí! ¡Otro eclipse caído!",
  ui_story_5031_50310902_66_dialog_content = "¡Esa chica con un lazo es increíble!",
  ui_story_5031_50310902_67_dialog_content = "...",
  ui_story_5031_50310902_68_dialog_content = "Perdona, ¿puedes llevarme a algún lugar con menos gente para que pueda descansar un poco?",
  ui_story_5031_50310902_69_dialog_content = "Por supuesto.",
  ui_story_5031_50310902_70_dialog_content = "¡Eh, tú, allá!",
  ui_story_5031_50310902_71_dialog_content = "Sí tú.",
  ui_story_5031_50310902_72_dialog_content = "¿Si jefe?",
  ui_story_5031_50310902_73_dialog_content = "Mantenga la puntuación y reemplácese por mí por un rato. Tenemos un negocio que discutir.",
  ui_story_5031_50310902_74_dialog_content = "¡En eso!",
  ui_story_5031_50310902_75_dialog_content = "No me mires así. Estoy bien ahora.",
  ui_story_5031_50310902_76_dialog_content = "¿Multa? Toser sangre sobre mí no está BIEN.",
  ui_story_5031_50310902_77_dialog_content = "Lo siento por tu ropa.",
  ui_story_5031_50310902_78_dialog_content = "Sabes que eso no es lo que quise decir.",
  ui_story_5031_50310902_79_dialog_content = "No te preocupes. Solo significa que tengo más sangre de la que necesito... Es una buena señal, ¿no?",
  ui_story_5031_50310902_80_dialog_content = "Déjate de tonterías.",
  ui_story_5031_50310902_81_dialog_content = "¿De verdad no puedes decirme cuál es tu plan?",
  ui_story_5031_50310902_82_dialog_content = "Me aseguraré de hacerlo por ti si confías en mí.",
  ui_story_5031_50310902_83_dialog_content = "...",
  ui_story_5031_50310902_84_dialog_content = "¿Qué es esa mirada en tu cara?",
  ui_story_5031_50310902_85_dialog_content = "Oh, es solo que me recordaste nuestro pasado otra vez.",
  ui_story_5031_50310902_86_dialog_content = "¿Otra cosa vergonzosa que había hecho?",
  ui_story_5031_50310902_87_dialog_content = "Bueno, siempre fuiste más pequeño y delgado que yo, pero aun así, hiciste todo lo posible para ayudar a los demás, ayúdame.",
  ui_story_5031_50310902_88_dialog_content = "Y esa es exactamente la mirada en tus ojos ahora mismo.",
  ui_story_5031_50310902_89_dialog_content = "El tiempo puede haber dejado su huella en nosotros, pero no cambia quiénes somos.",
  ui_story_5031_50310902_90_dialog_content = "Sí... Algunas cosas cambian, pero otras permanecen igual.",
  ui_story_5031_50310902_91_dialog_content = "Al igual que todavía eres más bajo que yo.",
  ui_story_5031_50310902_92_dialog_content = "Tsk. Pero ahora, puedo tomar diez de ustedes.",
  ui_story_5031_50310902_93_dialog_content = "Sí... Ya no eres el Jeno que necesitaba mi protección.",
  ui_story_5031_50310902_94_dialog_content = "No es que esté en condiciones de protegerte ahora.",
  ui_story_5031_50310902_95_dialog_content = "Entonces es mi turno.",
  ui_story_5031_50310902_96_dialog_content = "Ja... No es tan fácil, y no puedes simplemente hablarlo.",
  ui_story_5031_50310902_97_dialog_content = "Hablo en serio, Elvis.",
  ui_story_5031_50310902_98_dialog_content = "Dime cuál es tu plan y encontraré la manera de hacerlo realidad.",
  ui_story_5031_50310902_99_dialog_content = "¿Qué pasa si se trata de la organización detrás de usted?",
  ui_story_5031_50310902_100_dialog_content = "¿...?",
  ui_story_5031_50310902_101_dialog_content = "¿Qué pasa si, qué pasa si. ¿Requiere tu nave y algo de su profundidad?",
  ui_story_5031_50310902_102_dialog_content = "¿Todavía ayudarás?",
  ui_story_5031_50310902_103_dialog_content = "Como supiste...?",
  ui_story_5031_50310902_104_dialog_content = "Eso no es importante, Jeno.",
  ui_story_5031_50310902_105_dialog_content = "Lo importante es que ya no somos niños y ya no podemos volver a ese tiempo simple.",
  ui_story_5031_50310902_106_dialog_content = "Cada una de nuestras decisiones, promesas, cada palabra lleva mucho más peso y carga.",
  ui_story_5031_50310902_107_dialog_content = "Entonces, déjame preguntarte de nuevo. Si ese es el caso, ¿me seguirás ayudando?",
  ui_story_5031_50310902_108_dialog_content = "...",
  ui_story_5031_50310902_109_dialog_content = "Yo... una vez hice una promesa.",
  ui_story_5031_50310902_110_dialog_content = "Prometí proteger la nave y proteger esa cosa.",
  ui_story_5031_50310902_111_dialog_content = "Ya veo... Lamento haberte puesto en esta posición.",
  ui_story_5031_50310902_112_dialog_content = "Lo mejor para nosotros es volver al juego. Parece que el trabajo es más de lo que su sustituto temporal puede manejar.",
  ui_story_5031_50310902_113_dialog_content = "Elvis, yo...",
  ui_story_5031_50310902_114_dialog_content = "Jeno.",
  ui_story_5031_50310902_115_dialog_content = "...",
  ui_story_5031_50310902_116_dialog_content = "Está bien. Entiendo.",
  ui_story_5031_50310902_117_dialog_content = "No importa qué, solo quiero que sepas...",
  ui_story_5031_50310902_118_dialog_content = "Te he extrañado durante los últimos doce años.",
  ui_story_5031_50310902_119_dialog_content = "¡...!",
  ui_story_5031_50311001_1_dialog_content = "Su Alteza.",
  ui_story_5031_50311001_2_dialog_content = "Matthieu? ¿Qué es?",
  ui_story_5031_50311001_3_dialog_content = "¿Vas a seguir con esta farsa?",
  ui_story_5031_50311001_4_dialog_content = "Estar en las mismas aguas que los plebeyos... Es repugnante.",
  ui_story_5031_50311001_5_dialog_content = "Sí lo soy.",
  ui_story_5031_50311001_6_dialog_content = "Si le resulta insoportable, es mejor que se quede en la playa o en el barco. Mejor aún, deberías regresar a Lumopolis.",
  ui_story_5031_50311001_7_dialog_content = "Tsk, qué actitud tan enfurecida...",
  ui_story_5031_50311001_8_dialog_content = "Matthieu.",
  ui_story_5031_50311001_9_dialog_content = "Hmph... Qué tarea. ¿Por qué debería proteger a una diva de princesa?",
  ui_story_5031_50311001_10_dialog_content = "...",
  ui_story_5031_50311001_11_dialog_content = "Matthieu, no soy una diva y esta princesa no necesita tu protección.",
  ui_story_5031_50311001_12_dialog_content = "Y si solo te molesta el hecho de que no puedes nadar, no te preocupes, estaré bien.",
  ui_story_5031_50311001_13_dialog_content = "No...",
  ui_story_5031_50311001_14_dialog_content = "¡¿Qué? De qué estás hablando?!",
  ui_story_5031_50311001_15_dialog_content = "¿¡No puedo nadar!? ¡No hay forma de que no pueda hacer algo que un humilde plebeyo puede hacer!",
  ui_story_5031_50311001_16_dialog_content = "¡Y, Loewe, te oí reírte de mí! ¡Cómo te atreves!",
  ui_story_5031_50311001_17_dialog_content = "Bueno, realmente no puedes nadar.",
  ui_story_5031_50311001_18_dialog_content = "¡Ahhhh! Tú...!",
  ui_story_5031_50311001_19_dialog_content = "¡Tuve suficiente! Princesa malhumorada, recuerda mis palabras, ¡te arrepentirás de mezclarte con los plebeyos!",
  ui_story_5031_50311001_20_dialog_content = "¡Me voy a cambiar!",
  ui_story_5031_50311001_21_dialog_content = "...",
  ui_story_5031_50311001_22_dialog_content = "¿Por qué están aquí...?",
  ui_story_5031_50311001_23_dialog_content = "Probablemente quería evitar que entrara en el juego porque él mismo no sabía nadar.",
  ui_story_5031_50311001_24_dialog_content = "Realmente no entiendo por qué Irridon incluso lo envió.",
  ui_story_5031_50311001_25_dialog_content = "Vice! ¡Estás de vuelta!",
  ui_story_5031_50311001_26_dialog_content = "Bienvenido de nuevo, Vice.",
  ui_story_5031_50311001_27_dialog_content = "Eras tan increíble, Vice! ¡Definitivamente obtendrás una puntuación alta!",
  ui_story_5031_50311001_28_dialog_content = "¡El Cloudwhale es tan bueno como el nuestro! ¡Y no tengo que escuchar a mi maestro hablando hasta el cansancio!",
  ui_story_5031_50311001_29_dialog_content = "Me das demasiado crédito, Fia.",
  ui_story_5031_50311001_30_dialog_content = "Los otros concursantes eran dignos oponentes.",
  ui_story_5031_50311001_31_dialog_content = "No pensé oficial Gronru Sería tan bueno surfeando... La subestimé.",
  ui_story_5031_50311001_32_dialog_content = "Está bien. Todavía tenemos una ronda más, pero su puntaje ya está arreglado.",
  ui_story_5031_50311001_33_dialog_content = "¡Ahora es el turno de Carleen!",
  ui_story_5031_50311001_34_dialog_content = "Matthieu y Loewe estuvieron aquí? ¿También están aquí para participar en el juego?",
  ui_story_5031_50311001_35_dialog_content = "No les hagas caso.",
  ui_story_5031_50311001_36_dialog_content = "Ahora que lo pienso, no hemos escuchado la voz de nuestro anfitrión en mucho tiempo.",
  ui_story_5031_50311001_37_dialog_content = "Estás bien. Me pregunto qué estarán haciendo él y Elvis.",
  ui_story_5031_50311001_38_dialog_content = "De todos modos, será mejor que te prepares, Carleen.",
  ui_story_5031_50311001_39_dialog_content = "Buena suerte, Carleen!",
  ui_story_5031_50311001_40_dialog_content = "Vamos, Carleen!",
  ui_story_5031_50311001_41_dialog_content = "Déjamelo a mí.",
  ui_story_5031_50311001_42_dialog_content = "...",
  ui_story_5031_50311001_43_dialog_content = "¿Jeno, señor?",
  ui_story_5031_50311001_44_dialog_content = "¿Qué?",
  ui_story_5031_50311001_45_dialog_content = "<size=33>¡Ah! ¿Qué pasa con el repentino cambio de actitud del jefe...?</size>",
  ui_story_5031_50311001_46_dialog_content = "Uhm... Los puntajes de la última ronda están aquí. ¿No vas a anunciarlo?",
  ui_story_5031_50311001_47_dialog_content = "...",
  ui_story_5031_50311001_48_dialog_content = "Uhm... O, al menos di la palabra para comenzar la siguiente ronda...",
  ui_story_5031_50311001_49_dialog_content = "Los concursantes están listos y esperando...",
  ui_story_5031_50311001_50_dialog_content = "Empezar.",
  ui_story_5031_50311001_51_dialog_content = "...",
  ui_story_5031_50311001_52_dialog_content = "Bien... Me estoy acostumbrando a él.",
  ui_story_5031_50311001_53_dialog_content = "¡Flor de hielo!",
  ui_story_5031_50311001_54_dialog_content = "¡Vaya! ¡Reacción rapida!",
  ui_story_5031_50311001_55_dialog_content = "¡Usó Lumina para congelar las olas!",
  ui_story_5031_50311001_56_dialog_content = "¡Y aceleró mientras ejecutaba el movimiento a la perfección!",
  ui_story_5031_50311001_57_dialog_content = "¡Esto es increíble! ¡Estoy muy emocionado!",
  ui_story_5031_50311001_58_dialog_content = "¡Ve!",
  ui_story_5031_50311001_59_dialog_content = "¡Graagh!",
  ui_story_5031_50311001_60_dialog_content = "¿Eh? ¿¡Congelar tantos eclipses al mismo tiempo!?",
  ui_story_5031_50311001_61_dialog_content = "¡Wow!",
  ui_story_5031_50311001_62_dialog_content = "Esa chica también salvó a Ranka, ¿no?",
  ui_story_5031_50311001_63_dialog_content = "Ella es alucinante. ¡Ella no solo es elegante, también es mortal contra todos esos Eclipsites!",
  ui_story_5031_50311001_64_dialog_content = "No solo eso, ¡incluso congeló la superficie del mar, convirtiéndolo en su camino! ¡Qué precisión!",
  ui_story_5031_50311001_65_dialog_content = "Espera, es su nombre Carleen?",
  ui_story_5031_50311001_66_dialog_content = "¡Ahora recuerdo! Ella es la princesa, ¿no?",
  ui_story_5031_50311001_67_dialog_content = "¡Increíble, simplemente increíble!",
  ui_story_5031_50311001_68_dialog_content = "¡Ella realmente tiene mi corazón latiendo fuerte! ¡Tengo que seguir!",
  ui_story_5031_50311001_69_dialog_content = "Uf...",
  ui_story_5031_50311001_70_dialog_content = "Eso es 62.",
  ui_story_5031_50311001_71_dialog_content = "Gronru golpeó 70 y Ciel clavó... 93.",
  ui_story_5031_50311001_72_dialog_content = "Tsk. Tener un mecha seguro es ventajoso en esto.",
  ui_story_5031_50311001_73_dialog_content = "Si Vice tengo 69... Mmm...",
  ui_story_5031_50311001_74_dialog_content = "Necesito derribar al menos 32 más y también anotar más con los movimientos.",
  ui_story_5031_50311001_75_dialog_content = "En cuanto al circo...",
  ui_story_5031_50311001_76_dialog_content = "Hola princesa Carleen. ¿Estás tomando un descanso aquí?",
  ui_story_5031_50311001_77_dialog_content = "Subli?",
  ui_story_5031_50311001_78_dialog_content = "¡Recuerdas mi nombre! ¡Estoy tan feliz!",
  ui_story_5031_50311001_79_dialog_content = "Solo llamame Carleen.",
  ui_story_5031_50311001_80_dialog_content = "Bien, Carleen.",
  ui_story_5031_50311001_81_dialog_content = "Me gustas mucho, pero tengo malas noticias para ti.",
  ui_story_5031_50311001_82_dialog_content = "¿Qué es?",
  ui_story_5031_50311001_83_dialog_content = "Nuestra estrategia es enviar a Rainbow y Merylt primero para anotar tantos puntos como puedan.",
  ui_story_5031_50311001_84_dialog_content = "En cuanto a Frimet y a mí...",
  ui_story_5031_50311001_85_dialog_content = "¡Estamos aquí para interferir con los otros concursantes!",
  ui_story_5031_50311001_86_dialog_content = "¡Uh!",
  ui_story_5031_50311001_87_dialog_content = "No es de extrañar que Frimet siguiera jugando con Vice!",
  ui_story_5031_50311001_88_dialog_content = "Sí... Así que no me odien, por favor. No es nada personal.",
  ui_story_5031_50311001_89_dialog_content = "Tsk! ¿Cómo se atreve un simple plebeyo a atacar a la Princesa? Carleen!",
  ui_story_5031_50311001_90_dialog_content = "¡Loewe, quiero que la derriben, ahora mismo!",
  ui_story_5031_50311001_91_dialog_content = "...",
  ui_story_5031_50311001_92_dialog_content = "Qué ágil... Seguro que creció en el circo.",
  ui_story_5031_50311001_93_dialog_content = "Estoy en desventaja aquí en un tablero tan estrecho...",
  ui_story_5031_50311001_94_dialog_content = "¡Vaya! Carleen, ¡eres increíble!",
  ui_story_5031_50311001_95_dialog_content = "¡Puedes mantener el equilibrio mientras te defiendes de mis ataques!",
  ui_story_5031_50311001_96_dialog_content = "¡Eres tan elegante, realmente te admiro!",
  ui_story_5031_50311001_97_dialog_content = "Uhm... En realidad no puedo lastimarla.",
  ui_story_5031_50311001_98_dialog_content = "Sólo tengo que tratar de poner algo de distancia entre nosotros.",
  ui_story_5031_50311001_99_dialog_content = "¿Eh? A dónde vas, Carleen?",
  ui_story_5031_50311001_100_dialog_content = "¿No quieres jugar conmigo un poco más? ¡Aún no me he divertido lo suficiente!",
  ui_story_5031_50311001_101_dialog_content = "¡Ahora es el tiempo!",
  ui_story_5031_50311001_102_dialog_content = "¡Flor de hielo!",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5031_50311001_104_dialog_content = "¡Ah!",
  ui_story_5031_50311001_105_dialog_content = "Lo siento. Es mejor que te quedes aquí.",
  ui_story_5031_50311001_106_dialog_content = "Ay... ¿Ah?",
  ui_story_5031_50311001_107_dialog_content = "¡Pensé que estaba perdido!",
  ui_story_5031_50311001_108_dialog_content = "¡Así que me congeló aquí!",
  ui_story_5031_50311001_109_dialog_content = "No puedo moverme, pero no estoy herido de ninguna manera, y mi cabeza no está en el hielo...",
  ui_story_5031_50311001_110_dialog_content = "¡Oh, qué control y precisión! ahora me gusta Carleen ¡aún más!",
  ui_story_5031_50311001_111_dialog_content = "Esa niña... Es tan rara.",
  ui_story_5031_50311001_112_dialog_content = "Al menos ya no es una amenaza. Todo lo que necesito hacer ahora es concentrarme en ganar puntos.",
  ui_story_5031_50311001_113_dialog_content = "Perdí demasiado tiempo en ese entonces. Tengo que compensarlo por el bien de todos.",
  ui_story_5031_50311002_1_dialog_content = "¡Reúnanse todos!",
  ui_story_5031_50311002_2_dialog_content = "¿Qué te pareció el concurso de surf?",
  ui_story_5031_50311002_3_dialog_content = "¡Lo amamos!",
  ui_story_5031_50311002_4_dialog_content = "Jejeje, yo también lo pasé genial!",
  ui_story_5031_50311002_5_dialog_content = "Todos ustedes han tenido un tiempo memorable aquí. ¡Es para siempre para que lo guardes!",
  ui_story_5031_50311002_6_dialog_content = "¡Ahora es el momento de anunciar la puntuación!",
  ui_story_5031_50311002_7_dialog_content = "Trago-",
  ui_story_5031_50311002_8_dialog_content = "Fia, tu sonido al tragar fue fuerte.",
  ui_story_5031_50311002_9_dialog_content = "¡No estoy ansioso en absoluto!",
  ui_story_5031_50311002_10_dialog_content = "No te preocupes. Carleen hizo un gran trabajo Estaremos bien.",
  ui_story_5031_50311002_11_dialog_content = "Solo alcancé la puntuación de Gronru al matar a los Eclipsites...",
  ui_story_5031_50311002_12_dialog_content = "En cuanto a la puntuación de mis movimientos... Habrá que ver.",
  ui_story_5031_50311002_13_dialog_content = "Rainbow y su equipo... aún pueden estar por delante de nosotros.",
  ui_story_5031_50311002_14_dialog_content = "¡Bien! ¡No te haré esperar!",
  ui_story_5031_50311002_15_dialog_content = "El ganador del concurso de surf es...",
  ui_story_5031_50311002_16_dialog_content = "¡Atentamente! ¡La Esmeralda!",
  ui_story_5031_50311002_17_dialog_content = "Los cálculos detallados y la puntuación se publicarán en el tablón de anuncios. ¡Por favor, compruébalo si tienes dudas!",
  ui_story_5031_50311002_18_dialog_content = "¡Prometo que es la puntuación legítima de toda la audiencia aquí! ¡Sin favores!",
  ui_story_5031_50311002_19_dialog_content = "¡Wow!",
  ui_story_5031_50311002_20_dialog_content = "¡Rainbow, te lo mereces!",
  ui_story_5031_50311002_21_dialog_content = "¡Gracias por su apoyo a Esmeralda!",
  ui_story_5031_50311002_22_dialog_content = "¡Y agradecemos al laird por los 5 millones de Nightium!",
  ui_story_5031_50311002_23_dialog_content = "¡Jajajaja!",
  ui_story_5031_50311002_24_dialog_content = "¡Muy triste!",
  ui_story_5031_50311002_25_dialog_content = "Nightium... 5 millones de Nightium...",
  ui_story_5031_50311002_26_dialog_content = "Boo-hoo, mi traje de baño...!",
  ui_story_5031_50311002_27_dialog_content = "Está bien. El Emerald no es un equipo de carnaval, por lo que todavía tenemos una oportunidad en el Cloudwhale.",
  ui_story_5031_50311002_28_dialog_content = "En cuanto al traje de baño... Todavía podemos pagarlo sin el dinero del premio.",
  ui_story_5031_50311002_29_dialog_content = "¿En serio? ¿De verdad me vas a comprar un traje de baño, PlayerName?",
  ui_story_5031_50311002_30_dialog_content = "Claro, si dejas de enojar a la gente y de chismear y solo eres una buena chica.",
  ui_story_5031_50311002_31_dialog_content = "¿¡Qué!? ¡Soy una señorita! ¿De dónde viene esa impresión tuya?",
  ui_story_5031_50311002_32_dialog_content = "¿Quieres decir que no puedes hacerlo? Oh, no importa entonces.",
  ui_story_5031_50311002_33_dialog_content = "¡Ahhh! ¡Pero tu lo prometiste! ¡No puedes retractarte de una promesa!",
  ui_story_5031_50311002_34_dialog_content = "...",
  ui_story_5031_50311002_35_dialog_content = "¡A continuación, nuestro equipo subcampeón!",
  ui_story_5031_50311002_36_dialog_content = "¡Cállate! ¡Ya están anunciando el subcampeón!",
  ui_story_5031_50311002_37_dialog_content = "El subcampeón es...",
  ui_story_5031_50311002_38_dialog_content = "Gronru y Ciel, de Illumina!",
  ui_story_5031_50311002_39_dialog_content = "¡Wow!",
  ui_story_5031_50311002_40_dialog_content = "¡¿Qué?!",
  ui_story_5031_50311002_41_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>¿Eh?</size>",
  ui_story_5031_50311002_43_dialog_content = "Su... Gronru y ciel?",
  ui_story_5031_50311002_44_dialog_content = "E-Entonces... ¿Eso no significa...?",
  ui_story_5031_50311002_45_dialog_content = "¿No seríamos nosotros los que llevaríamos el premio a casa...?",
  ui_story_5031_50311002_46_dialog_content = "¿¡E-La Ballena Nube va a ser de otra persona!?",
  ui_story_5031_50311002_47_dialog_content = "¡Ahhhh! ¡El maestro me va a regañar hasta la muerte!",
  ui_story_5031_50311002_48_dialog_content = "...",
  ui_story_5031_50311002_49_dialog_content = "Carleen? ¿A dónde vas?",
  ui_story_5031_50311002_50_dialog_content = "¡Carleen!",
  ui_story_5031_50311002_51_dialog_content = "Espera, Carleen. ¿A dónde vas?",
  ui_story_5031_50311002_52_dialog_content = "Coche⁠—",
  ui_story_5031_50311002_53_dialog_content = "Lo siento, PlayerName y Vice, pero me gustaría estar solo un rato.",
  ui_story_5031_50311002_54_dialog_content = "N-Podemos ir.",
  ui_story_5031_50311002_55_dialog_content = "Pero estamos preocupados por ti. ¿Podrías al menos...",
  ui_story_5031_50311002_56_dialog_content = "Al menos cuéntanos... ¿Qué pasó?",
  ui_story_5031_50311002_56X1_dialog_content = "Sí. ¿Hicimos algo mal?",
  ui_story_5031_50311002_56X2_dialog_content = "No, no... No tiene nada que ver contigo.",
  ui_story_5031_50311002_57_dialog_content = "Yo solo... siento que soy un perdedor.",
  ui_story_5031_50311002_58_dialog_content = "Hice de todo, pero aun así no logré ganárselo a mis amigos... y no pude conseguirle lo que quería.",
  ui_story_5031_50311002_59_dialog_content = "Pero no es tu culpa.",
  ui_story_5031_50311002_60_dialog_content = "A decir verdad, yo debería ser el responsable...",
  ui_story_5031_50311002_61_dialog_content = "Todos hicieron lo mejor que pudieron, pero lo arruiné todo porque no aprendí a surfear.",
  ui_story_5031_50311002_62_dialog_content = "Eso es diferente...",
  ui_story_5031_50311002_63_dialog_content = "¿Cómo es diferente? Se siente igual.",
  ui_story_5031_50311002_64_dialog_content = "Gracias por decir eso, pero es mi culpa, no la tuya, y eso es un hecho.",
  ui_story_5031_50311002_65_dialog_content = "Este es un deporte de equipo. Nadie debería asumir toda la culpa.",
  ui_story_5031_50311002_66_dialog_content = "Yo soy el que necesita disculparse y agradecer.",
  ui_story_5031_50311002_67_dialog_content = "Sin ti, no seríamos capaces de llegar tan lejos.",
  ui_story_5031_50311002_68_dialog_content = "...",
  ui_story_5031_50311002_69_dialog_content = "Del mismo modo, ¿crees que podemos llegar tan lejos sin Vice?",
  ui_story_5031_50311002_70_dialog_content = "No...",
  ui_story_5031_50311002_71_dialog_content = "Mira, entonces lo entiendes. Es lo que sentimos por ti.",
  ui_story_5031_50311002_72_dialog_content = "En cuanto al premio, la ballena o lo que sea, solo tenemos que encontrar otra forma.",
  ui_story_5031_50311002_73_dialog_content = "No es como si fuera el fin del mundo si no ganamos.",
  ui_story_5031_50311002_74_dialog_content = "Sí, Carleen. Como mínimo, podemos ver a Jeno, oficial Gronru, o Rainbow.",
  ui_story_5031_50311002_75_dialog_content = "Podemos contarles acerca de Cloudwhale. Estoy seguro de que estarán dispuestos a ayudar.",
  ui_story_5031_50311002_75X1_dialog_content = "Vice es correcto. Nada de esto es un problema que no se pueda resolver.",
  ui_story_5031_50311002_76_dialog_content = "Entonces, deja de estar tan molesto, Carleen.",
  ui_story_5031_50311002_77_dialog_content = "Averigüemos algo juntos.",
  ui_story_5031_50311002_78_dialog_content = "...",
  ui_story_5031_50311002_79_dialog_content = "Está bien...",
  ui_story_5031_50311002_80_dialog_content = "Estás bien. Gracias.",
  ui_story_5031_50311002_81_dialog_content = "Debería aprender de ti. Tal vez esto es lo que mi padre quería...",
  ui_story_5031_50311002_82_dialog_content = "Caballero Schwartz? ¿Qué quieres decir?",
  ui_story_5031_50311002_83_dialog_content = "De hecho, antes de este viaje, tuvimos una... conversación.",
  ui_story_5031_50311002_83X1_dialog_content = "¿Conversación?",
  ui_story_5031_50311002_83X2_dialog_content = "Sí. Padre quisiera que contemplara el propósito de viajar contigo.",
  ui_story_5031_50311002_83X3_dialog_content = "Creo que entendí lo que quiso decir. Hay muchas cosas que puedo aprender de ti.",
  ui_story_5031_50311002_83X4_dialog_content = "No es de extrañar que hayas estado perdido en tu propio mundo todo el día, Carleen.",
  ui_story_5031_50311002_83X5_dialog_content = "Pero incluso después de estrujarme el cerebro, muchas cosas aún están más allá de mí.",
  ui_story_5031_50311002_83X6_dialog_content = "Como el avance del que hablaste, Vice. De hecho, lo probé hoy.",
  ui_story_5031_50311002_83X7_dialog_content = "¿eh? ¿Intentaste?",
  ui_story_5031_50311002_83X8_dialog_content = "Sí, y seguí lo que me sugeriste, la liberación de la conciencia.",
  ui_story_5031_50311002_83X9_dialog_content = "Pero seguí recordando la conversación con mi padre... y por eso no podía concentrarme.",
  ui_story_5031_50311002_83X10_dialog_content = "Así que fallé.",
  ui_story_5031_50311002_83X11_dialog_content = "Ya veo. Sin embargo, eso es bastante común.",
  ui_story_5031_50311002_83X12_dialog_content = "Es muy difícil liberarse de cualquier emoción para poder estar totalmente concentrado.",
  ui_story_5031_50311002_83X13_dialog_content = "Para mí, me deshice de todos los demás pensamientos porque me aferré a ese destello.",
  ui_story_5031_50311002_83X14_dialog_content = "¿Destello? Recuerdo que lo mencionaste. ¿Qué era?",
  ui_story_5031_50311002_83X15_dialog_content = "Um... Pensé en las cosas divertidas que hice contigo y PlayerName.",
  ui_story_5031_50311002_83X16_dialog_content = "Y antes de que me diera cuenta, hubo silencio dentro de mí.",
  ui_story_5031_50311002_83X17_dialog_content = "Pero eso es bastante profundo y difícil de describir para mí.",
  ui_story_5031_50311002_83X18_dialog_content = "Ya veo. Entonces yo...",
  ui_story_5031_50311002_84_dialog_content = "¡PlayerName! Carleen! Vice!",
  ui_story_5031_50311002_85_dialog_content = "¿Por qué me dejaste atrás? ¡Te hemos estado buscando!",
  ui_story_5031_50311002_85X1_dialog_content = "Ups, ¡no puedo creer que nos hayamos olvidado de ti! Teníamos tanta prisa.",
  ui_story_5031_50311002_86_dialog_content = "¿Qué te pasa, Fía? ¿Por qué estás tan nervioso?",
  ui_story_5031_50311002_87_dialog_content = "¡Buscándote, por supuesto!",
  ui_story_5031_50311002_88_dialog_content = "¡Escucha Escucha! Jeno acaba de venir a decirnos que...",
  ui_story_5031_50311002_89_dialog_content = "¡La clasificación del concurso de surf solo sirve para decidir la secuencia del próximo concurso! ¡Aún tenemos otro concurso!",
  ui_story_5031_50311002_90_dialog_content = "¡Actuamos con el circo como miembros!",
  ui_story_5031_50311002_91_dialog_content = "¡Eso significa que todavía tenemos una oportunidad!",
  ui_story_5031_50311101_1_dialog_content = "Espera, entonces, ¿qué es exactamente⁠—",
  ui_story_5031_50311101_2_dialog_content = "Boo-hoo—<size=45>Waaaagh!!</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>Nuestro... gran objetivo...</size>",
  ui_story_5031_50311101_4_dialog_content = "La Ballena Nube... ¡A este ritmo, perderemos la Ballena Nube! <size=45>¡Waaagh!</size>",
  ui_story_5031_50311101_5_dialog_content = "(Caramba... La batalla final más importante se acerca...)",
  ui_story_5031_50311101_6_dialog_content = "(Pero las maravillosas bestias están haciendo un berrinche y simplemente no escuchan a Fia).",
  ui_story_5031_50311101_7_dialog_content = "(Vamos a ser eliminados así. ¡Será mejor que hable con Fia para que se esfuerce más!)",
  ui_story_5031_50311101_8_option_content = "¡Fia, no te enfades!",
  ui_story_5031_50311101_9_dialog_content = "D-¿Eso significa que tienes una idea, PlayerName?",
  ui_story_5031_50311101_10_dialog_content = "Para ser honesto, no. Pero solo tenemos menos de una hora para ensayar.",
  ui_story_5031_50311101_11_dialog_content = "El público vendrá a ver la actuación después de eso.",
  ui_story_5031_50311101_12_dialog_content = "¡Estamos tan muertos! ¡Waaagh!",
  ui_story_5031_50311101_13_dialog_content = "¡Para para! ¡Para de llorar!",
  ui_story_5031_50311101_14_dialog_content = "¿Recuerda? Cruzamos todo el Astra para proteger a las maravillosas bestias contra viento y marea.",
  ui_story_5031_50311101_15_dialog_content = "¡Logramos hacer ESO! No hay forma de que algo como esto pueda deprimirnos, ¿verdad?",
  ui_story_5031_50311101_16_dialog_content = "Si te esforzaras más para comunicarte con Bica, ¡podríamos darles una gran actuación!",
  ui_story_5031_50311101_17_dialog_content = "¿Hola?",
  ui_story_5031_50311101_18_dialog_content = "Yo... estoy vencido.",
  ui_story_5031_50311101_19_dialog_content = "Quiero decir, entramos en el concurso sin siquiera saber si el premio final era realmente la Ballena Nube.",
  ui_story_5031_50311101_20_dialog_content = "(¿¡Y recién te diste cuenta de eso ahora!?)",
  ui_story_5031_50311101_21_dialog_content = "¡Oye! ¡Esa mirada en tu cara! Estás pensando algo malo sobre mí, ¿¡no es así!?",
  ui_story_5031_50311101_22_dialog_content = "¡NO! ¡Por supuesto que no! ¡No me atrevería!",
  ui_story_5031_50311101_23_dialog_content = "¿Qué tal esto? Hagamos como que vamos al baño y veamos si el premio es la Ballena Nube.",
  ui_story_5031_50311101_24_dialog_content = "Si es así, estarías motivado para ensayar con Bica, ¿no?",
  ui_story_5031_50311101_25_dialog_content = "P-¿Podemos realmente hacer eso?",
  ui_story_5031_50311101_26_dialog_content = "Ese Jeno parece un tipo temible. Sería malo si lo enojamos.",
  ui_story_5031_50311101_27_dialog_content = "Oh, solo será un vistazo rápido. ¡Estará bien!",
  ui_story_5031_50311101_28_dialog_content = "¡También intentaré usar mis habilidades psíquicas para que nadie se entere!",
  ui_story_5031_50311101_29_dialog_content = "Mmm... ¡Cierto! ¡Eso servirá!",
  ui_story_5031_50311101_30_dialog_content = "Confío en ti, PlayerName. ¡Mi bestia maravillosa \"súper exótica\", la Caelestite!",
  ui_story_5031_50311101_31_dialog_content = "¡Vamos, deja de llamarme bestia maravillosa!",
  ui_story_5031_50311101_32_dialog_content = "Oh no importa. No tenemos mucho tiempo. ¡Movámonos!",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>En algún lugar profundo dentro de la nave</color>",
  ui_story_5031_50311101_34_dialog_content = "Este es el lugar al que el feroz dueño no nos dejaría entrar.",
  ui_story_5031_50311101_35_dialog_content = "¡Es un laberinto! Todos los pasillos tienen el mismo aspecto y tantos caminos bifurcados...",
  ui_story_5031_50311101_36_dialog_content = "¿Dónde están escondiendo la Ballena Nube?",
  ui_story_5031_50311101_37_dialog_content = "Detente, Fía.",
  ui_story_5031_50311101_38_dialog_content = "Ocultémonos aquí un rato. Siento que alguien viene hacia aquí.",
  ui_story_5031_50311101_39_dialog_content = "*Bostezo* Ya es la tercera ronda de patrullaje.",
  ui_story_5031_50311101_40_dialog_content = "No sé en qué está pensando el jefe mandándonos a patrullar a un lugar tan hermético como este.",
  ui_story_5031_50311101_41_dialog_content = "¿Por qué habría patrullas en un circo? ¿Podría el dueño del circo estar escondiendo algo?",
  ui_story_5031_50311101_42_dialog_content = "Sin ti, definitivamente ya me atraparían y me echarían, PlayerName.",
  ui_story_5031_50311101_43_dialog_content = "Todo es gracias a ti, PlayerName. ¡Cuando encontremos la Ballena Nube, me aseguraré de recompensarte!",
  ui_story_5031_50311101_44_dialog_content = "¿Qué tal un paquete de galletas de animales? A Kyllo le encanta. ¿Crees que te gustará, PlayerName?",
  ui_story_5031_50311101_45_dialog_content = "Pensemos en eso después de encontrar el premio.",
  ui_story_5031_50311101_46_dialog_content = "Uhm...",
  ui_story_5031_50311101_47_dialog_content = "Sostener. Siento a dos personas adelante... Pero no se mueven.",
  ui_story_5031_50311101_48_dialog_content = "Tratemos de escabullirnos, entonces.",
  ui_story_5031_50311101_49_dialog_content = "¡Espera!",
  ui_story_5031_50311101_50_dialog_content = "¿Ahora qué?",
  ui_story_5031_50311101_51_dialog_content = "Estas dos personas se sienten... familiares, de alguna manera.",
  ui_story_5031_50311101_52_dialog_content = "¿Elvis y Patou?",
  ui_story_5031_50311101_53_dialog_content = "¿El laird y el guardia? ¿Por qué están ellos aquí?",
  ui_story_5031_50311101_54_dialog_content = "¿Cómo puedo saber? Olvidémonos de ellos primero y concentrémonos en nuestro objetivo.",
  ui_story_5031_50311101_55_dialog_content = "Guardemos silencio y no los alertemos de nuestra presencia.",
  ui_story_5031_50311101_56_dialog_content = "Lo siento señor. Hemos buscado en la residencia de Jeno y en todas partes relacionadas, pero no encontramos nada que se parezca a una llave.",
  ui_story_5031_50311101_57_dialog_content = "Está bien. Yo sé donde está.",
  ui_story_5031_50311101_58_dialog_content = "Mantiene la llave con él en todo momento.",
  ui_story_5031_50311101_59_dialog_content = "Ahora, eso va a ser difícil...",
  ui_story_5031_50311101_60_dialog_content = "Está bien. El plan todavía está en marcha. Tenemos que hacer que funcione esta noche.",
  ui_story_5031_50311101_61_dialog_content = "¿El plan? PlayerName, están hablando de algún plan⁠—",
  ui_story_5031_50311101_62_option_content = "¡Cállate!",
  ui_story_5031_50311101_63_dialog_content = "¿Escuchaste eso?",
  ui_story_5031_50311101_64_dialog_content = "¿Quién está ahí? ¡Sal, ahora!",
  ui_story_5031_50311101_65_dialog_content = "(¡Oh, no! ¡Corre!)",
  ui_story_5031_50311101_66_dialog_content = "Huff, huff. Llegamos a la cubierta.",
  ui_story_5031_50311101_67_dialog_content = "¡¡¡Suspiro!!! ¡Fuiste tan grosero, PlayerName! ¡Casi me asfixias!",
  ui_story_5031_50311101_68_dialog_content = "¡Lo siento! Estaba demasiado concentrado en escapar.",
  ui_story_5031_50311101_69_dialog_content = "¡Se dirigieron hacia allí!",
  ui_story_5031_50311101_70_dialog_content = "*Tos* Vamos a... encontrarlos.",
  ui_story_5031_50311101_71_dialog_content = "¡Vaya! Todavía están en nuestra cola. ¡Será mejor que encontremos un lugar para escondernos!",
  ui_story_5031_50311101_72_dialog_content = "¡Hola, PlayerName y Little Fia!",
  ui_story_5031_50311101_73_dialog_content = "¡No soy pequeño!",
  ui_story_5031_50311101_74_dialog_content = "¿Has terminado de ensayar?",
  ui_story_5031_50311101_75_dialog_content = "¿Eh? N-No, todavía no. Pero necesitábamos hacer algo, así que por favor, disculpe...",
  ui_story_5031_50311101_76_dialog_content = "Jeje! ¡Tengo un as bajo la manga!",
  ui_story_5031_50311101_77_dialog_content = "¡Con la ayuda del Trono, seguramente seré el ganador esta vez!",
  ui_story_5031_50311101_78_dialog_content = "¿¡Por qué no te doy un adelanto, mi rival derrotado!?",
  ui_story_5031_50311101_79_dialog_content = "(Oh, no, nos enredamos con Gronru. ¿Hay algún lugar para esconderse cerca?)",
  ui_story_5031_50311101_80_dialog_content = "PlayerName, ¡casi están sobre nosotros!",
  ui_story_5031_50311101_81_dialog_content = "¡Usa tus habilidades psíquicas para hacer algo!",
  ui_story_5031_50311101_82_dialog_content = "¡No funciona así!",
  ui_story_5031_50311101_83_dialog_content = "Invencible-",
  ui_story_5031_50311101_84_dialog_content = "Mar azul-",
  ui_story_5031_50311101_85_dialog_content = "<size=45>¡¡Trono!!</size>",
  ui_story_5031_50311101_86_dialog_content = "¡La luz, es tan cegadora!",
  ui_story_5031_50311101_87_dialog_content = "Ugh... ¿¡Qué pasa con esa luz!?",
  ui_story_5031_50311101_88_dialog_content = "Increíble, ¿no?",
  ui_story_5031_50311101_89_dialog_content = "¡Proporciona iluminación a mi Trono!",
  ui_story_5031_50311101_90_dialog_content = "De esta manera, ¡incluso puedo surfear en las noches más oscuras!",
  ui_story_5031_50311101_91_dialog_content = "Está bien. ¿E-Eso es genial?",
  ui_story_5031_50311101_92_dialog_content = "¡Eso es increíble!",
  ui_story_5031_50311101_93_dialog_content = "¿¡Atrajo la atención de tanta gente!?",
  ui_story_5031_50311101_94_dialog_content = "¡Eso fue increíble! ¿Puedes hacerlo de nuevo?",
  ui_story_5031_50311101_95_dialog_content = "¿Otra vez? ¡Por supuesto!",
  ui_story_5031_50311101_96_dialog_content = "Tsk. Hay demasiada gente aquí. Ya deben haberse escapado.",
  ui_story_5031_50311101_97_dialog_content = "Está bien. Es posible que hayan escuchado a escondidas, pero no afecta nuestro plan.",
  ui_story_5031_50311101_98_dialog_content = "Regresemos. Todo va de acuerdo al plan.",
  ui_story_5031_50311101_99_dialog_content = "Como usted ordene.",
  ui_story_5031_50311101_100_dialog_content = "Se fueron. Qué alivio.",
  ui_story_5031_50311101_101_dialog_content = "Muchas gracias, Gronru!",
  ui_story_5031_50311101_102_dialog_content = "¿eh? ¿Gracias por qué? ¿De qué estás hablando?",
  ui_story_5031_50311101_103_dialog_content = "Te lo agradeceremos una vez que todo esto termine.",
  ui_story_5031_50311101_104_dialog_content = "Pero tenemos cosas que hacer. ¡Luego!",
  ui_story_5031_50311101_105_dialog_content = "Oye, ¿¡por qué tienes prisa, mi derrotado rival!?",
  ui_story_5031_50311101_106_dialog_content = "Bueno, al menos ahora se ven más relajados.",
  ui_story_5031_50311101_107_dialog_content = "¡Deben haber disfrutado de mi extraordinaria actuación!",
  ui_story_5031_50311101_108_dialog_content = "Después de pasar por todos los problemas, no solo perdimos el tiempo, sino que todavía no descubrimos cuál es el gran premio.",
  ui_story_5031_50311101_109_dialog_content = "No hay nada que podamos hacer. Era enorme y estaba lleno de guardias dentro de la nave.",
  ui_story_5031_50311101_110_dialog_content = "No hay forma de que podamos registrar todo el barco solo nosotros dos.",
  ui_story_5031_50311101_111_dialog_content = "¡Parece que tendremos que hacerlo de la manera difícil y ser el ganador!",
  ui_story_5031_50311101_112_dialog_content = "Pero... Estamos fuera de tiempo...",
  ui_story_5031_50311101_113_dialog_content = "Mi Ballena Nube... Mi pobre Ballena Nube ya debe estar...",
  ui_story_5031_50311101_114_dialog_content = "¿¡Por qué estás llorando de nuevo!?",
  ui_story_5031_50311101_115_dialog_content = "PlayerName, Fia. ¿Sigues ensayando?",
  ui_story_5031_50311101_116_dialog_content = "¿Le dijiste algo grosero a Fia para hacerla llorar?",
  ui_story_5031_50311101_117_option_content = "¡De ninguna manera!",
  ui_story_5031_50311101_118_option_content = "¡No soy yo!",
  ui_story_5031_50311101_119_dialog_content = "Bica simplemente no colabora, por lo que Fia entra en pánico.",
  ui_story_5031_50311101_120_dialog_content = "¡Hiya!",
  ui_story_5031_50311101_121_dialog_content = "Ellos... ¡No te están alabando!",
  ui_story_5031_50311101_122_dialog_content = "¿Hola?",
  ui_story_5031_50311101_123_dialog_content = "Extraño. Pensé que tenían una buena relación.",
  ui_story_5031_50311101_124_dialog_content = "¿Cómo es que Bica de repente no colabora?",
  ui_story_5031_50311101_125_dialog_content = "¿No hablaste con Bica sobre eso?",
  ui_story_5031_50311101_126_dialog_content = "¡Hablé, pero Bica simplemente no escucha!",
  ui_story_5031_50311101_127_dialog_content = "¿Qué le dijiste a Bica?",
  ui_story_5031_50311101_128_dialog_content = "Le dije a Bica que trabajara conmigo para ganar ese importante premio.",
  ui_story_5031_50311101_129_dialog_content = "Entonces, ¿qué dijo Bica?",
  ui_story_5031_50311101_130_dialog_content = "Bica no dijo nada...",
  ui_story_5031_50311101_131_dialog_content = "¡¿Así que Bica no estuvo de acuerdo después de todo?!",
  ui_story_5031_50311101_132_dialog_content = "Pero Bica ya prometió ser mi pareja temporal... ¡¿Cómo no va a estar de acuerdo?!",
  ui_story_5031_50311101_133_dialog_content = "¡¡¡Waaaah!!!",
  ui_story_5031_50311101_134_dialog_content = "Oh, no llores, Fia... Eres la única que puede ayudarse esta vez.",
  ui_story_5031_50311101_135_dialog_content = "¿Ayudarme a mí mismo?",
  ui_story_5031_50311101_136_dialog_content = "Es posible que Bica haya aceptado ser tu pareja, pero eso no significa que puedas ordenar las cosas.",
  ui_story_5031_50311101_137_dialog_content = "Estás en esta situación en este momento solo porque realmente no escuchaste a Bica.",
  ui_story_5031_50311101_138_dialog_content = "¿Entonces, qué debería hacer?",
  ui_story_5031_50311101_139_dialog_content = "Primero, discúlpate con Bica.",
  ui_story_5031_50311101_140_dialog_content = "No solo disculpas. ¡Tienes que pedir la ayuda de Bica en esto y tener el consentimiento de Bica!",
  ui_story_5031_50311101_141_dialog_content = "¿Bica me echaría una mano esta vez?",
  ui_story_5031_50311101_142_dialog_content = "Se ve mucho más feroz que una Bica salvaje...",
  ui_story_5031_50311101_143_dialog_content = "Eso depende de tu actitud.",
  ui_story_5031_50311101_144_dialog_content = "Puedes hacerlo, Fía.",
  ui_story_5031_50311101_145_dialog_content = "Sí. no te rindas Solo da lo mejor de ti.",
  ui_story_5031_50311101_146_dialog_content = "Al-Bien. Voy a tratar de.",
  ui_story_5031_50311101_147_dialog_content = "Bica, yo...",
  ui_story_5031_50311101_148_dialog_content = "Lo siento.",
  ui_story_5031_50311101_149_dialog_content = "¿Hai, hai?",
  ui_story_5031_50311101_150_dialog_content = "(Bica pone sus patas al lado de sus orejas. ¿Le está pidiendo a Fia que hable más fuerte?)",
  ui_story_5031_50311101_151_dialog_content = "Yo...",
  ui_story_5031_50311101_152_dialog_content = "<size=45>¡Lo siento!</size>",
  ui_story_5031_50311101_153_dialog_content = "Fue mi culpa. No debí obligarte a ayudar con mi actuación, ignorando tu voluntad...",
  ui_story_5031_50311101_154_dialog_content = "Lo siento mucho. No sucederá la próxima vez... ¡E-No habrá una próxima vez!",
  ui_story_5031_50311101_155_dialog_content = "Siempre te preguntaré sobre tus sentimientos con anticipación en el futuro... Boo-hoo...",
  ui_story_5031_50311101_156_dialog_content = "¿Hola?",
  ui_story_5031_50311101_157_dialog_content = "¿Y después? Er, después... ¿qué tal si te invito a una buena comida?",
  ui_story_5031_50311101_158_dialog_content = "Hai, hai, hai?",
  ui_story_5031_50311101_159_dialog_content = "¿Eh? ¿Quieres tener las uvas legendarias del Sr. Peng?",
  ui_story_5031_50311101_160_dialog_content = "¿Dijiste que otra Bica te dijo eso?",
  ui_story_5031_50311101_161_dialog_content = "Pero eso es tan caro...",
  ui_story_5031_50311101_162_dialog_content = "¿Hai, hai?",
  ui_story_5031_50311101_163_dialog_content = "¡No no! ¡No me estoy quejando!",
  ui_story_5031_50311101_164_dialog_content = "Te compraré cualquier cosa, siempre y cuando me perdones. Boo-hoo...",
  ui_story_5031_50311101_165_dialog_content = "(Oh, solo mira la expresión de Fia en este momento).",
  ui_story_5031_50311101_166_dialog_content = "(Realmente debería aprovechar esta oportunidad para aprender a trabajar con otros).",
  ui_story_5031_50311101_167_dialog_content = "¡Hola!",
  ui_story_5031_50311101_168_dialog_content = "(Bica parece feliz. ¿Aceptó Bica las disculpas de Fia?)",
  ui_story_5031_50311101_169_dialog_content = "¿Me perdonas? ¡Eso es maravilloso!",
  ui_story_5031_50311101_170_dialog_content = "Luego sobre la actuación...",
  ui_story_5031_50311101_171_dialog_content = "¡Hiya!",
  ui_story_5031_50311101_172_dialog_content = "¿Ah?",
  ui_story_5031_50311101_173_dialog_content = "Fia, ¿qué dijo Bica?",
  ui_story_5031_50311101_174_dialog_content = "Decía... \"Eso depende de ti\".",
  ui_story_5031_50311101_175_dialog_content = "¿Es tan vago?",
  ui_story_5031_50311101_176_dialog_content = "¿Va a estar bien? ¿No deberías preguntarle a Bica una vez más, solo para estar seguro?",
  ui_story_5031_50311101_177_dialog_content = "Quiero decir, el resultado de la batalla final depende de esto...",
  ui_story_5031_50311101_178_dialog_content = "Pero yo...",
  ui_story_5031_50311101_179_dialog_content = "¡La batalla final está sobre nosotros! Concursantes, ¡es hora!",
  ui_story_5031_50311101_180_dialog_content = "¡¿Ya?!",
  ui_story_5031_50311101_181_dialog_content = "¿Ha pasado una hora? No hay otra opción...",
  ui_story_5031_50311101_182_dialog_content = "¡Tenemos que hacerlo!",
  ui_story_5031_50311101_183_dialog_content = "¡Déjamelo a mí!",
  ui_story_5031_50311101_184_dialog_content = "Intentaré ganar tantos puntos como pueda.",
  ui_story_5031_50311101_185_dialog_content = "¡Bica y yo también haremos nuestro mejor esfuerzo!",
  ui_story_5031_50311101_186_dialog_content = "¡Hiya!",
  ui_story_5031_50311201_1_dialog_content = "Al caer la noche, ¡la tercera ronda de la competencia está a punto de comenzar!",
  ui_story_5031_50311201_2_dialog_content = "¡¡¡Guau!!!",
  ui_story_5031_50311201_3_dialog_content = "Según los resultados de las rondas anteriores, ¡dos equipos se enfrentarán en el escenario!",
  ui_story_5031_50311201_4_dialog_content = "Ellos son... ¡el equipo líder de Illumina!",
  ui_story_5031_50311201_5_dialog_content = "¡Y un equipo en ascenso liderado por la extrozoóloga novata Fia!",
  ui_story_5031_50311201_6_dialog_content = "¡Ohhhhhh!",
  ui_story_5031_50311201_7_dialog_content = "Esa es una cálida bienvenida de la audiencia. ¡Excelente!",
  ui_story_5031_50311201_8_dialog_content = "Ahora, antes de que comience oficialmente el juego, disfrutemos de la actuación de apertura del maestro de ceremonias: ¡Jeno y las tres hermanas!",
  ui_story_5031_50311201_9_dialog_content = "¡Primero, el maestro de ceremonias Jeno!",
  ui_story_5031_50311201_10_dialog_content = "The Foresight Ritual, una habilidad buscada por innumerables aurorianos a lo largo de los siglos.",
  ui_story_5031_50311201_11_dialog_content = "Para comunicarse con existencias mayores, para descifrar fragmentos del pasado o del futuro...",
  ui_story_5031_50311201_12_dialog_content = "Y poder percibir la verdadera historia o asomarse al futuro.",
  ui_story_5031_50311201_13_dialog_content = "Esta noche, demostraré este antiguo poder y responderé a todas sus preguntas.",
  ui_story_5031_50311201_14_dialog_content = "Esta baraja de Origin Card será mi ayuda.",
  ui_story_5031_50311201_15_dialog_content = "¡Vaya! ¡Eso es todo! ¡El legendario Ritual de Previsión!",
  ui_story_5031_50311201_16_dialog_content = "Ser capaz de invocar eclipses y prever el futuro. ¿Qué secretos guarda el poder del Origen?",
  ui_story_5031_50311201_17_dialog_content = "A continuación, debo pedir la ayuda de una audiencia afortunada.",
  ui_story_5031_50311201_18_dialog_content = "¿Quién es el invitado predestinado que se cruzará conmigo?",
  ui_story_5031_50311201_19_dialog_content = "¡¡¡Yo!!!",
  ui_story_5031_50311201_20_dialog_content = "¡Yo! ¡Elígeme!",
  ui_story_5031_50311201_21_dialog_content = "lo siento Lo siento ahora...",
  ui_story_5031_50311201_22_dialog_content = "La carta de origen apunta mi destino hacia... ¡USTED!",
  ui_story_5031_50311201_23_dialog_content = "La señora de la derecha de la primera fila.",
  ui_story_5031_50311201_24_dialog_content = "Yo-Yo?",
  ui_story_5031_50311201_25_dialog_content = "Sí tú. Por favor, ven aquí.",
  ui_story_5031_50311201_26_dialog_content = "Puedes hacerme cualquier pregunta y te responderé usando Origin Card.",
  ui_story_5031_50311201_27_dialog_content = "¿Cualquier cosa?",
  ui_story_5031_50311201_28_dialog_content = "Cualquier cosa.",
  ui_story_5031_50311201_29_dialog_content = "Entonces... ¿Sabes de dónde vengo?",
  ui_story_5031_50311201_30_dialog_content = "¡Oh, Carta del Origen, sé mis ojos y dame la visión de la verdad! ¡Dime de dónde es esta señora!",
  ui_story_5031_50311201_31_dialog_content = "(¡Las cartas bailan entre los dedos de Jeno y luego saca una!)",
  ui_story_5031_50311201_32_dialog_content = "La Tarjeta Origen me ha dado la respuesta. Eres de Petyaburg.",
  ui_story_5031_50311201_33_dialog_content = "¡¿Como supiste?!",
  ui_story_5031_50311201_34_dialog_content = "La Tarjeta de Origen me dio la respuesta. No solo eso, también me dijo algo más—",
  ui_story_5031_50311201_35_dialog_content = "Sois familia de un vizconde, y que familia tan feliz tenéis.",
  ui_story_5031_50311201_36_dialog_content = "Sin embargo, por alguna razón, no estás sentado con tu pareja, pero aún compartes un fuerte vínculo con él.",
  ui_story_5031_50311201_37_dialog_content = "Esto es increíble...",
  ui_story_5031_50311201_38_dialog_content = "Las entradas se vendían como pan caliente y solo pudimos conseguir asientos separados.",
  ui_story_5031_50311201_39_dialog_content = "Y tu pareja insistió en darte el asiento de primera fila.",
  ui_story_5031_50311201_40_dialog_content = "S-Sí...",
  ui_story_5031_50311201_41_dialog_content = "¡The Origin Card les desea una feliz vida juntos! Puede volver a su asiento ahora.",
  ui_story_5031_50311201_42_dialog_content = "¡Dios mio! ¡¡¡Eso es increíble!!!",
  ui_story_5031_50311201_43_dialog_content = "¡Elige otro! ¡Eligeme!",
  ui_story_5031_50311201_44_dialog_content = "El tiempo es fugaz. Incluso la Tarjeta de Origen debe cumplir con las leyes del tiempo.",
  ui_story_5031_50311201_45_dialog_content = "Y por favor disfruta de la siguiente actuación. Espero con ansias el próximo cruce de destinos.",
  ui_story_5031_50311201_46_dialog_content = "¡Qué maravillosa actuación de Ringmaster Jeno!",
  ui_story_5031_50311201_47_dialog_content = "¡Ahora, disfrute del emocionante trapecio de alto vuelo de Merylt, Subli y Frimet!",
  ui_story_5031_50311201_48_dialog_content = "Correcto... ¡Aquí vamos!",
  ui_story_5031_50311201_49_dialog_content = "¡Hagamos que se les caigan las mandíbulas!",
  ui_story_5031_50311201_50_dialog_content = "¡Ok!",
  ui_story_5031_50311201_51_dialog_content = "¡Hagámoslo!",
  ui_story_5031_50311201_52_dialog_content = "(Merylt sube la escalera y extiende su mano hacia los otros dos.)",
  ui_story_5031_50311201_53_dialog_content = "¡Je!",
  ui_story_5031_50311201_54_dialog_content = "¡Frimet, no me sueltes!",
  ui_story_5031_50311201_55_dialog_content = "Subli... Eres tan pesado...",
  ui_story_5031_50311201_56_dialog_content = "(¡Eso estuvo cerca! ¡Afortunadamente, Frimet atrapó a Subli!)",
  ui_story_5031_50311201_57_dialog_content = "¡Yo voy a continuación!",
  ui_story_5031_50311201_58_dialog_content = "(¿Eh? ¿Van a...?)",
  ui_story_5031_50311201_59_dialog_content = "¡Yo!",
  ui_story_5031_50311201_60_dialog_content = "¡Justo ahí!",
  ui_story_5031_50311201_61_dialog_content = "¡Es... aún más pesado ahora!",
  ui_story_5031_50311201_62_dialog_content = "¡Funcionó!",
  ui_story_5031_50311201_63_option_content = "¡Increíble!",
  ui_story_5031_50311201_64_dialog_content = "¡Ohhhhhh! ¡Eso es increíble!",
  ui_story_5031_50311201_65_dialog_content = "G-Gracias a todos!",
  ui_story_5031_50311201_66_dialog_content = "¿Estás impresionado?",
  ui_story_5031_50311201_67_dialog_content = "¡Muy impresionado!",
  ui_story_5031_50311201_68_dialog_content = "No fue más que una simple actuación...",
  ui_story_5031_50311201_69_dialog_content = "¡Pero con gusto aceptamos sus aplausos!",
  ui_story_5031_50311201_70_dialog_content = "¡Esperen con ansias la competencia!",
  ui_story_5031_50311201_71_dialog_content = "¡Le agradecemos su maravillosa actuación!",
  ui_story_5031_50311201_72_dialog_content = "Ahora es el momento de anunciar... La última ronda comienza, ¡AHORA!",
  ui_story_5031_50311201_73_dialog_content = "El primero es el Equipo Illumina. Gronru ¡y Ciel demostrarán sus movimientos especiales!",
  ui_story_5031_50311201_74_dialog_content = "Modifiqué mi mecha según los comentarios de Gronru, solo por este momento...",
  ui_story_5031_50311201_75_dialog_content = "¡Tiene que funcionar, por favor!",
  ui_story_5031_50311201_76_dialog_content = "¡Vaya! ¡Parece que Ciel tiene algo increíble preparado!",
  ui_story_5031_50311201_77_dialog_content = "...",
  ui_story_5031_50311201_78_dialog_content = "¿Eh? fia? ¿Estás bien? ¿Por qué estás temblando?",
  ui_story_5031_50311201_79_dialog_content = "Estoy tan nervioso...",
  ui_story_5031_50311201_80_dialog_content = "¿Estás nerviosa?",
  ui_story_5031_50311201_81_dialog_content = "¡N-De ninguna manera!",
  ui_story_5031_50311201_82_dialog_content = "¡Soy un extrozoólogo!, de ninguna manera soy—¡Ay!",
  ui_story_5031_50311201_83_dialog_content = "¿Estás tan nervioso que te mordiste la lengua?",
  ui_story_5031_50311201_84_dialog_content = "¡No estoy nervioso!",
  ui_story_5031_50311201_85_dialog_content = "Fia, despeja tu mente y respira hondo.",
  ui_story_5031_50311201_86_dialog_content = "*Inhalar*",
  ui_story_5031_50311201_87_dialog_content = "*Exhalar*",
  ui_story_5031_50311201_88_dialog_content = "¿Me siento mejor ahora?",
  ui_story_5031_50311201_89_dialog_content = "Oh no... no mejor. ¡Mi corazón esta palpitando!",
  ui_story_5031_50311201_90_dialog_content = "Ciel y Gronru se ve increible pero no se si Bica va a ayudar...",
  ui_story_5031_50311201_91_dialog_content = "¡No hay forma de que ganemos!",
  ui_story_5031_50311201_92_dialog_content = "No entrar en pánico. No sirve de nada pensar eso ahora.",
  ui_story_5031_50311201_93_dialog_content = "Solo concéntrate en lo que tienes que hacer. Solo concéntrate en la actuación en sí.",
  ui_story_5031_50311201_94_dialog_content = "Pero, ¿y si Bica sigue sin colaborar?",
  ui_story_5031_50311201_95_dialog_content = "Bueno...",
  ui_story_5031_50311201_96_option_content = "¿Alguna vez has escuchado un dicho?",
  ui_story_5031_50311201_97_dialog_content = "¿Qué dicho?",
  ui_story_5031_50311201_98_dialog_content = "¡Los cumplidos pueden hacer magia!",
  ui_story_5031_50311201_99_dialog_content = "¡¿Qué?!",
  ui_story_5031_50311201_100_dialog_content = "Más o menos lo que quise decir. De todos modos, trata de hacer feliz a Bica para que te ayude.",
  ui_story_5031_50311201_101_dialog_content = "Todo lo que importa es conseguir el gran premio, sea o no la Ballena Nube. ¡Todas las demás preocupaciones son secundarias!",
  ui_story_5031_50311201_102_dialog_content = "¡Lo intentaré!",
  ui_story_5031_50311201_103_dialog_content = "Buena suerte. Vice, Carleen, y haré todo lo posible para ganar puntos.",
  ui_story_5031_50311201_104_dialog_content = "Nuestro puntaje final sería nuestro promedio.",
  ui_story_5031_50311201_105_dialog_content = "Entonces, ¡la mejor manera de ganar esto es que todos hagamos nuestro mejor esfuerzo!",
  ui_story_5031_50311201_106_dialog_content = "Y-ya veo ...",
  ui_story_5031_50311201_107_dialog_content = "¡Mirar! Esa fue una actuación increíble de Gronru y Ciel!",
  ui_story_5031_50311201_108_dialog_content = "¡El mecha de Ciel y el trono de Gronru están bailando bajo una luz deslumbrante!",
  ui_story_5031_50311201_109_dialog_content = "¡El mecha de Ciel parecía sin peso, realizando bailes de combate con habilidades extremas!",
  ui_story_5031_50311201_110_dialog_content = "¡Ella trazó un equilibrio perfecto entre peso y belleza!",
  ui_story_5031_50311201_111_dialog_content = "¡Ahora es el turno del Equipo Fia de subir al escenario!",
  ui_story_5031_50311201_112_dialog_content = "¿Qué actuación extraordinaria tiene reservada para nosotros?",
  ui_story_5031_50311201_113_dialog_content = "Uf... Es hora. ¡Vamos, Bica!",
  ui_story_5031_50311201_114_dialog_content = "¡Hola!",
  ui_story_5031_50311201_115_dialog_content = "(¡Buena suerte, Fia, Bica!)",
  ui_story_5031_50311201_116_dialog_content = "(Por favor, no dejes que nada salga mal esta vez...)",
  ui_story_5031_50311201_117_dialog_content = "¡Bien! ¡Hagámoslo! ¡Bica, ven aquí!",
  ui_story_5031_50311201_118_dialog_content = "¡Hola!",
  ui_story_5031_50311201_119_dialog_content = "Como te dije, Bica. Salta y haz un salto mortal, ¿de acuerdo?",
  ui_story_5031_50311201_120_dialog_content = "¿Hai, hai?",
  ui_story_5031_50311201_121_dialog_content = "(¡¿Bica está mirando a Fia con una sonrisa traviesa?!)",
  ui_story_5031_50311201_122_dialog_content = "¡Por favor... por favor colabore!",
  ui_story_5031_50311201_123_dialog_content = "¿Hola?",
  ui_story_5031_50311201_124_dialog_content = "(¿Bica se está haciendo la tonta?)",
  ui_story_5031_50311201_125_dialog_content = "¿Qué está pasando?",
  ui_story_5031_50311201_126_dialog_content = "¡No gastamos el dinero para verte perder el tiempo!",
  ui_story_5031_50311201_127_dialog_content = "*lloriqueo*",
  ui_story_5031_50311201_128_dialog_content = "¡P-Por favor!",
  ui_story_5031_50311201_129_dialog_content = "¡Hola!",
  ui_story_5031_50311201_129X1_dialog_content = "Bica es lo mejor! ¡Debe ser fácil para ti encargarte de un caso tan pequeño!",
  ui_story_5031_50311201_130_dialog_content = "¡Te compraré las uvas del Sr. Peng justo después de esto!",
  ui_story_5031_50311201_131_dialog_content = "¡Hiya!",
  ui_story_5031_50311201_132_dialog_content = "¡¿Eso funciono?!",
  ui_story_5031_50311201_133_dialog_content = "¡Hola!",
  ui_story_5031_50311201_134_dialog_content = "Yo-ho! ¡Haz otro!",
  ui_story_5031_50311201_135_dialog_content = "Ahora, lanzaré esta pelota. ¡Por favor, tómalo!",
  ui_story_5031_50311201_136_dialog_content = "¡Hiya!",
  ui_story_5031_50311201_137_dialog_content = "¡Hola!",
  ui_story_5031_50311201_138_dialog_content = "¡Bien hecho!",
  ui_story_5031_50311201_139_dialog_content = "(¡Genial, Bica está dispuesta a ayudarme a cambio de las uvas!)",
  ui_story_5031_50311201_140_dialog_content = "¿Hola?",
  ui_story_5031_50311201_141_dialog_content = "¡Hey, espera! ¡Eso no es comida!",
  ui_story_5031_50311201_142_dialog_content = "¡Jajajajaja!",
  ui_story_5031_50311201_143_dialog_content = "(Eso estuvo cerca. Al menos la audiencia pensó que era parte de la actuación).",
  ui_story_5031_50311201_144_dialog_content = "¡Ahora, mostrémosle al público tu truco secreto, Bica!",
  ui_story_5031_50311201_145_dialog_content = "truco secreto? ¿Qué truco secreto?",
  ui_story_5031_50311201_146_dialog_content = "¿Vas a hacer que Bica se trague una roca como la última vez con el cazador?",
  ui_story_5031_50311201_147_dialog_content = "¡Eso es peligroso!",
  ui_story_5031_50311201_148_dialog_content = "¡No voy a hacer nada de eso!",
  ui_story_5031_50311201_149_dialog_content = "¡He preparado esto!",
  ui_story_5031_50311201_150_dialog_content = "¡Mira!",
  ui_story_5031_50311201_151_dialog_content = "Burbujas?",
  ui_story_5031_50311201_152_dialog_content = "¡Vaya! ¡Tantas burbujas hermosas!",
  ui_story_5031_50311201_153_dialog_content = "Pero, ¿qué tiene eso que ver con la domesticación de una bestia?",
  ui_story_5031_50311201_154_dialog_content = "¡Ahora le toca a Bica!",
  ui_story_5031_50311201_155_dialog_content = "¡Hiya!",
  ui_story_5031_50311201_156_dialog_content = "¡Hola!",
  ui_story_5031_50311201_157_dialog_content = "(¡Cierto! Las burbujas son todas esferas. ¡Justo lo que le gusta a Bica!)",
  ui_story_5031_50311201_158_dialog_content = "¡Oooh! ¡¿Ese pequeño tiene incluso ese talento?!",
  ui_story_5031_50311201_159_dialog_content = "¡Hola!",
  ui_story_5031_50311201_160_dialog_content = "¡H-Hai!",
  ui_story_5031_50311201_161_dialog_content = "*Eructo*",
  ui_story_5031_50311201_162_dialog_content = "(¡Bica tragó demasiado aire y su cuerpo se hinchó!)",
  ui_story_5031_50311201_163_dialog_content = "Jajajajaja! ¡Eso es tan adorable!",
  ui_story_5031_50311201_164_dialog_content = "¡Eso es todo por nuestra actuación!",
  ui_story_5031_50311201_165_dialog_content = "¡Esperen con ansias lo que mis compañeros de equipo prepararán para ustedes a continuación!",
  ui_story_5031_50311201_166_dialog_content = "¡¡¡Guau!!!",
  ui_story_5031_50311201_167_dialog_content = "Después de que terminó la actuación de Fia, yo, Vice, y Carleen también subieron al escenario en ese orden.",
  ui_story_5031_50311201_168_dialog_content = "Usé mis habilidades psíquicas para leer la mente.",
  ui_story_5031_50311201_169_dialog_content = "Vice demostró su impresionante puntería...",
  ui_story_5031_50311201_170_dialog_content = "Y solo puedo esperar que ella no ponga la manzana objetivo en la parte superior de mi cabeza, la próxima vez...",
  ui_story_5031_50311201_171_dialog_content = "Carleen era el cisne negro. Sorprendió a todos con su ballet.",
  ui_story_5031_50311201_172_dialog_content = "Es más... ¡Incluso le pidió a Jeno que pusiera Eclipsites en el escenario como parte de su espectáculo!",
  ui_story_5031_50311202_1_dialog_content = "¡Flor de hielo!",
  ui_story_5031_50311202_2_dialog_content = "Te apuesto Carleen ¡Es el único que combinó ballet y combate!",
  ui_story_5031_50311202_3_dialog_content = "¡Qué es INCREÍBLE!",
  ui_story_5031_50311202_4_dialog_content = "¡Un gran aplauso para el ballet de Carleen! ¡Eso fue a la vez emocionante y espectacular!",
  ui_story_5031_50311202_5_dialog_content = "Ahora, el momento que todos están esperando...",
  ui_story_5031_50311202_6_dialog_content = "¡Es hora de los resultados!",
  ui_story_5031_50311202_7_dialog_content = "¡Hola!",
  ui_story_5031_50311202_8_dialog_content = "Estoy tan nerviosa... No puedo... respirar...",
  ui_story_5031_50311202_9_dialog_content = "¡Espera, Fía!",
  ui_story_5031_50311202_10_dialog_content = "¡Piensa en tu Ballena Nube!",
  ui_story_5031_50311202_11_dialog_content = "Cloudwhale, sí, mi Cloudwhale... ¡Mi gran premio!",
  ui_story_5031_50311202_12_dialog_content = "El ganador de este concurso es...",
  ui_story_5031_50311202_13_dialog_content = "¡Equipo Fía!",
  ui_story_5031_50311202_14_dialog_content = "¿Yo gané...?",
  ui_story_5031_50311202_15_dialog_content = "¡Oh sí! ¡Gané!",
  ui_story_5031_50311202_16_dialog_content = "¡Hola!",
  ui_story_5031_50311202_17_dialog_content = "A pesar del desempeño menos que perfecto de Fia, el trabajo en equipo entre ellos es realmente impresionante.",
  ui_story_5031_50311202_18_dialog_content = "Y el ballet de Miss Carleen fue simplemente estelar.",
  ui_story_5031_50311202_19_dialog_content = "¡Entonces, el puntaje promedio del Equipo Fia es lo suficientemente alto como para ganarles el primer lugar!",
  ui_story_5031_50311202_20_dialog_content = "¡Felicidades, Fía!",
  ui_story_5031_50311202_21_dialog_content = "¡Nunca supe que una niña como tú podría ser tan increíble, Fia!",
  ui_story_5031_50311202_22_dialog_content = "¡Me has derrotado, pero no voy a perder contigo la próxima vez!",
  ui_story_5031_50311202_23_dialog_content = "¡Felicidades, Fía! ¡Terminas la actuación y obtienes una victoria!",
  ui_story_5031_50311202_24_dialog_content = "Pero tengo mucha curiosidad. ¿Qué es exactamente el gran premio?",
  ui_story_5031_50311202_25_dialog_content = "¿Podría ser realmente la ballena nubosa que Fia ha estado buscando?",
  ui_story_5031_50311202_26_dialog_content = "¡Derecha! ¡Mi gran premio, el único tesoro de las profundidades del mar!",
  ui_story_5031_50311202_27_dialog_content = "Por supuesto. Tengo el premio conmigo.",
  ui_story_5031_50311202_28_dialog_content = "Aquí tienes.",
  ui_story_5031_50311202_29_dialog_content = "¡Lo! ¡Lo, lo, lo!",
  ui_story_5031_50311202_30_dialog_content = "¡¿Qué?! N-No es esto... ¡¿KYLLO?!",
  ui_story_5031_50311202_31_dialog_content = "¿No te envié al mar para rastrear a la Ballena Nube?",
  ui_story_5031_50311202_32_dialog_content = "¡Con razón nunca volví a saber de ti! ¡Has estado holgazaneando todo este tiempo!",
  ui_story_5031_50311202_33_dialog_content = "Capturé este animal del mar no hace mucho.",
  ui_story_5031_50311202_34_dialog_content = "Se ve delicioso, así que planeo convertirlo en una sopa de mariscos para el ganador.",
  ui_story_5031_50311202_35_dialog_content = "¿Lo, lo, lo? ¡Lo!",
  ui_story_5031_50311202_36_dialog_content = "¡No puedes cocinar a Kyllo!",
  ui_story_5031_50311202_37_dialog_content = "¡Es mi amigo!",
  ui_story_5031_50311202_38_dialog_content = "¿Un amigo? Y pensé que era algún ingrediente alimenticio raro y delicioso.",
  ui_story_5031_50311202_39_dialog_content = "Bueno, tú eres el ganador, y es tu premio. Lo dejo en tus manos.",
  ui_story_5031_50311202_40_dialog_content = "Lo, lo...",
  ui_story_5031_50311202_41_dialog_content = "¡Uf, pequeña cosa descuidada! ¿Sabes que casi mueres?",
  ui_story_5031_50311202_42_dialog_content = "Lo... ¡Lo, lo!",
  ui_story_5031_50311202_43_dialog_content = "¿Eh? ¿Dijiste que te atraparon en una red mientras buscabas a la Ballena Nube bajo el mar?",
  ui_story_5031_50311202_44_dialog_content = "¿Y te encerraron en el barco durante días?",
  ui_story_5031_50311202_45_dialog_content = "Entonces... ¿Viste la Ballena Nube en el barco?",
  ui_story_5031_50311202_46_dialog_content = "Lo? ¡Lo, lo!",
  ui_story_5031_50311202_47_dialog_content = "¿No? Qué triste...",
  ui_story_5031_50311202_48_dialog_content = "Ahora que se ha anunciado el ganador, ¿podrían subir todos a la terraza?",
  ui_story_5031_50311202_49_dialog_content = "El banquete y los fuegos artificiales están a punto de comenzar.",
  ui_story_5031_50311202_50_dialog_content = "¿Dijiste fuegos artificiales? ¡Démonos prisa y consigamos un buen lugar!",
  ui_story_5031_50311202_51_dialog_content = "No Cloudwhale... ¡¿Cómo es que el gran premio no es Cloudwhale?!",
  ui_story_5031_50311202_52_dialog_content = "¡Todo ese trabajo para nada!",
  ui_story_5031_50311202_53_dialog_content = "¿Cómo puede ser eso una ballena?",
  ui_story_5031_50311202_54_dialog_content = "La Esmeralda no podrá manejarlo, incluso si solo estamos hablando de cría de ballena.",
  ui_story_5031_50311202_55_dialog_content = "¿Tengo razón al suponer que nunca ha visto una ballena, jovencita?",
  ui_story_5031_50311202_56_dialog_content = "¡¿Y qué si nunca he visto uno?!",
  ui_story_5031_50311202_57_dialog_content = "Es un exótico. Es normal que no haya visto uno antes...",
  ui_story_5031_50311202_58_dialog_content = "No...",
  ui_story_5031_50311202_59_dialog_content = "¡No es gracioso! ¡Parar de reír!",
  ui_story_5031_50311202_60_dialog_content = "Bien bien. No fue todo por nada, ya sabes.",
  ui_story_5031_50311202_61_option_content = "Ganamos el concurso",
  ui_story_5031_50311202_62_dialog_content = "Fia y Bica ahora también son amigas, ¿no es así?",
  ui_story_5031_50311202_63_dialog_content = "¡Hola!",
  ui_story_5031_50311202_64_dialog_content = "¡A-Está bien! ¡Te voy a comprar uvas!",
  ui_story_5031_50311202_65_option_content = "Al menos salvaste a Kyllo.",
  ui_story_5031_50311202_66_dialog_content = "¡Lo, lo!",
  ui_story_5031_50311202_67_dialog_content = "Por desgracia... Simplemente no esperaba que el gran premio fuera Kyllo.",
  ui_story_5031_50311202_68_dialog_content = "Ya que te capturaron por accidente, será mejor que vuelvas a buscar la Ballena Nube.",
  ui_story_5031_50311202_69_dialog_content = "Lo?",
  ui_story_5031_50311202_70_dialog_content = "No necesito tu ayuda aquí. Está bien, está bien, ¡adelante!",
  ui_story_5031_50311202_71_dialog_content = "¡Déjame darte una mano y lanzarte al mar, entonces!",
  ui_story_5031_50311202_72_dialog_content = "Lo-!",
  ui_story_5031_50311202_73_dialog_content = "(Kyllo se convierte en una estrella fugaz que atraviesa el cielo... ¡Fia es tan aterradora!)",
  ui_story_5031_50311202_74_dialog_content = "Hmm... ¿Eres realmente un extrozoólogo?",
  ui_story_5031_50311202_75_dialog_content = "¡Claro que lo soy!",
  ui_story_5031_50311202_76_dialog_content = "Pero, ¿cómo funcionó tu adivinación, Jeno?",
  ui_story_5031_50311202_77_dialog_content = "¿Eres también un Caelestite que posee habilidades psíquicas?",
  ui_story_5031_50311202_78_dialog_content = "Eso no era adivinación en absoluto, no realmente. Eran todas mis habilidades de observación.",
  ui_story_5031_50311202_79_dialog_content = "¿Recuerdas a esa señora? Su vestido puede parecer nada fuera de lo común a simple vista, pero la tela es específica de Petyaburg.",
  ui_story_5031_50311202_80_dialog_content = "En cuanto a su vida amorosa... el anillo en su dedo me dijo que está casada.",
  ui_story_5031_50311202_81_dialog_content = "Y, la forma en que seguía mirando hacia atrás significaba que probablemente no estaba sentada con su pareja.",
  ui_story_5031_50311202_82_dialog_content = "Acabo de poner todo junto y...",
  ui_story_5031_50311202_83_dialog_content = "Siento entrometerme, Jeno, pero hay algo de lo que necesito hablar contigo, en privado, junto al escenario.",
  ui_story_5031_50311202_84_dialog_content = "Seguro.",
  ui_story_5031_50311202_85_dialog_content = "Lo siento, todos. Volveré enseguida.",
  ui_story_5031_50311202_86_dialog_content = "¡Oye! ¡Al menos termina tu frase!",
  ui_story_5031_50311202_87_dialog_content = "Caray, acaba de abandonar una conversación como esa.",
  ui_story_5031_50311202_88_dialog_content = "¡Los fuegos artificiales han comenzado!",
  ui_story_5031_50311202_89_dialog_content = "Eso es realmente hermoso.",
  ui_story_5031_50311202_90_dialog_content = "¡Así que ahí estás!",
  ui_story_5031_50311202_91_dialog_content = "E-Todos están aquí...",
  ui_story_5031_50311202_92_dialog_content = "Rainbow, ¿qué pasa con ese tazón de comida en tu regazo? ¿Lo llevarás para comer?",
  ui_story_5031_50311202_93_dialog_content = "¿No te unirás a nosotros?",
  ui_story_5031_50311202_94_dialog_content = "¡Tengo otros planes!",
  ui_story_5031_50311202_95_dialog_content = "Claro, los fuegos artificiales son hermosos, ¡pero a Ciel y a mí se nos ocurrió una gran idea sobre cómo modificar nuestro mecha!",
  ui_story_5031_50311202_96_dialog_content = "¡No podemos esperar a empezar a trabajar en ello!",
  ui_story_5031_50311202_97_dialog_content = "Sí...",
  ui_story_5031_50311202_98_dialog_content = "Lamento que no podamos pasar tiempo contigo esta noche.",
  ui_story_5031_50311202_99_dialog_content = "Ah, no te preocupes por eso. ¡Tenemos mucho tiempo en el futuro!",
  ui_story_5031_50311202_100_dialog_content = "¡Nos vamos entonces!",
  ui_story_5031_50311202_101_dialog_content = "Parecen muy cercanos. Tengo un poco de envidia de ellos.",
  ui_story_5031_50311202_102_dialog_content = "¿Te estás perdiendo algo? Carleen?",
  ui_story_5031_50311202_103_dialog_content = "¡Me tienes a mí y a PlayerName!",
  ui_story_5031_50311202_104_dialog_content = "¡Sí, hemos estado viajando y permaneciendo juntos en todo este tiempo!",
  ui_story_5031_50311202_105_dialog_content = "Exactamente. ¡Como esta vez!",
  ui_story_5031_50311202_106_dialog_content = "¡Habríamos perdido si no fuera por tu extraordinario ballet que nos hizo ganar tantos puntos!",
  ui_story_5031_50311202_107_dialog_content = "¡Así es! ¡Todo es gracias a ti!",
  ui_story_5031_50311202_108_dialog_content = "¡Así que no empieces a actuar como un extraño, tú!",
  ui_story_5031_50311202_109_dialog_content = "Es eso así...? Bien, bien.",
  ui_story_5031_50311202_110_dialog_content = "Gracias.",
  ui_story_5031_50311202_111_dialog_content = "¡Sí!",
  ui_story_5031_50311301_1_dialog_content = "No lo noté antes durante el día, pero si miras de cerca, Harbor City realmente se ve encantador por la noche bajo los fuegos artificiales.",
  ui_story_5031_50311301_2_dialog_content = "Sí. Sus edificios blancos quedaron pintados por los radiantes fuegos artificiales. ¡Es aún más encantador que durante el día!",
  ui_story_5031_50311301_3_dialog_content = "PlayerName, Vicey Fía. Quiero ir a hablar con Elvis.",
  ui_story_5031_50311301_4_dialog_content = "¿Podrías esperarme un rato?",
  ui_story_5031_50311301_5_dialog_content = "¡Cosa segura! Estaremos justo aquí.",
  ui_story_5031_50311301_6_dialog_content = "Está bien. Gracias.",
  ui_story_5031_50311301_7_dialog_content = "Parece que finalmente ha terminado...",
  ui_story_5031_50311301_8_dialog_content = "Pero aún no he encontrado mi Ballena Nube...",
  ui_story_5031_50311301_9_dialog_content = "Ahora, ¿dónde podría estar la legendaria Ballena Nube...?",
  ui_story_5031_50311301_10_dialog_content = "No se apresure. Algunas cosas que simplemente no puedes conseguir a toda prisa.",
  ui_story_5031_50311301_11_dialog_content = "Así es. A veces, cuanto más tenía prisa por encontrar mis horquillas después de despertarme, más difícil me resultaba encontrarlas.",
  ui_story_5031_50311301_12_dialog_content = "Pero cuando finalmente me rendí, ¡me daría cuenta de que ha estado a mi lado todo el tiempo!",
  ui_story_5031_50311301_13_dialog_content = "¿En serio?",
  ui_story_5031_50311301_14_dialog_content = "Por supuesto.",
  ui_story_5031_50311301_15_dialog_content = "Está bien, confiaré en ti esta vez.",
  ui_story_5031_50311301_16_dialog_content = "Hola a todos.",
  ui_story_5031_50311301_17_dialog_content = "Carleen? ¿Tuviste una charla rápida?",
  ui_story_5031_50311301_18_dialog_content = "No, en absoluto. No pude encontrar a Elvis en ninguna parte.",
  ui_story_5031_50311301_19_dialog_content = "¿No arrastró a Jeno a charlar por el escenario?",
  ui_story_5031_50311301_20_dialog_content = "Pasé por ahí pero no los vi.",
  ui_story_5031_50311301_21_dialog_content = "Elvis y Jeno...",
  ui_story_5031_50311301_22_dialog_content = "¿Podrían estar dirigiéndose a la cabaña?",
  ui_story_5031_50311301_23_dialog_content = "¿Cabina? Jeno nunca dejó que nadie se le acercara, ¿verdad?",
  ui_story_5031_50311301_24_dialog_content = "Pero si no están en ningún otro lugar, probablemente sea allí donde estén.",
  ui_story_5031_50311301_25_dialog_content = "Vamos a comprobar. Debería haber gente que sepa adónde fueron.",
  ui_story_5031_50311301_26_dialog_content = "¿Cómo sabes bien el camino a la cabaña, PlayerName?",
  ui_story_5031_50311301_27_dialog_content = "Porque Fia y yo una vez fuimos perseguidos por Elvis y Patou aquí mismo durante mucho tiempo.",
  ui_story_5031_50311301_28_dialog_content = "¿Elvis y Patou? ¿Cómo pasó eso?",
  ui_story_5031_50311301_29_dialog_content = "Para resumir, nosotros...",
  ui_story_5031_50311301_30_dialog_content = "¡Mira, PlayerName, hay alguien en el suelo!",
  ui_story_5031_50311301_31_dialog_content = "¿Ese es... Jeno?",
  ui_story_5031_50311301_32_dialog_content = "¿En serio? ¿Me harías un dibujo?",
  ui_story_5031_50311301_33_dialog_content = "Sí, pero dibujo lento y no muy bien, tampoco.",
  ui_story_5031_50311301_34_dialog_content = "Está bien. Tus dibujos son los mejores para mi!",
  ui_story_5031_50311301_35_dialog_content = "Bueno... supongo que te veré mañana por la mañana en el puerto.",
  ui_story_5031_50311301_36_dialog_content = "Dibújalo para mí después de tu trabajo en la playa, ¡y te haré una sopa de mariscos!",
  ui_story_5031_50311301_37_dialog_content = "¡Guau, sopa de mariscos de Elvis!",
  ui_story_5031_50311301_38_dialog_content = "¡Impresionante! ¡Es un trato, entonces!",
  ui_story_5031_50311301_39_dialog_content = "¡Hasta mañana!",
  ui_story_5031_50311301_40_dialog_content = "¡T-nos vemos mañana!",
  ui_story_5031_50311301_41_dialog_content = "...",
  ui_story_5031_50311301_42_dialog_content = "...",
  ui_story_5031_50311301_43_dialog_content = "Teníamos una promesa.",
  ui_story_5031_50311301_44_dialog_content = "Teníamos una promesa...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>Je...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>Jeno...</size>",
  ui_story_5031_50311301_47_dialog_content = "¿Quién está ahí?",
  ui_story_5031_50311301_48_dialog_content = "Jeno!",
  ui_story_5031_50311301_49_dialog_content = "¿Elvis? ¿Eres tu? ¿Has vuelto?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>¡Despierta, Jeno!</size>",
  ui_story_5031_50311301_51_dialog_content = "¡Elvis!",
  ui_story_5031_50311301_52_dialog_content = "¡Ahhhh!",
  ui_story_5031_50311301_53_dialog_content = "¡Ahhhh!",
  ui_story_5031_50311301_54_dialog_content = "¿Por qué gritas, PlayerName? ¡Me asustaste!",
  ui_story_5031_50311301_55_dialog_content = "L-Lo siento, yo también estaba asustado.",
  ui_story_5031_50311301_56_dialog_content = "¿Cómo te sientes, Jeno? ¿Estás herido?",
  ui_story_5031_50311301_57_dialog_content = "¿Qué... qué estoy haciendo aquí?",
  ui_story_5031_50311301_58_dialog_content = "¿No deberíamos estar preguntándote eso?",
  ui_story_5031_50311301_59_dialog_content = "¿Por qué estás durmiendo aquí? Te hemos estado buscando.",
  ui_story_5031_50311301_60_dialog_content = "Uh, Fia, eso claramente no es \"dormir\"...",
  ui_story_5031_50311301_61_dialog_content = "Aquí está la cosa. Los fuegos artificiales y la celebración terminaron, así que queríamos despedirnos de Laird Elvis.",
  ui_story_5031_50311301_62_dialog_content = "Pero no pudimos encontrarlo por ningún lado, así que pensamos que ustedes dos podrían estar en la cabaña.",
  ui_story_5031_50311301_63_dialog_content = "Nos arriesgamos solo para ver que yacías aquí, inconsciente.",
  ui_story_5031_50311301_64_dialog_content = "Bueno, yo... Ay.",
  ui_story_5031_50311301_65_dialog_content = "Aquí nadie nos molestará. ¿Qué quieres decir, Elvis?",
  ui_story_5031_50311301_66_dialog_content = "Yo solo... solo quiero darte las gracias, Jeno.",
  ui_story_5031_50311301_67_dialog_content = "... ¿Eh? Eso salio de la nada.",
  ui_story_5031_50311301_68_dialog_content = "¿Para qué?",
  ui_story_5031_50311301_69_dialog_content = "Gracias por aceptar mi invitación y darle a la gente de Harbor City un recuerdo tan maravilloso.",
  ui_story_5031_50311301_70_dialog_content = "Para mí, tu presencia es... muy significativa.",
  ui_story_5031_50311301_71_dialog_content = "No es gran cosa. Deambulamos por todas partes, por lo que no importa dónde trabajemos.",
  ui_story_5031_50311301_72_dialog_content = "Además, nos pagaste más que suficiente. En ese caso, debemos expresar nuestra gratitud.",
  ui_story_5031_50311301_73_dialog_content = "No, Jeno.",
  ui_story_5031_50311301_74_dialog_content = "Nunca podré pagarte lo que te debo.",
  ui_story_5031_50311301_75_dialog_content = "¿Gratitud hacia mí? De qué hablas-",
  ui_story_5031_50311301_76_dialog_content = "¡Argh!",
  ui_story_5031_50311301_77_dialog_content = "Lo siento.",
  ui_story_5031_50311301_78_dialog_content = "Tos, tos... ¿Qué demonios...?",
  ui_story_5031_50311301_79_dialog_content = "¿Es este...?",
  ui_story_5031_50311301_80_dialog_content = "Jeno... lo siento mucho.",
  ui_story_5031_50311301_81_dialog_content = "¿Quieres decir que el Laird Elvis te drogó?",
  ui_story_5031_50311301_82_dialog_content = "Sí.",
  ui_story_5031_50311301_83_dialog_content = "Espera, ¿Elvis es un tipo malo?",
  ui_story_5031_50311301_84_dialog_content = "No saques conclusiones precipitadas, Fia. Aún no sabemos la verdad.",
  ui_story_5031_50311301_85_dialog_content = "<size=33>Maldiciones, se ha ido...</size>",
  ui_story_5031_50311301_86_dialog_content = "¿Qué pasa, Jeno? Qué estás buscando...",
  ui_story_5031_50311301_87_dialog_content = "¡Guau! ¿Qué esta pasando?",
  ui_story_5031_50311301_88_dialog_content = "El barco... ¿se balancea?",
  ui_story_5031_50311301_89_dialog_content = "... Nunca pensó que se rebajaría a esto.",
  ui_story_5031_50311301_90_dialog_content = "¡Espera, Jeno!",
  ui_story_5031_50311301_91_dialog_content = "Je-Jeno... Huff, puff...",
  ui_story_5031_50311301_92_dialog_content = "¿Te importaría explicar lo que está pasando?",
  ui_story_5031_50311301_93_dialog_content = "...",
  ui_story_5031_50311301_94_dialog_content = "Estoy al final de mi ingenio.",
  ui_story_5031_50311301_95_dialog_content = "Si logra activar esa COSA, necesitaré la ayuda de todos ustedes.",
  ui_story_5031_50311301_96_dialog_content = "¿Esa cosa?",
  ui_story_5031_50311301_97_dialog_content = "Acabo de descubrir que falta la llave de la cámara central de la nave que llevaba conmigo.",
  ui_story_5031_50311301_98_dialog_content = "¿Hay algo importante en esa habitación?",
  ui_story_5031_50311301_99_dialog_content = "los <color=#FFB400>Núcleo de energía</color>.",
  ui_story_5031_50311301_100_dialog_content = "Núcleo de energía?",
  ui_story_5031_50311301_101_dialog_content = "¿Cómo es que todos ustedes parecen saber exactamente qué es eso?",
  ui_story_5031_50311301_102_dialog_content = "El núcleo de energía es una creación de civilizaciones antiguas. Piense en ello como un recurso precioso.",
  ui_story_5031_50311301_103_dialog_content = "Nunca imaginé que habría uno en el barco...",
  ui_story_5031_50311301_104_dialog_content = "Porque este barco originalmente vino de una ruina antigua.",
  ui_story_5031_50311301_105_dialog_content = "Y la COSA a la que me referí es un arma antigua que protege el núcleo de energía...",
  ui_story_5031_50311301_106_dialog_content = "<color=#FFB400>guardián del núcleo</color>.",
  ui_story_5031_50311301_107_dialog_content = "Cuando se activa Core Guardian, atacará cualquier forma de vida que se acerque al núcleo de energía indiscriminadamente.",
  ui_story_5031_50311301_108_dialog_content = "Eso significa que todo el barco está en peligro.",
  ui_story_5031_50311301_109_dialog_content = "Entonces estás diciendo que Laird Elvis se llevó la llave cuando te desmayaste.",
  ui_story_5031_50311301_110_dialog_content = "¿Y ahora ha entrado en la cámara del núcleo, tratando de apoderarse del núcleo de energía?",
  ui_story_5031_50311301_111_dialog_content = "Lo más probable, pero...",
  ui_story_5031_50311301_112_dialog_content = "Jeno!",
  ui_story_5031_50311301_113_dialog_content = "¡Son Rainbow y Ciel!",
  ui_story_5031_50311301_114_dialog_content = "¡Jeno, acabamos de recibir la alerta de que se ha abierto la cámara central!",
  ui_story_5031_50311301_115_dialog_content = "Lo sé. Nos dirigimos allí ahora mismo.",
  ui_story_5031_50311301_116_dialog_content = "En el camino, notamos que los guardias mercenarios también estaban desmayados...",
  ui_story_5031_50311301_117_dialog_content = "¡Cuidado, Rainbow!",
  ui_story_5031_50311301_118_dialog_content = "¡Agh! Eso estuvo cerca. Gracias, Ciel.",
  ui_story_5031_50311301_119_dialog_content = "¿Eh? Estos son... ¿Guardias de Harbor City?",
  ui_story_5031_50311301_120_dialog_content = "¿Están asignados para retrasarnos?",
  ui_story_5031_50311301_121_dialog_content = "...",
  ui_story_5031_50311301_122_dialog_content = "¡Quítate de en medio, siervo necio!",
  ui_story_5031_50311302_1_dialog_content = "¿Cuándo Elvis...",
  ui_story_5031_50311302_2_dialog_content = "¿Desde cuando esta gente ha entrado en la cabaña?",
  ui_story_5031_50311302_3_dialog_content = "¡Puedo sentir que se acerca otro flujo de Lumina!",
  ui_story_5031_50311302_4_dialog_content = "Es mucho más de lo que tenemos aquí ahora...",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5031_50311302_6_dialog_content = "¡Argh! ¡Mi barco!",
  ui_story_5031_50311302_7_dialog_content = "¡¿Qué le está haciendo ese Elvis a mi barco?!",
  ui_story_5031_50311302_8_dialog_content = "No podemos hacer nada más que quedarnos atrapados aquí si esto continúa.",
  ui_story_5031_50311302_9_dialog_content = "Todo el mundo está en un lío...",
  ui_story_5031_50311302_10_dialog_content = "¡Tengo que hacer esto!",
  ui_story_5031_50311302_11_dialog_content = "Actualización del estado del mecanismo del brazo: Tipo III.",
  ui_story_5031_50311302_12_dialog_content = "Actualización del estado del mecanismo de pierna: Tipo III.",
  ui_story_5031_50311302_13_dialog_content = "Aumentar la producción de energía en un 70%.",
  ui_story_5031_50311302_14_dialog_content = "¿Qué?",
  ui_story_5031_50311302_15_dialog_content = "¿Qué estás haciendo, Ciel? ¡Tu mecha aún no está completamente probado!",
  ui_story_5031_50311302_16_dialog_content = "Los mantendré ocupados mientras ustedes van a la cámara central.",
  ui_story_5031_50311302_17_dialog_content = "Pero...",
  ui_story_5031_50311302_18_dialog_content = "¡No te preocupes!",
  ui_story_5031_50311302_19_dialog_content = "Hicimos las calibraciones juntos, ¿recuerdas? ¡Styx estará bien!",
  ui_story_5031_50311302_20_dialog_content = "Ciel tiene razón, Rainbow.",
  ui_story_5031_50311302_21_dialog_content = "No podemos pasar mucho tiempo aquí.",
  ui_story_5031_50311302_22_dialog_content = "Debemos confiar en nuestros compañeros... Déjale esto a Ciel.",
  ui_story_5031_50311302_23_dialog_content = "Carleen...",
  ui_story_5031_50311302_24_dialog_content = "(Carleen ciertamente ha cambiado.)",
  ui_story_5031_50311302_25_dialog_content = "...",
  ui_story_5031_50311302_26_dialog_content = "¡No te diviertas demasiado y destruyas el mecanismo, Ciel!",
  ui_story_5031_50311302_27_dialog_content = "De lo contrario, ¡nunca podrás devolverme el dinero!",
  ui_story_5031_50311302_28_dialog_content = "¡¿Eh?!",
  ui_story_5031_50311302_29_dialog_content = "Está bien, no te preocupes.",
  ui_story_5031_50311302_30_dialog_content = "Tienes esto, Ciel.",
  ui_story_5031_50311302_31_dialog_content = "¡Cuidado, Ciel!",
  ui_story_5031_50311302_32_dialog_content = "No queremos meternos con una chica. Será mejor que te vayas ahora.",
  ui_story_5031_50311302_33_dialog_content = "Soy más que suficiente para enfrentaros a todos vosotros.",
  ui_story_5031_50311302_34_dialog_content = "Bueno, si así es como lo quieres.",
  ui_story_5031_50311302_35_dialog_content = "Hmm, son más duros y tienen más gente.",
  ui_story_5031_50311302_36_dialog_content = "En ese caso, tendré que...",
  ui_story_5031_50311302_37_dialog_content = "Aumentar la producción de energía en un 80%.",
  ui_story_5031_50311302_38_dialog_content = "Dios... ¿Su potencia de fuego mejoró de nuevo?",
  ui_story_5031_50311302_39_dialog_content = "Este mecha es como un monstruo.",
  ui_story_5031_50311302_40_dialog_content = "Pero por el laird, no caeremos.",
  ui_story_5031_50311302_41_dialog_content = "¡Escuadrón 1! ¡Mantén tu formación y presiona con tus escudos Lumina!",
  ui_story_5031_50311302_42_dialog_content = "¡Ha terminado si está fuera de ese mecha!",
  ui_story_5031_50311302_43_dialog_content = "¡Sí señor!",
  ui_story_5031_50311302_44_dialog_content = "¿Sus escudos se volvieron más duraderos cuando se apilaron en uno?",
  ui_story_5031_50311302_45_dialog_content = "¡Prepárate para las armas Lumina, Squad 2!",
  ui_story_5031_50311302_46_dialog_content = "Oh, no, si no puedo romper este escudo y dejar que se acerquen...",
  ui_story_5031_50311302_47_dialog_content = "Está bien, tengo que calmarme, respirar...",
  ui_story_5031_50311302_48_dialog_content = "Puede ser más difícil, pero Lumina es la clave si funciona con energía.",
  ui_story_5031_50311302_49_dialog_content = "Así que solo tengo que lanzar más Lumina de lo que hace.",
  ui_story_5031_50311302_50_dialog_content = "Pero Styx ya cayó una vez hoy...",
  ui_story_5031_50311302_51_dialog_content = "Si aumento la producción, Styx podría...",
  ui_story_5031_50311302_52_dialog_content = "Me decidí. ¡Ayudaré mucho a la gente después de construir un mecha dinámico!",
  ui_story_5031_50311302_53_dialog_content = "¿Vaya? Entonces, ¿qué es lo que más quieres hacer con eso, Ciel?",
  ui_story_5031_50311302_54_dialog_content = "Bueno, Yo pienso...",
  ui_story_5031_50311302_55_dialog_content = "Yo creo.",
  ui_story_5031_50311302_56_dialog_content = "¡Ayudaré y protegeré a mis amigos y seré confiable!",
  ui_story_5031_50311302_57_dialog_content = "Lo siento, Rainbow. ¡Lo siento, Styx!",
  ui_story_5031_50311302_58_dialog_content = "<size=45>¡Aumenta la producción de energía en un 100%!</size>",
  ui_story_5031_50311302_59_dialog_content = "¿Qué? ¡El escudo está roto! Pero cómo...",
  ui_story_5031_50311302_60_dialog_content = "¡Tiene que ser un monstruo!",
  ui_story_5031_50311302_61_dialog_content = "Buf... buf...",
  ui_story_5031_50311302_62_dialog_content = "Parece que eso fue bastante exagerado...",
  ui_story_5031_50311302_63_dialog_content = "No solo los circuitos de las piernas están chisporroteando, sino que el Lumina también...",
  ui_story_5031_50311302_64_dialog_content = "¡No te arrepientas!",
  ui_story_5031_50311302_65_dialog_content = "No importa si el escudo se ha ido. ¡Ella solo tiene tanta energía!",
  ui_story_5031_50311302_66_dialog_content = "¿Podemos dejar que una chica nos detenga a todos?",
  ui_story_5031_50311302_67_dialog_content = "... ¡Sí, señor!",
  ui_story_5031_50311302_68_dialog_content = "Huff... no te dejaré pasar...",
  ui_story_5031_50311302_69_dialog_content = "Su ofensiva está disminuyendo. ¡Ahora es el tiempo!",
  ui_story_5031_50311302_70_dialog_content = "Todavía no puedes ganar a pesar de tu superioridad numérica. ¿Seguro que eres el mejor de Harbor City?",
  ui_story_5031_50311302_71_dialog_content = "Eso suena como...",
  ui_story_5031_50311302_72_dialog_content = "¡Ah!",
  ui_story_5031_50311302_73_dialog_content = "¡E-Es él!",
  ui_story_5031_50311302_74_dialog_content = "Uf, ¿no te dije que no te divirtieras demasiado?",
  ui_story_5031_50311302_75_dialog_content = "¡Styx se ve peor por el desgaste! ¡Dios, acabo de perder toda una tarde arreglándolo!",
  ui_story_5031_50311302_76_dialog_content = "¡Eres tú, Rainbow! ¿Por qué estás de vuelta?",
  ui_story_5031_50311302_77_dialog_content = "Porque estoy preocupado por ti.",
  ui_story_5031_50311302_78_dialog_content = "Pero, ¿qué pasa con la cámara central?",
  ui_story_5031_50311302_79_dialog_content = "Jeno y los chicos están en eso.",
  ui_story_5031_50311302_80_dialog_content = "Tut, ¿cómo te atreves a atacarme furtivamente?",
  ui_story_5031_50311302_81_dialog_content = "¡Uh!",
  ui_story_5031_50311302_82_dialog_content = "...",
  ui_story_5031_50311302_83_dialog_content = "¿Mmm? ¿Qué pasa, Ciel? ¿Por qué te ves así?",
  ui_story_5031_50311302_84_dialog_content = "... Eso tiene sentido.",
  ui_story_5031_50311302_85_dialog_content = "Alguien que se avergüenza como yo no tiene derecho a hablar de confianza y confiabilidad.",
  ui_story_5031_50311302_86_dialog_content = "Si no volviste a mí, probablemente...",
  ui_story_5031_50311302_87_dialog_content = "...",
  ui_story_5031_50311302_88_dialog_content = "Eres un poco tonto a veces, Ciel.",
  ui_story_5031_50311302_89_dialog_content = "¿Qué?",
  ui_story_5031_50311302_90_dialog_content = "¡Pero me gusta el tonto que eres!",
  ui_story_5031_50311302_91_dialog_content = "Confío en ti, y por eso sé que te esforzarías al 100% en cubrirnos.",
  ui_story_5031_50311302_92_dialog_content = "Pero nadie sabe en qué condición se encuentra Styx mejor que nosotros. Soy consciente de cómo terminaría, y aquí voy.",
  ui_story_5031_50311302_93_dialog_content = "...",
  ui_story_5031_50311302_94_dialog_content = "También confío en Jeno, y creo que defenderán la Esmeralda.",
  ui_story_5031_50311302_95_dialog_content = "Así que tranquilo.",
  ui_story_5031_50311302_96_dialog_content = "Cuando todo termine, arreglaré Styx contigo.",
  ui_story_5031_50311302_97_dialog_content = "¡Lo haremos inteligente, robusto y no se averiará ni siquiera al 300 % de su producción!",
  ui_story_5031_50311302_98_dialog_content = "...Okey.",
  ui_story_5031_50311302_99_dialog_content = "Pero primero tenemos que deshacernos de estas molestias.",
  ui_story_5031_50311302_100_dialog_content = "Vamos. Lanzan ataques furtivos incluso cuando nos superan ampliamente en número.",
  ui_story_5031_50311302_101_dialog_content = "¿No tienes vergüenza?",
  ui_story_5031_50311302_102_dialog_content = "...",
  ui_story_5031_50311401_1_dialog_content = "*Tose*",
  ui_story_5031_50311401_2_dialog_content = "Bueno, todo listo para ir ahora.",
  ui_story_5031_50311401_3_dialog_content = "Solo esperando que la última pieza caiga en su lugar.",
  ui_story_5031_50311401_4_dialog_content = "Pasos acercándose, señor.",
  ui_story_5031_50311401_5_dialog_content = "Está bien, que vengan. Debes abandonar el barco de acuerdo con el plan y evitar que alguien más se acerque.",
  ui_story_5031_50311401_6_dialog_content = "...",
  ui_story_5031_50311401_7_dialog_content = "¿Qué pasa?",
  ui_story_5031_50311401_8_dialog_content = "¿Está seguro, señor?",
  ui_story_5031_50311401_9_dialog_content = "No debería dejarte solo...",
  ui_story_5031_50311401_10_dialog_content = "Hiciste tu trabajo. Debo enfrentar lo que sigue solo.",
  ui_story_5031_50311401_11_dialog_content = "...",
  ui_story_5031_50311401_12_dialog_content = "¿O no me crees, Patou?",
  ui_story_5031_50311401_13_dialog_content = "¡Ciertamente creo en ti! Sabes que eso no es lo que quise decir.",
  ui_story_5031_50311401_14_dialog_content = "Si lo haces, vete ahora. Solo arruinarás el plan quedándote aquí.",
  ui_story_5031_50311401_15_dialog_content = "No te preocupes. Todo está bajo mi control hasta ahora.",
  ui_story_5031_50311401_16_dialog_content = "Recuerda lo que dije... No entres sin importar lo que escuches.",
  ui_story_5031_50311401_17_dialog_content = "...Sí.",
  ui_story_5031_50311401_18_dialog_content = "Por favor cuídate.",
  ui_story_5031_50311401_19_dialog_content = "¡Elvis!",
  ui_story_5031_50311401_20_dialog_content = "¿Vaya? ¿No son Rainbow y Ciel sino Su Alteza y ustedes?",
  ui_story_5031_50311401_21_dialog_content = "Pero eso está bien. Llegas un poco más tarde de lo que pensaba.",
  ui_story_5031_50311401_22_dialog_content = "Todo estaba listo pero aún no apareciste, así que me preocupaba si esos hombres realmente te detendrían.",
  ui_story_5031_50311401_23_dialog_content = "¿Nos está esperando por la forma en que habló...?",
  ui_story_5031_50311401_24_dialog_content = "No veo a Patou. Me pregunto qué tiene bajo la manga.",
  ui_story_5031_50311401_25_dialog_content = "De todos modos, tengamos cuidado.",
  ui_story_5031_50311401_26_dialog_content = "Sí.",
  ui_story_5031_50311401_27_dialog_content = "¿Es ese... el núcleo de energía a su lado?",
  ui_story_5031_50311401_28_dialog_content = "Debería ser. Puedo sentir una energía fuerte e inusual en él.",
  ui_story_5031_50311401_29_dialog_content = "Pero, ¿cómo va a llevar algo tan grande con él?",
  ui_story_5031_50311401_30_dialog_content = "Escúchame, Elvis.",
  ui_story_5031_50311401_31_dialog_content = "No sé qué planeaste hacer con el núcleo de energía.",
  ui_story_5031_50311401_32_dialog_content = "Pero sé que tu objetivo final es proteger a la gente de Harbor City del síndrome de Modali.",
  ui_story_5031_50311401_33_dialog_content = "Sin embargo, lo que estás haciendo ahora solo pondrá en peligro a la ciudad.",
  ui_story_5031_50311401_34_dialog_content = "Cuando el núcleo de energía sale de su modo normal, se despertará...",
  ui_story_5031_50311401_35_dialog_content = "Su Guardián.",
  ui_story_5031_50311401_36_dialog_content = "...",
  ui_story_5031_50311401_37_dialog_content = "¿Sabes de eso?",
  ui_story_5031_50311401_38_dialog_content = "También encontrará la información que necesita, una vez que haya leído detenidamente todos los libros de este mundo.",
  ui_story_5031_50311401_39_dialog_content = "Arma robótica: Core Guardian.",
  ui_story_5031_50311401_40_dialog_content = "Un producto de civilizaciones antiguas, con poder suficiente para destruir una pequeña ciudad.",
  ui_story_5031_50311401_41_dialog_content = "Cuando el núcleo de energía falla, Core Guardian se activa.",
  ui_story_5031_50311401_42_dialog_content = "Si esta operación continúa, no solo hará que el Guardián ataque, sino que puede provocar la autodestrucción del núcleo.",
  ui_story_5031_50311401_43_dialog_content = "Es por eso que ustedes, la gente de True Order, nunca podrían tener en sus manos este núcleo de energía, ¿verdad?",
  ui_story_5031_50311401_44_dialog_content = "...",
  ui_story_5031_50311401_45_dialog_content = "¿Orden Verdadero...?",
  ui_story_5031_50311401_46_dialog_content = "¿Estás con True Order, Jeno?",
  ui_story_5031_50311401_47_dialog_content = "... Es una larga historia. De hecho, mi comprensión del núcleo provino de The True Order, pero eso no es importante.",
  ui_story_5031_50311401_48_dialog_content = "Dejemos a un lado el asunto con Jeno y True Order por ahora.",
  ui_story_5031_50311401_49_dialog_content = "Si sabes tanto al respecto, Elvis, ¿por qué seguirías haciendo algo que podría poner en peligro a la gente de Harbor City?",
  ui_story_5031_50311401_50_dialog_content = "¿Poner en peligro a la gente de Harbor City?",
  ui_story_5031_50311401_51_dialog_content = "No, no, Su Alteza, no soy como esos viejos nobles mimados en Lumopolis.",
  ui_story_5031_50311401_52_dialog_content = "Nunca jugaría con la vida de mi gente.",
  ui_story_5031_50311401_53_dialog_content = "Tengo mis razones para hacer esto.",
  ui_story_5031_50311401_54_dialog_content = "Pero no creo que llegues nunca a averiguarlo.",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5031_50311401_56_dialog_content = "¿Que es ese ruido? ¡Tan ruidoso y molesto!",
  ui_story_5031_50311401_57_dialog_content = "Vaya... ¿Qué hiciste, Elvis?",
  ui_story_5031_50311401_58_dialog_content = "Como todos los invitados están presentes, puedo poner el espectáculo en marcha.",
  ui_story_5031_50311401_59_dialog_content = "Admiro su carácter, Su Alteza, pero estoy más inclinado a hacer cualquier cosa por el futuro de Harbor City.",
  ui_story_5031_50311401_60_dialog_content = "Si quieres guardar rencor, que sea solo para mí.",
  ui_story_5031_50311401_61_dialog_content = "El sello ya no es estable, así que debo salvar la ciudad como pueda.",
  ui_story_5031_50311401_62_dialog_content = "¡Mira, la gema en su cetro está brillando!",
  ui_story_5031_50311401_63_dialog_content = "Esa joya...",
  ui_story_5031_50311401_64_dialog_content = "¡Está absorbiendo energía del núcleo!",
  ui_story_5031_50311401_65_dialog_content = "Ah, ¿incluso pudiste sentir eso, Caelestite?",
  ui_story_5031_50311401_66_dialog_content = "Bueno, supongo que eso significa que no puedo dejar a ninguno de ustedes con vida.",
  ui_story_5031_50311401_67_dialog_content = "Pero estaba planeando hacerlo, de todos modos.",
  ui_story_5031_50311401_68_dialog_content = "\"Actividad inusual detectada\".",
  ui_story_5031_50311401_69_dialog_content = "\"Autodefensa activada. En proceso de análisis del sistema\".",
  ui_story_5031_50311401_70_dialog_content = "¡Oye, ese enorme robot que cuelga debajo de ese gran bloque se está moviendo!",
  ui_story_5031_50311401_71_dialog_content = "Oh, lo peor ha pasado.",
  ui_story_5031_50311401_72_dialog_content = "El Guardián del Núcleo está a punto de ser despertado...",
  ui_story_5031_50311401_73_dialog_content = "Cuidado, chicos.",
  ui_story_5031_50311401_74_dialog_content = "\"Identificación de energía: Lumina\".",
  ui_story_5031_50311401_75_dialog_content = "\"Análisis: objetivos hostiles\".",
  ui_story_5031_50311401_76_dialog_content = "\"Conclusión: iniciar el modo de ataque\".",
  ui_story_5031_50311401_77_dialog_content = "¡Su energía se está amplificando!",
  ui_story_5031_50311401_78_dialog_content = "¡Ponte detrás de mí, Fia!",
  ui_story_5031_50311401_79_dialog_content = "¡Ah, okey!",
  ui_story_5031_50311402_1_dialog_content = "Vice, Jeno, atacaré por la parte trasera izquierda.",
  ui_story_5031_50311402_2_dialog_content = "¡Necesito que detengas el avance del Guardián del Núcleo!",
  ui_story_5031_50311402_3_dialog_content = "¡Entendido!",
  ui_story_5031_50311402_4_dialog_content = "Cuidado con el grupo de energía en su brazo derecho, Vice!",
  ui_story_5031_50311402_5_dialog_content = "¡Está a punto de atacar!",
  ui_story_5031_50311402_6_dialog_content = "¡Ok, lo tengo!",
  ui_story_5031_50311402_7_dialog_content = "¡Flor de hielo!",
  ui_story_5031_50311402_8_dialog_content = "\"Casco golpeado\".",
  ui_story_5031_50311402_9_dialog_content = "\"Comienza a evaluar el daño\".",
  ui_story_5031_50311402_10_dialog_content = "¡Vaya, el gran robot no se mueve!",
  ui_story_5031_50311402_11_dialog_content = "Eres increíble, Carleen!",
  ui_story_5031_50311402_12_dialog_content = "No exactamente. Su energía sigue funcionando normalmente en su interior.",
  ui_story_5031_50311402_13_dialog_content = "Eres muy competente, incluso superando mis expectativas.",
  ui_story_5031_50311402_14_dialog_content = "Aunque he escuchado mucho sobre lo que PlayerName puede hacer, pero ver para creer.",
  ui_story_5031_50311402_15_dialog_content = "Es una pena, sin embargo...",
  ui_story_5031_50311402_16_dialog_content = "Que tu esfuerzo será en vano.",
  ui_story_5031_50311402_17_dialog_content = "\"Evaluación completa, sin daños graves\".",
  ui_story_5031_50311402_18_dialog_content = "\"Actualiza los datos del enemigo, ajusta la producción de daños\".",
  ui_story_5031_50311402_19_dialog_content = "Qué es esto...?",
  ui_story_5031_50311402_20_dialog_content = "Carleen, está acumulando energía masiva en el cofre. ¡Pato!",
  ui_story_5031_50311402_21_dialog_content = "¡Uh!",
  ui_story_5031_50311402_22_dialog_content = "Eso estuvo cerca.",
  ui_story_5031_50311402_23_dialog_content = "¿Estás bien, Carleen?",
  ui_story_5031_50311402_24_dialog_content = "Estoy bien. Gracias a la advertencia de PlayerName, es solo un rasguño.",
  ui_story_5031_50311402_25_dialog_content = "Bien, porque el poder que acaba de desatar es horrible...",
  ui_story_5031_50311402_26_dialog_content = "La mitad de las paredes de la habitación se derritieron.",
  ui_story_5031_50311402_27_dialog_content = "El poder de las armas de las civilizaciones antiguas es realmente temible.",
  ui_story_5031_50311402_28_dialog_content = "Rodeémoslo y encontremos un punto débil.",
  ui_story_5031_50311402_29_dialog_content = "Sí. Ten cuidado también.",
  ui_story_5031_50311402_30_dialog_content = "Ya sabes, ¿has notado algo extraño?",
  ui_story_5031_50311402_31_dialog_content = "¿Qué es?",
  ui_story_5031_50311402_32_dialog_content = "¿Por qué el Guardián solo nos ataca a nosotros?",
  ui_story_5031_50311402_33_dialog_content = "Elvis obviamente está parado justo al lado del núcleo y extrayendo su energía.",
  ui_story_5031_50311402_34_dialog_content = "Eso es cierto.",
  ui_story_5031_50311402_35_dialog_content = "Porque el Guardián...",
  ui_story_5031_50311402_36_dialog_content = "...",
  ui_story_5031_50311402_37_dialog_content = "¿Sabes por qué, Jeno?",
  ui_story_5031_50311402_38_dialog_content = "No nada.",
  ui_story_5031_50311402_39_dialog_content = "¿Por qué no terminaste lo que estabas diciendo?",
  ui_story_5031_50311402_40_dialog_content = "¿Todavía te preocupas por mis sentimientos incluso ahora?",
  ui_story_5031_50311402_41_dialog_content = "Sigues siendo el mismo, Jeno.",
  ui_story_5031_50311402_42_dialog_content = "Está bien. Ya estoy acostumbrado, puedes escupirlo.",
  ui_story_5031_50311402_43_dialog_content = "Elvis...",
  ui_story_5031_50311402_44_dialog_content = "Diles que es porque el Guardián reconoce a los enemigos a través de Lumina.",
  ui_story_5031_50311402_45_dialog_content = "Pero para mí, con toda mi Lumina absorbida...",
  ui_story_5031_50311402_46_dialog_content = "No soy más que un cadáver.",
  ui_story_5031_50311402_47_dialog_content = "¿L-Lumina absorbida?",
  ui_story_5031_50311402_48_dialog_content = "Eso explica por qué no pude sentir a Lumina en Elvis.",
  ui_story_5031_50311402_49_dialog_content = "Pensé que era por su enfermedad.",
  ui_story_5031_50311402_50_dialog_content = "Es al revés. La pérdida de Lumina condujo a la enfermedad.",
  ui_story_5031_50311402_51_dialog_content = "El síndrome de Modali es en realidad una enfermedad que resulta de la pérdida de Lumina durante un largo período de tiempo.",
  ui_story_5031_50311402_52_dialog_content = "Las víctimas viven con el dolor de Lumina saliendo constantemente de sus cuerpos. Los casos severos incluso...",
  ui_story_5031_50311402_53_dialog_content = "Entonces, ¿la solución es obtener el núcleo de energía?",
  ui_story_5031_50311402_54_dialog_content = "No estoy seguro de los detalles, pero esa es la esencia de su plan.",
  ui_story_5031_50311402_55_dialog_content = "Escúchame, Elvis.",
  ui_story_5031_50311402_56_dialog_content = "Incluso si obtienes el núcleo de energía, no puedes controlar al Guardián.",
  ui_story_5031_50311402_57_dialog_content = "Después de que bajemos, centrará su atención en ti y en Harbour City.",
  ui_story_5031_50311402_58_dialog_content = "Tiene que haber otra manera. Podemos...",
  ui_story_5031_50311402_59_dialog_content = "No hay otra manera, Jeno.",
  ui_story_5031_50311402_60_dialog_content = "He estado buscando una solución desde que vi por primera vez a mi gente morir a causa de la enfermedad.",
  ui_story_5031_50311402_61_dialog_content = "Probé todas las opciones posibles a lo largo de los años, incluso cuando las posibilidades de éxito eran escasas o nulas.",
  ui_story_5031_50311402_62_dialog_content = "Pero todo lo que queda es decepción y un cuerpo en declive.",
  ui_story_5031_50311402_63_dialog_content = "Debo terminarlo aunque se me acabe el tiempo.",
  ui_story_5031_50311402_64_dialog_content = "Pero...",
  ui_story_5031_50311402_65_dialog_content = "Deja de hablar, Jeno. ¡El Guardián viene hacia ti!",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5031_50311402_67_dialog_content = "Jeno!",
  ui_story_5031_50311402_68_dialog_content = "Tos, tos.",
  ui_story_5031_50311402_69_dialog_content = "Estoy bien.",
  ui_story_5031_50311402_70_dialog_content = "Gracias a Dios, eso me asustó mucho...",
  ui_story_5031_50311402_71_dialog_content = "¡Eso es bajo, Elvis!",
  ui_story_5031_50311402_72_dialog_content = "¡Distrajiste a Jeno con el pretexto de una charla!",
  ui_story_5031_50311402_73_dialog_content = "No, entendió mal, señorita Fia.",
  ui_story_5031_50311402_74_dialog_content = "Esa no es mi intención. Al contrario, los necesito a todos...",
  ui_story_5031_50311402_75_dialog_content = "Nos necesitas para mantener ocupado al Guardián mientras absorbes la energía, ¿verdad?",
  ui_story_5031_50311402_76_dialog_content = "Muy astuto de su parte, Su Alteza.",
  ui_story_5031_50311402_77_dialog_content = "En cuanto al Guardián del Núcleo, puedo revelar cierta información dado que estás muy preocupado por la gente de Harbor City.",
  ui_story_5031_50311402_78_dialog_content = "La diferencia entre True Order y yo es que yo tengo algo que ellos no tienen.",
  ui_story_5031_50311402_79_dialog_content = "Puedo unir el núcleo de energía a mi sangre y controlarlo.",
  ui_story_5031_50311402_80_dialog_content = "Una vez que termine de absorber el núcleo de energía, el Guardián también me obedecerá.",
  ui_story_5031_50311402_81_dialog_content = "Por lo tanto, puedes descansar en paz con este barco en el fondo del océano, sabiendo que mi gente está a salvo.",
  ui_story_5031_50311402_82_dialog_content = "Ha tomado la decisión de matarnos entonces, Laird Elvis.",
  ui_story_5031_50311402_83_dialog_content = "Lo siento, pero no puedo arriesgarme a que el Consejo de Ancianos lo descubra.",
  ui_story_5031_50311402_84_dialog_content = "Bueno, supongo que no tenemos nada más que discutir.",
  ui_story_5031_50311402_85_dialog_content = "Pero ya sea que tengas buenas intenciones, no dejaré que lastimes a mis amigos.",
  ui_story_5031_50311402_86_dialog_content = "Jeno, las ilusiones que conjuras llevaban tu Lumina, ¿verdad?",
  ui_story_5031_50311402_87_dialog_content = "En seguida.",
  ui_story_5031_50311402_88_dialog_content = "¿Cuántas imágenes de los soldados puedes proyectar?",
  ui_story_5031_50311402_89_dialog_content = "Probablemente podría controlar más de diez al mismo tiempo.",
  ui_story_5031_50311402_90_dialog_content = "Tienes un plan, Carleen?",
  ui_story_5031_50311402_91_dialog_content = "Me gustaría que tu, Vice, y Jeno, para mantener ocupado al Guardián por mí.",
  ui_story_5031_50311402_92_dialog_content = "Devolver el núcleo de energía a la normalidad es el requisito previo para desactivar el Guardián.",
  ui_story_5031_50311402_93_dialog_content = "Eso debería aclarar nuestro objetivo.",
  ui_story_5031_50311402_94_dialog_content = "Evitaré que Elvis absorba el núcleo de energía.",
  ui_story_5031_50311501_1_dialog_content = "¡Torrente rápido!",
  ui_story_5031_50311501_2_dialog_content = "Bien, tenemos la atención del Guardián.",
  ui_story_5031_50311501_3_dialog_content = "¡Ahora, Carleen!",
  ui_story_5031_50311501_4_dialog_content = "Hazlo rápido. No puedo mantener todas estas ilusiones por mucho tiempo.",
  ui_story_5031_50311501_5_dialog_content = "¡Muy bien, gracias!",
  ui_story_5031_50311501_6_dialog_content = "Tose, tose.",
  ui_story_5031_50311501_7_dialog_content = "No esperaría menos de ti, señora. Carleen.",
  ui_story_5031_50311501_8_dialog_content = "Ni siquiera conocía a Jeno un día y aún así descubrió cómo usar su poder para distraer al Guardián.",
  ui_story_5031_50311501_9_dialog_content = "Una mente altamente táctica, junto con las habilidades de PlayerName...",
  ui_story_5031_50311501_10_dialog_content = "Me alegro de no haberte subestimado desde el principio.",
  ui_story_5031_50311501_11_dialog_content = "¡Uh!",
  ui_story_5031_50311501_12_dialog_content = "Qué ocurre, Carleen?!",
  ui_story_5031_50311501_13_dialog_content = "Yo... no puedo... moverme...",
  ui_story_5031_50311501_14_dialog_content = "Mi poder se está agotando...",
  ui_story_5031_50311501_15_dialog_content = "¡Quédate aquí y no te vayas a ningún lado, Fia!",
  ui_story_5031_50311501_16_dialog_content = "¡Pero ese robot te va a matar, PlayerName!",
  ui_story_5031_50311501_17_dialog_content = "Oye, ¿cómo es que el robot no reaccionó en absoluto?",
  ui_story_5031_50311501_18_dialog_content = "¡Carleen!",
  ui_story_5031_50311501_19_dialog_content = "PlayerName...",
  ui_story_5031_50311501_20_dialog_content = "(La lúmina en Carleen se está agotando rápido!)",
  ui_story_5031_50311501_21_dialog_content = "Rayos...",
  ui_story_5031_50311501_22_dialog_content = "<size=45>¡¿Qué has hecho, Elvis?!</size>",
  ui_story_5031_50311501_23_dialog_content = "No se siente bien que te quiten a Lumina, ¿verdad?",
  ui_story_5031_50311501_24_dialog_content = "Como contingencia, puse un <color=#FFB400>precauciones de seguridad</color> sobre Su Alteza.",
  ui_story_5031_50311501_25_dialog_content = "¿Precauciones de seguridad? ¿Cuándo?",
  ui_story_5031_50311501_26_dialog_content = "¿Es el traje que lleva puesto?",
  ui_story_5031_50311501_27_dialog_content = "Correcto.",
  ui_story_5031_50311501_28_dialog_content = "Cuando me preguntaste cómo entrar en la cabina, supe que podría llegar a esto.",
  ui_story_5031_50311501_29_dialog_content = "El atuendo de ella fue especialmente diseñado.",
  ui_story_5031_50311501_30_dialog_content = "Cuando se activa el <color=#FFB400>Lumothread</color>, se adherirá al usuario y absorberá rápidamente Lumina.",
  ui_story_5031_50311501_31_dialog_content = "Por lo tanto, es mejor que no use Lumina en absoluto.",
  ui_story_5031_50311501_32_dialog_content = "¡Por qué tú...!",
  ui_story_5031_50311501_33_dialog_content = "Lo siento... lo subestimé...",
  ui_story_5031_50311501_34_dialog_content = "No es tu culpa. Debería...",
  ui_story_5031_50311501_35_dialog_content = "¡Cuidado, Jeno!",
  ui_story_5031_50311501_36_dialog_content = "¿Eh?",
  ui_story_5031_50311501_37_dialog_content = "¿Estás bien, Jeno?",
  ui_story_5031_50311501_38_dialog_content = "¡Ay! Mi brazo...",
  ui_story_5031_50311501_39_dialog_content = "No puedo moverlo.",
  ui_story_5031_50311501_40_dialog_content = "No te muevas. ¡Estas sangrando!",
  ui_story_5031_50311501_41_dialog_content = "\"Enemigo herido. Modo de persecución activado\".",
  ui_story_5031_50311501_42_dialog_content = "El Guardián está cargando hacia ti, Vice!",
  ui_story_5031_50311501_43_dialog_content = "¡Oh no, es demasiado rápido!",
  ui_story_5031_50311501_44_dialog_content = "¡Es demasiado tarde para disparar!",
  ui_story_5031_50311501_45_dialog_content = "Detente... ¡Uf!",
  ui_story_5031_50311501_46_dialog_content = "¿J-Jeno?",
  ui_story_5031_50311501_47_dialog_content = "...",
  ui_story_5031_50311501_48_dialog_content = "Él murió.",
  ui_story_5031_50311501_49_dialog_content = "Oh no, ¿qué vamos a hacer ahora?",
  ui_story_5031_50311501_50_dialog_content = "¡Oh, sí, todavía tengo esto!",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5031_50311501_52_dialog_content = "\"?\"",
  ui_story_5031_50311501_53_dialog_content = "¡Entendido! ¡Afortunadamente todavía tengo la pistola que me dio el maestro!",
  ui_story_5031_50311501_54_dialog_content = "¿Qué te parece eso, robot?",
  ui_story_5031_50311501_55_dialog_content = "\"Bajo ataque desconocido, daño sufrido: 0\".",
  ui_story_5031_50311501_56_dialog_content = "\"El objetivo no gastó Lumina. Análisis: Eliminación prioritaria\".",
  ui_story_5031_50311501_57_dialog_content = "¡Waaaah! ¿Por qué me está cargando ahora?",
  ui_story_5031_50311501_58_dialog_content = "¡Ahhh!",
  ui_story_5031_50311501_59_dialog_content = "¡Fia!",
  ui_story_5031_50311501_60_dialog_content = "...",
  ui_story_5031_50311501_61_dialog_content = "Estamos acabados si esto continúa.",
  ui_story_5031_50311501_62_dialog_content = "Soy el único que queda ahora, así que no entres en pánico.",
  ui_story_5031_50311501_63_dialog_content = "Tengo que detener a Elvis primero para detener al Guardián.",
  ui_story_5031_50311501_64_dialog_content = "...",
  ui_story_5031_50311501_65_dialog_content = "Acuéstate un rato, Carleen, y no vuelvas a usar Lumina.",
  ui_story_5031_50311501_66_dialog_content = "¿Qué estás haciendo, PlayerName?",
  ui_story_5031_50311501_67_dialog_content = "Voy a detener a Elvis.",
  ui_story_5031_50311501_68_dialog_content = "Supongo que es hora de que ponga el entrenamiento de Sinsa y otros para buen uso.",
  ui_story_5031_50311501_69_dialog_content = "Pero...",
  ui_story_5031_50311501_70_dialog_content = "Relájate, Carleen.",
  ui_story_5031_50311501_71_dialog_content = "Puede que no tenga a Lumina, pero contra un hombre enfermizo como Elvis...",
  ui_story_5031_50311501_72_dialog_content = "no perderé",
  ui_story_5031_50311501_73_dialog_content = "Ten mucho cuidado.",
  ui_story_5031_50311501_74_dialog_content = "Discurso muy conmovedor. Impresionante.",
  ui_story_5031_50311501_75_dialog_content = "Pero llamar a alguien un hombre enfermizo es increíblemente grosero.",
  ui_story_5031_50311501_76_dialog_content = "Déjate de tonterías.",
  ui_story_5031_50311501_77_dialog_content = "Cállate y-",
  ui_story_5031_50311501_78_dialog_content = "¡Bajar!",
  ui_story_5031_50311501_79_dialog_content = "Je...",
  ui_story_5031_50311501_80_dialog_content = "<size=45>¡PlayerName! ¡Cuidado!</size>",
  ui_story_5031_50311501_81_dialog_content = "\"Cambiando la prioridad del comando, sobrescribiendo el comando predeterminado. Cambiar de objetivo\".",
  ui_story_5031_50311501_82_dialog_content = "¡¡Puaj!!",
  ui_story_5031_50311501_83_dialog_content = "¡PlayerName!",
  ui_story_5031_50311501_84_dialog_content = "De ninguna manera...",
  ui_story_5031_50311501_85_dialog_content = "Esto es imposible...",
  ui_story_5031_50311501_86_dialog_content = "Estuviste tan cerca, PlayerName.",
  ui_story_5031_50311501_87_dialog_content = "Lástima que he absorbido toda la energía del núcleo.",
  ui_story_5031_50311501_88_dialog_content = "Ahora, tengo el control del Core Guardian.",
  ui_story_5031_50311501_89_dialog_content = "De lo contrario, alguien sin Lumina como tú sería realmente una molestia.",
  ui_story_5031_50311501_90_dialog_content = "\"Comando de mayor prioridad actualizado, cambiado al modo de control manual\".",
  ui_story_5031_50311501_91_dialog_content = "\"Sistema de autodefensa apagado\".",
  ui_story_5031_50311501_92_dialog_content = "(¡Eso duele!)",
  ui_story_5031_50311501_93_dialog_content = "(No puedo sentir mis piernas.)",
  ui_story_5031_50311501_94_dialog_content = "Déjame ver, el único que aún puede moverse es...",
  ui_story_5031_50311501_95_dialog_content = "Señorita Vice, Supongo.",
  ui_story_5031_50311501_96_dialog_content = "Ve a acabar con ella y luego nos dirigiremos a la siguiente ubicación.",
  ui_story_5031_50311501_97_dialog_content = "\"Nuevo comando recibido. Cambiando de objetivo\".",
  ui_story_5031_50311501_98_dialog_content = "(No, Vice!)",
  ui_story_5031_50311501_99_dialog_content = "<size=33>Correr, Vice...</size>",
  ui_story_5031_50311501_100_dialog_content = "¿Vaya? Todavía es capaz de ponerse de pie, ¿eh?",
  ui_story_5031_50311501_101_dialog_content = "<size=33>¿Eh?</size>",
  ui_story_5031_50311501_102_dialog_content = "Te respeto por ser aún capaz de tal fuerza en estas circunstancias.",
  ui_story_5031_50311501_103_dialog_content = "Sin embargo, y perdóname por mi franqueza, esto solo acelerará tu desaparición.",
  ui_story_5031_50311501_104_dialog_content = "<size=33>Carleen...?</size>",
  ui_story_5031_50311501_105_dialog_content = "Todo es por mi culpa...",
  ui_story_5031_50311501_106_dialog_content = "¿Su Alteza?",
  ui_story_5031_50311501_107_dialog_content = "Es todo... por mi culpa...",
  ui_story_5031_50311501_108_dialog_content = "Ah, está delirando por perder a Lumina...",
  ui_story_5031_50311501_109_dialog_content = "Muy encomiable cómo sigues tratando de proteger a tus amigos cuando estás en un estado tan lamentable.",
  ui_story_5031_50311501_110_dialog_content = "\"Nuevo objetivo detectado. ¿Comenzar ataque?\"",
  ui_story_5031_50311501_111_dialog_content = "No hay necesidad. Ella no es una amenaza.",
  ui_story_5031_50311501_112_dialog_content = "<size=45>Para, Carleen!</size>",
  ui_story_5031_50311501_113_dialog_content = "(Maldita sea, ni siquiera puedo hacer un sonido.)",
  ui_story_5031_50311501_114_dialog_content = "(Tengo que hacer algo...)",
  ui_story_5031_50311501_115_option_content = "¡Control forzado!",
  ui_story_5031_50311501_116_dialog_content = "¿Qué estás preparado para hacer si un día, tu ciudad es atacada por Eclipsite?",
  ui_story_5031_50311501_117_dialog_content = "(Es eso... Schwartz?)",
  ui_story_5031_50311501_118_dialog_content = "(¿Es esto un sueño? ¿Es porque Carleen está a punto de perder el conocimiento?)",
  ui_story_5031_50311501_119_dialog_content = "Inmediatamente reuniría un ejército para defenderlo.",
  ui_story_5031_50311501_120_dialog_content = "¿Y si una fuerza de Eclipsite logra atravesar tu defensa?",
  ui_story_5031_50311501_121_dialog_content = "Me apresuraría con las tropas de reserva.",
  ui_story_5031_50311501_122_dialog_content = "Y luego los Eclipsites que han estado cavando un túnel subterráneo emergen en el centro de la ciudad.",
  ui_story_5031_50311501_123_dialog_content = "Ordenaría a los soldados que se mantuvieran firmes, y luego yo...",
  ui_story_5031_50311501_124_dialog_content = "Ahora la muralla está empezando a caer.",
  ui_story_5031_50311501_125_dialog_content = "...",
  ui_story_5031_50311501_126_dialog_content = "Derrotaría a todos los Eclipsites.",
  ui_story_5031_50311501_127_dialog_content = "Tú y yo sabemos que no pueden ser aniquilados.",
  ui_story_5031_50311501_128_dialog_content = "...",
  ui_story_5031_50311501_129_dialog_content = "Me parece que todavía estás lejos de convertirte en un excelente gobernante...",
  ui_story_5031_50311501_130_dialog_content = "Lumopolis no puede depender de ti todavía.",
  ui_story_5031_50311501_131_dialog_content = "P-padre?",
  ui_story_5031_50311501_132_dialog_content = "Te envié a Northland para estudiar bajo Bethlehem, pero no veo evidencia de progreso.",
  ui_story_5031_50311501_133_dialog_content = "Tu fuerza es insuficiente y te falta poder mental.",
  ui_story_5031_50311501_134_dialog_content = "Por eso perdiste a tus amigos.",
  ui_story_5031_50311501_135_dialog_content = "Se lastimaron, incluso murieron, todo por su culpa, Su Alteza.",
  ui_story_5031_50311501_136_dialog_content = "Yo, yo...",
  ui_story_5031_50311501_137_dialog_content = "confié en ti, y seguí tu plan de batalla, Carleen.",
  ui_story_5031_50311501_138_dialog_content = "Pero, ¿qué me trajo eso?",
  ui_story_5031_50311501_139_dialog_content = "PlayerName y yo estamos a punto de morir por tu culpa.",
  ui_story_5031_50311501_140_dialog_content = "Lo siento, Vice...",
  ui_story_5031_50311501_141_dialog_content = "Enfoque, Carleen, eso no es Vice!",
  ui_story_5031_50311501_142_dialog_content = "Es eso...",
  ui_story_5031_50311501_143_dialog_content = "¿PlayerName?",
  ui_story_5031_50311501_144_dialog_content = "¡Si, soy yo!",
  ui_story_5031_50311501_145_dialog_content = "Lo siento por no haber notado cuánto conflicto interno estabas experimentando, Carleen.",
  ui_story_5031_50311501_146_dialog_content = "Pero Vice nunca diría eso. ¡Lo que estás viendo no es real sino ilusiones!",
  ui_story_5031_50311501_147_dialog_content = "¿Estás tratando de huir de tus responsabilidades?",
  ui_story_5031_50311501_148_dialog_content = "Qué pena. Sigue diciendo cómo protegerás a los demás cuando en realidad eres débil.",
  ui_story_5031_50311501_149_dialog_content = "No estás hecho para gobernar.",
  ui_story_5031_50311501_150_dialog_content = "Yo...",
  ui_story_5031_50311501_151_dialog_content = "Escúchame, Carleen.",
  ui_story_5031_50311501_152_dialog_content = "¡No tienes que soportar el peso de ser un gobernante todo el tiempo!",
  ui_story_5031_50311501_153_dialog_content = "para mi y Vice, estás Carleen y solo Carleen!",
  ui_story_5031_50311501_154_dialog_content = "¿Mmm?",
  ui_story_5031_50311501_154X1_dialog_content = "¿Recuerdas esa cosa? Vice dijo, Carleen?",
  ui_story_5031_50311501_154X2_dialog_content = "¡No debes ceder a tu obsesión!",
  ui_story_5031_50311501_154X3_dialog_content = "Mi obsesion...",
  ui_story_5031_50311501_154X4_dialog_content = "Yo estaba en un sueño tan grande durante el proceso. Pensé que nunca me despertaría.",
  ui_story_5031_50311501_154X5_dialog_content = "Seguía pensando en mi antiguo yo, con miedo de perderme si me relajaba aunque sea por un segundo.",
  ui_story_5031_50311501_154X6_dialog_content = "También vi muchas cosas maravillosas, como si estuviera allí.",
  ui_story_5031_50311501_154X7_dialog_content = "Esas ilusiones se sentían tan reales, como una prueba para mí.",
  ui_story_5031_50311501_154X8_dialog_content = "Por suerte, me aferré a un destello de conciencia y lo conservé hasta el final.",
  ui_story_5031_50311501_154X9_dialog_content = "¿Destello? Recuerdo que lo mencionaste. ¿Qué era?",
  ui_story_5031_50311501_154X10_dialog_content = "Um... Pensé en las cosas divertidas que hice contigo y PlayerName.",
  ui_story_5031_50311501_154X11_dialog_content = "Y antes de que me diera cuenta, hubo silencio dentro de mí.",
  ui_story_5031_50311501_154X12_dialog_content = "Sí, Carleen, no te rindas y no te pierdas!",
  ui_story_5031_50311501_155_dialog_content = "Luchamos juntos y nos retiramos juntos.",
  ui_story_5031_50311501_156_dialog_content = "Siempre nos cubriremos las espaldas.",
  ui_story_5031_50311501_157_dialog_content = "No te hacemos responsable cuando estamos en problemas.",
  ui_story_5031_50311501_158_dialog_content = "No tienes que protegernos a todos tú solo.",
  ui_story_5031_50311501_159_dialog_content = "¡Deberíamos trabajar en equipo y enfrentar los problemas como equipo!",
  ui_story_5031_50311501_160_dialog_content = "PlayerName...",
  ui_story_5031_50311501_161_dialog_content = "Pase lo que pase, Vice ¡y nunca NUNCA te culparía!",
  ui_story_5031_50311501_162_dialog_content = "Así que cálmate, Carleen! ¡No te dejes engañar por las ilusiones!",
  ui_story_5031_50311501_163_dialog_content = "El Real Vice no se rindió y sigue luchando por nosotros.",
  ui_story_5031_50311501_164_dialog_content = "¡Ella te necesita!",
  ui_story_5031_50311501_165_dialog_content = "...",
  ui_story_5031_50311501_166_dialog_content = "Tienes razón, PlayerName.",
  ui_story_5031_50311501_167_dialog_content = "Mis amigos todavía están peleando, ¿cómo puedo perder el tiempo engañándome a mí mismo?",
  ui_story_5031_50311501_168_dialog_content = "Entonces, ¿vas a pasar por alto el error que cometiste?",
  ui_story_5031_50311501_169_dialog_content = "Es obvio que tu subestimación e incompetencia...",
  ui_story_5031_50311501_170_dialog_content = "Llevó a la situación actual.",
  ui_story_5031_50311501_171_dialog_content = "Sí, pero no seré prisionero de mis propias decisiones, correctas o incorrectas.",
  ui_story_5031_50311501_172_dialog_content = "...",
  ui_story_5031_50311501_173_dialog_content = "Porque eso no tiene sentido. Si cometo un error...",
  ui_story_5031_50311501_174_dialog_content = "Me esforzaré por rectificarlo.",
  ui_story_5031_50311501_175_dialog_content = "Si así es como definiste el \"camino del gobernante\"...",
  ui_story_5031_50311501_176_dialog_content = "Espero que permanezca firme en esa creencia.",
  ui_story_5031_50311501_176X1_dialog_content = "Lo haré.",
  ui_story_5031_50311501_176X2_dialog_content = "Porque yo...",
  ui_story_5031_50311501_176X3_dialog_content = "He encontrado algo a lo que puedo aferrarme.",
  ui_story_5031_50311501_177_dialog_content = "Ah, la imagen es—",
  ui_story_5031_50311501_178_dialog_content = "Lamento haberte hecho esperar, Vice.",
  ui_story_5031_50311501_179_dialog_content = "¡Carleen!",
  ui_story_5031_50311501_180_dialog_content = "\"Advertencia: Lumina masiva detectada, nivel de amenaza alto\".",
  ui_story_5031_50311501_181_dialog_content = "\"Eliminar objetivo inmediatamente\".",
  ui_story_5031_50311501_182_dialog_content = "Resplandor espléndido!",
  ui_story_5031_50311501_183_dialog_content = "¿Qué estás pensando?",
  ui_story_5031_50311501_184_dialog_content = "Pero el <color=#FFB400>lumothread</color> ¿Todavía está absorbiendo su Lumina?",
  ui_story_5031_50311501_185_dialog_content = "Carleen se está bañando en Lumina!",
  ui_story_5031_50311501_186_dialog_content = "¿Que esta pasando aqui?",
  ui_story_5031_50311501_187_dialog_content = "Las dudas y la ansiedad innecesarias solo servirán para restarle valor.",
  ui_story_5031_50311501_188_dialog_content = "Una batalla cambia constantemente. Uno debe concentrarse en lo que se está desarrollando, no en el miedo interno.",
  ui_story_5031_50311501_189_dialog_content = "Ahora pelearé la batalla contigo, Vice.",
  ui_story_5031_50311501_190_dialog_content = "¿Estás bien físicamente, Carleen?",
  ui_story_5031_50311501_191_dialog_content = "No sé por qué, pero siento una energía ininterrumpida.",
  ui_story_5031_50311501_192_dialog_content = "De todos modos, solo tengo un objetivo en este momento...",
  ui_story_5031_50311501_193_dialog_content = "Y eso es derrotar al enemigo contigo.",
  ui_story_5031_50311501_194_dialog_content = "¡Correcto!",
  ui_story_5031_50311501_195_dialog_content = "\"Advertencia: Lumina masiva detectada, nivel de amenaza muy alto.\"",
  ui_story_5031_50311501_196_dialog_content = "\"Habilitando el modo Showdown.\"",
  ui_story_5031_50311502_1_dialog_content = "\"Advertencia... Daños en el casco superiores al 70 %\".",
  ui_story_5031_50311502_2_dialog_content = "\"Brazo derecho desconectado y no se puede reparar automáticamente\".",
  ui_story_5031_50311502_3_dialog_content = "¿Estás aguantando bien, Vice?",
  ui_story_5031_50311502_4_dialog_content = "Sí. ¡La supresión de largo alcance no me va a gastar demasiada energía!",
  ui_story_5031_50311502_5_dialog_content = "Bien, concentremos el fuego a su derecha.",
  ui_story_5031_50311502_6_dialog_content = "El brazo derecho está hacia abajo, por lo que afectará su ataque y defensa.",
  ui_story_5031_50311502_7_dialog_content = "¡Entendido!",
  ui_story_5031_50311502_8_dialog_content = "Debo decir que superó mis expectativas, Carleen.",
  ui_story_5031_50311502_9_dialog_content = "Admiro eso, incluso si estamos en lados opuestos.",
  ui_story_5031_50311502_10_dialog_content = "Sin embargo, tengo razones para no fallar.",
  ui_story_5031_50311502_11_dialog_content = "Por lo tanto, discúlpeme por no quedarme a ver el final de esta actuación.",
  ui_story_5031_50311502_12_dialog_content = "¡No irás a ninguna parte, Elvis!",
  ui_story_5031_50311502_13_dialog_content = "Detenerlos.",
  ui_story_5031_50311502_14_dialog_content = "Estar atento, Vice, ¡no le des la espalda al Guardián!",
  ui_story_5031_50311502_15_dialog_content = "¡Arrgh!",
  ui_story_5031_50311502_16_dialog_content = "...",
  ui_story_5031_50311502_17_dialog_content = "Ratas, se escapó.",
  ui_story_5031_50311502_18_dialog_content = "Está bien. Lo resolveremos cuando terminemos aquí.",
  ui_story_5031_50311502_19_dialog_content = "Estás en lo correcto.",
  ui_story_5031_50311502_20_dialog_content = "Ahora, el problema del Guardián.",
  ui_story_5031_50311502_21_dialog_content = "Entonces, deberíamos... ¿Hmm?",
  ui_story_5031_50311502_22_dialog_content = "Qué es, Carleen?",
  ui_story_5031_50311502_23_dialog_content = "(¿La Lumina de Carleen se volvió más fuerte?)",
  ui_story_5031_50311502_24_dialog_content = "Este atuendo ya no está absorbiendo mi Lumina.",
  ui_story_5031_50311502_25_dialog_content = "¿Es porque Elvis se fue?",
  ui_story_5031_50311502_26_dialog_content = "Eso explicaría por qué estabas bien en eso antes.",
  ui_story_5031_50311502_27_dialog_content = "Supongo que Elvis tiene que mantenerlo en persona para que funcione.",
  ui_story_5031_50311502_28_dialog_content = "En ese caso, no tengo que contenerme.",
  ui_story_5031_50311502_29_dialog_content = "Démosle el golpe final a esta estúpida e indiscriminada máquina antes de que arruine el barco.",
  ui_story_5031_50311502_30_dialog_content = "¡Sí! Jeno es mejor estar agradecido una vez que se despierta.",
  ui_story_5031_50311502_31_dialog_content = "¿Me estás desafiando?",
  ui_story_5031_50311502_32_dialog_content = "El laird se reunirá con el dueño del circo y nadie puede abordar el barco.",
  ui_story_5031_50311502_33_dialog_content = "Solo estamos cumpliendo órdenes, así que por favor comprenda.",
  ui_story_5031_50311502_34_dialog_content = "Todos ustedes no se ven como si estuvieran mirando las instalaciones.",
  ui_story_5031_50311502_35_dialog_content = "Sin mencionar los sonidos de explosiones provenientes de la nave.",
  ui_story_5031_50311502_36_dialog_content = "¿Reunión? Más como un rencor para mí.",
  ui_story_5031_50311502_37_dialog_content = "¿No estás preocupado por tu amo? Es demasiado escuálido para luchar contra Jeno.",
  ui_story_5031_50311502_38_dialog_content = "Por favor, vete.",
  ui_story_5031_50311502_39_dialog_content = "¿Vaya? ¿Me vas a hacer?",
  ui_story_5031_50311502_40_dialog_content = "Entonces será mejor que estés preparado para las consecuencias, ya que lo reportaré a...",
  ui_story_5031_50311502_41_dialog_content = "No seas insolente, Patou.",
  ui_story_5031_50311502_42_dialog_content = "¡Terrateniente!",
  ui_story_5031_50311502_43_dialog_content = "Oh, ¿no es el Laird Elvis? ¿Se acabó la reunión?",
  ui_story_5031_50311502_44_dialog_content = "Lamento haberte hecho esperar, Matthieu, pero tenía un asunto importante con un viejo amigo.",
  ui_story_5031_50311502_45_dialog_content = "Patou y sus hombres solo siguen órdenes. Por favor, perdónalos.",
  ui_story_5031_50311502_46_dialog_content = "Ya veo. May abordamos el barco ahora?",
  ui_story_5031_50311502_47_dialog_content = "Por favor siéntase libre.",
  ui_story_5031_50311502_48_dialog_content = "<size=33>¿Vamos a dejarlo entrar así, señor?</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>No importa De todos modos, la nave detonará pronto.</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>Preferiría ir a...</size>",
  ui_story_5031_50311502_51_dialog_content = "Un momento, Laird Elvis.",
  ui_story_5031_50311502_52_dialog_content = "¿Qué es?",
  ui_story_5031_50311502_53_dialog_content = "¿Viste a Su Alteza? Carleen ¿a bordo?",
  ui_story_5031_50311502_54_dialog_content = "No. ¿Estaban ella y sus amigos a bordo?",
  ui_story_5031_50311502_55_dialog_content = "Eso es extraño. He estado esperando desde que terminó la celebración pero nunca vi a Su Alteza.",
  ui_story_5031_50311502_56_dialog_content = "Ella no desembarcó ni te vio, así que ¿por qué se quedaría en el barco?",
  ui_story_5031_50311502_57_dialog_content = "Tal vez se esté despidiendo de los nuevos amigos que hizo.",
  ui_story_5031_50311502_58_dialog_content = "Ya que probablemente se conocieron bastante bien en el transcurso del día.",
  ui_story_5031_50311502_59_dialog_content = "Fui asignado a Su Alteza como guardaespaldas. Así que básicamente la cuidé durante todo el día, temiendo que pudiera lastimarse.",
  ui_story_5031_50311502_60_dialog_content = "Creo que no tuvo mucho que ver con la gente del circo, según mis observaciones.",
  ui_story_5031_50311502_61_dialog_content = "pero señorita Vice y la señorita Ciel son viejos amigos.",
  ui_story_5031_50311502_62_dialog_content = "Y PlayerName se lleva de maravilla con Miss Rainbow...",
  ui_story_5031_50311502_63_dialog_content = "Permítame intervenir, Laird Elvis.",
  ui_story_5031_50311502_64_dialog_content = "¿Si?",
  ui_story_5031_50311502_65_dialog_content = "Creo que no mencioné a nadie más.",
  ui_story_5031_50311502_66_dialog_content = "Si no la viste, ¿cómo puedes estar tan seguro de que está con ellos?",
  ui_story_5031_50311502_67_dialog_content = "...",
  ui_story_5031_50311502_68_dialog_content = "Eso es porque los cuatro son cercanos y siempre pasan el rato juntos.",
  ui_story_5031_50311502_69_dialog_content = "Pareces saber mucho por conocerlos solo por un día.",
  ui_story_5031_50311502_70_dialog_content = "Estoy cerca de ese compañero mío muy envuelto, pero él no está aquí.",
  ui_story_5031_50311502_71_dialog_content = "...",
  ui_story_5031_50311502_72_dialog_content = "Patou.",
  ui_story_5031_50311502_73_dialog_content = "Sí, señor.",
  ui_story_5031_50311502_74_dialog_content = "Veo que estamos entrando en la fase \"sin testigos\".",
  ui_story_5031_50311502_75_dialog_content = "No es una mala pose de lucha allí.",
  ui_story_5031_50311502_76_dialog_content = "Pero es posible que no sepa que debajo del exterior helado de nuestro Señor de la Ciudad, él es extremadamente protector con su hija.",
  ui_story_5031_50311502_77_dialog_content = "Entonces, ¿crees que yo, como su guardaespaldas, podría ser tratado fácilmente?",
  ui_story_5031_50311502_78_dialog_content = "¡Es hora de hacer tu entrada, Loewe!",
  ui_story_5031_50311502_79_dialog_content = "¿Qué?",
  ui_story_5031_50311502_80_dialog_content = "Hablas demasiado, Matthieu.",
  ui_story_5031_50311502_81_dialog_content = "Ese es tu negocio ¿cómo?",
  ui_story_5031_50311502_82_dialog_content = "¿Solo dos de ustedes?",
  ui_story_5031_50311502_83_dialog_content = "¿Esperas pelear contra mis hombres solo con ustedes dos?",
  ui_story_5031_50311502_84_dialog_content = "Mal, solo uno.",
  ui_story_5031_50311502_85_dialog_content = "Tienes esto, Loewe. Voy a ir a un rescate.",
  ui_story_5031_50311502_86_dialog_content = "...",
  ui_story_5031_50311502_87_dialog_content = "Eso no será necesario.",
  ui_story_5031_50311502_88_dialog_content = "Oye, eso suena como...",
  ui_story_5031_50311502_89_dialog_content = "¡¿Qué?!",
  ui_story_5031_50311502_90_dialog_content = "Gracias por mantener ocupado a Elvis.",
  ui_story_5031_50311502_91_dialog_content = "Eso es muy útil.",
  ui_story_5031_50311502_92_dialog_content = "¡Su Alteza! ¡Es genial verte todavía con vida!",
  ui_story_5031_50311502_93_dialog_content = "¡Imposible!",
  ui_story_5031_50311502_94_dialog_content = "¿Dónde está el Guardián? ¿Cómo es que el barco no explotó?",
  ui_story_5031_50311502_95_dialog_content = "Carleen golpéalo con toda tu potencia, y ahora es un montón de chatarra.",
  ui_story_5031_50311502_96_dialog_content = "¡Aunque tengo que decir que ese robot fue construido fantásticamente!",
  ui_story_5031_50311502_97_dialog_content = "Lástima que dejó de moverse cuando llegamos allí.",
  ui_story_5031_50311502_98_dialog_content = "Está bien. Todavía es bueno para la investigación.",
  ui_story_5031_50311502_99_dialog_content = "¡Estás en lo correcto!",
  ui_story_5031_50311502_100_dialog_content = "¿Pero cómo? ¿Cómo podrías seguir ejerciendo tal poder bajo restricción?",
  ui_story_5031_50311502_101_dialog_content = "Espera, ¿el Lumothread dejó de absorberse?",
  ui_story_5031_50311502_102_dialog_content = "¿No controlas eso, Elvis?",
  ui_story_5031_50311502_103_dialog_content = "¿No me digas que alcanzó su capacidad máxima?",
  ui_story_5031_50311502_104_dialog_content = "Eso no puede ser... ¡El atuendo debería ser capaz de absorber Lumina de dos, incluso tres Aurorianos!",
  ui_story_5031_50311502_105_dialog_content = "Eso no es importante.",
  ui_story_5031_50311502_106_dialog_content = "Lo que pasa es que tu plan fracasó, Elvis.",
  ui_story_5031_50311502_107_dialog_content = "Abandonar. No puedes escaparte ahora.",
  ui_story_5031_50311502_108_dialog_content = "No, no... ¡No puedo fallar! ¡No debo fallar!",
  ui_story_5031_50311502_109_dialog_content = "los <color=#FFB400>sello</color> pronto...",
  ui_story_5031_50311502_110_dialog_content = "Patou!",
  ui_story_5031_50311502_111_dialog_content = "¡Sí señor!",
  ui_story_5031_50311502_112_dialog_content = "La resistencia no tiene sentido.",
  ui_story_5031_50311502_113_dialog_content = "Urgh...",
  ui_story_5031_50311502_114_dialog_content = "¡Ahora, Laird!",
  ui_story_5031_50311502_115_dialog_content = "Seré el hazmerreír si te escapas. ¿Crees que dejaré que eso suceda?",
  ui_story_5031_50311502_116_dialog_content = "¡Uh!",
  ui_story_5031_50311502_117_dialog_content = "¡Vamos! Solo lo \"empujé\", ¿y ya terminó?",
  ui_story_5031_50311502_118_dialog_content = "¿Qué tan débil es el hombre?",
  ui_story_5031_50311502_119_dialog_content = "¡Terrateniente!",
  ui_story_5031_50311502_120_dialog_content = "Soy contra quien estás peleando.",
  ui_story_5031_50311502_121_dialog_content = "¡Rayos!",
  ui_story_5031_50311502_122_dialog_content = "Ninguno de ustedes se escapa.",
  ui_story_5031_50311601_1_dialog_content = "Tienes a Ciel, ¿verdad, Rainbow?",
  ui_story_5031_50311601_2_dialog_content = "¡Sí! ¡Cuidaré bien de ella, oficial!",
  ui_story_5031_50311601_3_dialog_content = "¡Frimet también te ayudará!",
  ui_story_5031_50311601_4_dialog_content = "¡Y Subli!",
  ui_story_5031_50311601_5_dialog_content = "M-Merylt también.",
  ui_story_5031_50311601_6_dialog_content = "¡Oh muy bien!",
  ui_story_5031_50311601_7_dialog_content = "gracias oficial Gronru, por dejarme quedar.",
  ui_story_5031_50311601_8_dialog_content = "Está todo bien. Últimamente no pasa mucho.",
  ui_story_5031_50311601_9_dialog_content = "Puedes tomártelo con calma aquí, Ciel.",
  ui_story_5031_50311601_10_dialog_content = "... ¿En serio? ¿Simplemente dejar ese núcleo de energía así?",
  ui_story_5031_50311601_11_dialog_content = "Oh, es solo un pequeño núcleo de energía. No es precioso para Illumina.",
  ui_story_5031_50311601_12_dialog_content = "Aunque es muy similar al núcleo de energía, es peor en muchos aspectos y la pureza de la energía emitida no es buena.",
  ui_story_5031_50311601_13_dialog_content = "Además, después del manejo sin sentido por parte de ese laird, es básicamente un pedazo de chatarra.",
  ui_story_5031_50311601_14_dialog_content = "Hablando de valor de investigación... Tal vez te sirva de inspiración para mejorar tu \"Styx\".",
  ui_story_5031_50311601_15_dialog_content = "Maldita sea, no he estudiado esta nave lo suficiente todavía. ¡Por qué debo ser recordado en este momento!",
  ui_story_5031_50311601_15X1_dialog_content = "¡Ciel, debes prestar especial atención al sistema de transmisión cuando les arregles el núcleo!",
  ui_story_5031_50311601_15X2_dialog_content = "¡Toma buenas notas! ¡Los leeré cuando vuelvas!",
  ui_story_5031_50311601_15X3_dialog_content = "Yo, entiendo...",
  ui_story_5031_50311601_16_dialog_content = "Oye, ¿de qué estás susurrando?",
  ui_story_5031_50311601_17_dialog_content = "¡Yo también quiero escucharlo!",
  ui_story_5031_50311601_18_dialog_content = "Uh, si fuera por nosotros, no tendrían que susurrar...",
  ui_story_5031_50311601_19_dialog_content = "Hmm, eso tenía sentido.",
  ui_story_5031_50311601_20_dialog_content = "Olvídalo entonces.",
  ui_story_5031_50311601_21_dialog_content = "Ahí tienes",
  ui_story_5031_50311601_22_dialog_content = "¿Qué dijiste?",
  ui_story_5031_50311601_23_dialog_content = "¿Quién está haciendo todo ese ruido?",
  ui_story_5031_50311601_24_dialog_content = "¿Está seguro, Su Alteza?",
  ui_story_5031_50311601_25_dialog_content = "¿De verdad te quedas aquí para administrar el lugar?",
  ui_story_5031_50311601_26_dialog_content = "En seguida.",
  ui_story_5031_50311601_27_dialog_content = "Pero Elvis tomó las armas contra ti. ¡Eso es traición!",
  ui_story_5031_50311601_28_dialog_content = "Caballero Schwartz ¡No soportaría eso!",
  ui_story_5031_50311601_29_dialog_content = "Es exactamente por eso que necesito la ayuda de ustedes dos.",
  ui_story_5031_50311601_30_dialog_content = "¿Por qué tengo un mal presentimiento sobre esto?",
  ui_story_5031_50311601_31_dialog_content = "Espero que usted y el Sr. Loewe mantengan en secreto partes de este incidente.",
  ui_story_5031_50311601_32_dialog_content = "Además, me gustaría que ambos se quedaran conmigo en Harbor City por un tiempo.",
  ui_story_5031_50311601_33_dialog_content = "Me temo que no.",
  ui_story_5031_50311601_34_dialog_content = "Lo siento, Su Alteza, vino directamente de Lady Irridon.",
  ui_story_5031_50311601_35_dialog_content = "Estoy obligado a honrar eso.",
  ui_story_5031_50311601_36_dialog_content = "...",
  ui_story_5031_50311601_37_dialog_content = "Lo entiendo, Sr. Matthieu. No cuestiono tu lealtad en absoluto.",
  ui_story_5031_50311601_38_dialog_content = "Pero prefiero no causarles problemas a usted ya Loewe.",
  ui_story_5031_50311601_39_dialog_content = "Después de todo, recibí 17 puntos por mis heridas, sin mencionar la incapacidad de usar Lumina por el agotamiento.",
  ui_story_5031_50311601_40_dialog_content = "Eso podría ser problemático si Lady Irridon o señor Schwartz infórmate al respecto.",
  ui_story_5031_50311601_41_dialog_content = "Seguro pero...",
  ui_story_5031_50311601_42_dialog_content = "Por supuesto, se debió a mi propia negligencia, y ahora estoy bien.",
  ui_story_5031_50311601_43_dialog_content = "El médico también me dijo que debería recuperarme por completo, con el tiempo.",
  ui_story_5031_50311601_44_dialog_content = "Entonces, si desea evitar acusaciones innecesarias, estaré encantado de cumplir.",
  ui_story_5031_50311601_45_dialog_content = "...",
  ui_story_5031_50311601_46_dialog_content = "¿Por qué?",
  ui_story_5031_50311601_47_dialog_content = "¿Que por que?",
  ui_story_5031_50311601_48_dialog_content = "¿Por qué insiste en quedarse atrás, Su Alteza?",
  ui_story_5031_50311601_49_dialog_content = "¿Por qué encubrir la transgresión de Elvis?",
  ui_story_5031_50311601_50_dialog_content = "Porque, ante todo, lo hizo por el bien de la gente de Harbor City.",
  ui_story_5031_50311601_51_dialog_content = "En segundo lugar, Harbor City siempre ha sido un vasallo de Lumopolis, y Laird Elvis incluso estudió en Lumopolis antes.",
  ui_story_5031_50311601_52_dialog_content = "Sin embargo, no solicitó ayuda a Lumopolis, sino que buscó una solución por su cuenta e incluso se la ocultó a Lumopolis.",
  ui_story_5031_50311601_53_dialog_content = "¿Por qué crees que es?",
  ui_story_5031_50311601_54_dialog_content = "...",
  ui_story_5031_50311601_55_dialog_content = "Es porque no creía que Lumopolis pudiera o quisiera ayudarlo.",
  ui_story_5031_50311601_56_dialog_content = "Un laird que no está dispuesto a confiar en nosotros es la causa principal.",
  ui_story_5031_50311601_57_dialog_content = "No podemos garantizar que el próximo laird no haga la misma elección que hizo Elvis.",
  ui_story_5031_50311601_58_dialog_content = "Si no llegamos a la raíz del problema y simplemente lo ignoramos, se hará más profundo.",
  ui_story_5031_50311601_59_dialog_content = "Por lo tanto, me gustaría averiguar la verdadera intención de Elvis.",
  ui_story_5031_50311601_60_dialog_content = "Y arrancarlo de raíz antes de que se entierre demasiado.",
  ui_story_5031_50311601_61_dialog_content = "...",
  ui_story_5031_50311601_62_dialog_content = "Je, para mí, siempre has sido nada más que una princesa ingenua y protegida.",
  ui_story_5031_50311601_63_dialog_content = "¿...?",
  ui_story_5031_50311601_64_dialog_content = "Pero...",
  ui_story_5031_50311601_65_dialog_content = "Tengo que admitir que fue un discurso sensato.",
  ui_story_5031_50311601_66_dialog_content = "¿No es así, Loewe?",
  ui_story_5031_50311601_67_dialog_content = "En seguida.",
  ui_story_5031_50311601_68_dialog_content = "Así que...",
  ui_story_5031_50311601_69_dialog_content = "¡Sin embargo!",
  ui_story_5031_50311601_70_dialog_content = "...",
  ui_story_5031_50311601_71_dialog_content = "Nunca le mentiríamos a Lady Irridon.",
  ui_story_5031_50311601_72_dialog_content = "Por lo tanto, aún le informaremos todo a través de Courier Union esta noche.",
  ui_story_5031_50311601_73_dialog_content = "¿Dónde está ese Courier Union de nuevo?",
  ui_story_5031_50311601_74_dialog_content = "¿Q-Qué fue eso? ¿Loewe?",
  ui_story_5031_50311601_75_dialog_content = "...",
  ui_story_5031_50311601_76_dialog_content = "White Pearl Street, junto al restaurante Lucky Garden.",
  ui_story_5031_50311601_77_dialog_content = "Ese es.",
  ui_story_5031_50311601_78_dialog_content = "Depende de ti, entonces.",
  ui_story_5031_50311601_79_dialog_content = "...",
  ui_story_5031_50311601_80_dialog_content = "¿Por qué no lo haces?",
  ui_story_5031_50311601_81_dialog_content = "Porque todavía tengo que asegurar la vecindad.",
  ui_story_5031_50311601_82_dialog_content = "Una situación tan peligrosa requiere una persona más fuerte en general para garantizar la seguridad de Su Alteza.",
  ui_story_5031_50311601_83_dialog_content = "...",
  ui_story_5031_50311601_84_dialog_content = "¿Qué, quieres pelear conmigo?",
  ui_story_5031_50311601_85_dialog_content = "Vamos a hacerlo.",
  ui_story_5031_50311601_86_dialog_content = "Vamos, pongámoslo en ese lote de allí. Te golpearé hoy.",
  ui_story_5031_50311601_87_dialog_content = "En tus sueños.",
  ui_story_5031_50311601_88_dialog_content = "...",
  ui_story_5031_50311601_89_dialog_content = "¿Has llegado a un acuerdo, Carleen?",
  ui_story_5031_50311601_90_dialog_content = "¿Cómo es que empezaron a pelear?",
  ui_story_5031_50311601_91_dialog_content = "Así son. Discuten y pelean, pero nunca se separan.",
  ui_story_5031_50311601_92_dialog_content = "En cuanto al informe del incidente...",
  ui_story_5031_50311601_93_dialog_content = "Creo que tenemos un entendimiento neutral.",
  ui_story_5031_50311601_94_dialog_content = "¡Eso es genial!",
  ui_story_5031_50311601_95_dialog_content = "Pueden parecer extraños, pero resultaron ser sorprendentemente agradables.",
  ui_story_5031_50311601_96_dialog_content = "¿Estás seguro de que ustedes dos no están heridos?",
  ui_story_5031_50311601_97_dialog_content = "No tienes que hacerme compañía aquí.",
  ui_story_5031_50311601_98_dialog_content = "¿Cómo podemos dejarte solo en tu condición actual?",
  ui_story_5031_50311601_98X1_dialog_content = "Tu Lumina irradiaba como si estuviera fuera de control, y te desmayaste poco después de que escapamos...",
  ui_story_5031_50311601_98X2_dialog_content = "¡Eso realmente nos asustó!",
  ui_story_5031_50311601_98X3_dialog_content = "Mis disculpas por haberte preocupado.",
  ui_story_5031_50311601_98X4_dialog_content = "¿Cómo lograste el gran avance de repente? Carleen? Eso fue increíble.",
  ui_story_5031_50311601_98X5_dialog_content = "En ese momento... sentí lo que describiste, Vice.",
  ui_story_5031_50311601_98X6_dialog_content = "Conocí todas esas ansiedades que me han estado molestando.",
  ui_story_5031_50311601_98X7_dialog_content = "Eran tan reales, autoritarios y sofocantes.",
  ui_story_5031_50311601_98X8_dialog_content = "Oh, Carleen...",
  ui_story_5031_50311601_98X9_dialog_content = "Afortunadamente, PlayerName se puso en contacto con mi mente y me sacó del abismo.",
  ui_story_5031_50311601_98X10_dialog_content = "Me hizo darme cuenta de que ustedes dos son el \"algo\" que necesitaba...",
  ui_story_5031_50311601_98X11_dialog_content = "Gracias, PlayerName. Y usted también, Vice.",
  ui_story_5031_50311601_98X12_dialog_content = "Lo hiciste por tu cuenta Carleen. Superaste el equipaje emocional y dominaste tu propia mente.",
  ui_story_5031_50311601_98X13_dialog_content = "Eso es cierto, ¡pero PlayerName siempre tiene lista una sopa de pollo verbal para el alma!",
  ui_story_5031_50311601_98X14_dialog_content = "¡Lo cual es algo maravilloso!",
  ui_story_5031_50311601_98X15_dialog_content = "E-¿Es real?",
  ui_story_5031_50311601_98X16_dialog_content = "Solo hablo de lo que siento.",
  ui_story_5031_50311601_98X17_dialog_content = "Eso es muy bueno en sí mismo.",
  ui_story_5031_50311601_98X18_dialog_content = "En seguida.",
  ui_story_5031_50311601_98X19_dialog_content = "Pero deberías tomártelo con calma por un tiempo, Carleen. No apresure su recuperación.",
  ui_story_5031_50311601_98X20_dialog_content = "Puede desmayarse debido a las fugas de Lumina si aún no está aclimatado.",
  ui_story_5031_50311601_98X21_dialog_content = "¡Así que no te fuerces con el nuevo poder antes de que te hayas recuperado!",
  ui_story_5031_50311601_98X22_dialog_content = "Eso suena como algo Carleen haría.",
  ui_story_5031_50311601_98X23_dialog_content = "Esta bien, lo tengo.",
  ui_story_5031_50311601_98X24_dialog_content = "Me cuidaré. Está seguro.",
  ui_story_5031_50311601_98X25_dialog_content = "En cuanto al avance, buscaré la mejor manera con Vice después de que esté completamente recuperado.",
  ui_story_5031_50311601_98X26_dialog_content = "¡No hay problema!",
  ui_story_5031_50311601_99_dialog_content = "No tienes que preocuparte por nosotros. PlayerName y yo somos duros, ¿verdad?",
  ui_story_5031_50311601_100_dialog_content = "Sí. Puedes apoyarte en nosotros de vez en cuando, Carleen.",
  ui_story_5031_50311601_101_dialog_content = "¡Así que déjanos cuidarte esta vez!",
  ui_story_5031_50311601_102_dialog_content = "Bueno, muchas gracias.",
  ui_story_5031_50311601_103_dialog_content = "¡No hay problema!",
  ui_story_5031_50311601_104_dialog_content = "¿Qué debemos hacer a continuación?",
  ui_story_5031_50311601_105_dialog_content = "Dado el gran lío, hay muchas cosas con las que lidiar en Harbor City.",
  ui_story_5031_50311601_106_dialog_content = "Carleen estará muy ocupado como laird interino.",
  ui_story_5031_50311601_107_dialog_content = "Por cierto. Pero antes de que eso sea oficial, tengo a alguien a quien quiero ver.",
